const QUESTIONS = [{"id": "gen-con-001", "part": "general", "topic": "Contracts", "q": "Which statement best describes a contract?", "a": ["A document that takes effect only once it is recorded at the registry", "An agreement that becomes binding only after it is notarized", "An agreement between competent parties that the law will enforce", "Any written promise, as long as at least one of the parties signed it"], "c": 2, "why": "A contract is a legally enforceable agreement between competent parties. Notarizing or recording (the tempting distractors) affect proof and public notice, not whether a contract exists.", "trap": "familiar-term", "difficulty": 1, "outline": "V.A.1"}, {"id": "gen-con-002", "part": "general", "topic": "Contracts", "q": "An owner never signs anything, but knowingly lets a broker advertise and show her house and thanks him for each showing. A court would most likely say a contract was created by", "a": ["Express written agreement", "Implication from the parties' conduct", "Novation", "Operation of the Statute of Frauds"], "c": 1, "why": "An implied contract arises from conduct rather than stated terms. It is not express, because nothing was stated or signed, and novation means replacing a contract, not creating one.", "trap": "familiar-term", "difficulty": 2, "outline": "V.A.1"}, {"id": "gen-con-003", "part": "general", "topic": "Contracts", "q": "A buyer and seller signed a purchase and sale agreement last week, and closing is set for next month. Right now the buyer holds", "a": ["A freehold life estate", "Equitable title", "A leasehold estate", "Legal title"], "c": 1, "why": "While the sale contract is pending, the buyer has equitable title, an enforceable right to acquire the property. Legal title does not pass until the deed is delivered and accepted at closing.", "trap": "familiar-term", "difficulty": 2, "outline": "V.A.11"}, {"id": "gen-con-004", "part": "general", "topic": "Contracts", "q": "Each of the following is an essential element of a valid contract EXCEPT", "a": ["Consideration given by each side", "A legal purpose for the agreement", "Acknowledgment before a notary", "Offer and acceptance by the parties"], "c": 2, "why": "Offer and acceptance, consideration, legal purpose and competent parties are essential. Acknowledgment is needed to record a deed, not to make a contract valid.", "trap": "familiar-term", "difficulty": 1, "outline": "V.A.2"}, {"id": "gen-con-005", "part": "general", "topic": "Contracts", "q": "Which statement about consideration in a real estate contract is correct?", "a": ["A deposit of at least 10% of the price is required for it to exist", "Anything of value, including a promise, can serve, even if worth less than market value", "It must be paid in cash at the time the agreement is signed", "It must equal the property's fair market value to be valid"], "c": 1, "why": "Courts ask whether something of value was bargained for, not whether it was a fair amount; mutual promises are enough. Cash at signing is common but not required.", "trap": "too-simple", "difficulty": 1, "outline": "V.A.2"}, {"id": "gen-con-006", "part": "general", "topic": "Contracts", "q": "A landlord and tenant sign a lease for a storefront that both know will be used for an activity the law prohibits. The lease is", "a": ["Valid but unenforceable", "Voidable by the tenant", "Valid until either party objects", "Void"], "c": 3, "why": "A contract for an illegal purpose lacks an essential element, so it is void and has no legal effect. Voidable describes a contract that is valid until a protected party chooses to cancel it.", "trap": "familiar-term", "difficulty": 1, "outline": "V.A.2"}, {"id": "gen-con-007", "part": "general", "topic": "Contracts", "q": "A 17-year-old signs a purchase and sale agreement to buy a condominium from an adult seller. The agreement is", "a": ["Void from the start", "Voidable by either party", "Voidable by the seller only", "Voidable by the minor only"], "c": 3, "why": "A minor's contract is valid but may be disaffirmed by the minor. The adult seller cannot use the buyer's age to escape the deal.", "trap": "opposite", "difficulty": 2, "outline": "V.A.2"}, {"id": "gen-con-008", "part": "general", "topic": "Contracts", "q": "A signed purchase and sale agreement describes the property only as 'the seller's lot on Birch Lane.' The seller owns three lots on Birch Lane. What is the biggest problem with this agreement?", "a": ["The property is not described with enough certainty to be enforced", "It lacks consideration, so the agreement is void from the start", "Nothing, because naming the street identifies the property well enough", "It was never notarized, so it cannot be enforced in court"], "c": 0, "why": "A real estate contract must identify the property clearly enough that it can be located. Naming the street is not enough when the seller owns three lots there; consideration and notarization are not the issue.", "trap": "too-simple", "difficulty": 3, "outline": "V.A.2"}, {"id": "gen-con-009", "part": "general", "topic": "Contracts", "q": "The Statute of Frauds requires that", "a": ["Contracts for the sale of an interest in land be in writing to be enforceable", "A breach-of-contract lawsuit be filed within a set number of years", "Every real estate contract be recorded at the registry to be valid", "Every real estate document be signed before a notary public"], "c": 0, "why": "The Statute of Frauds is about which contracts must be written. The deadline to file a lawsuit is the statute of limitations, a similar-sounding but different law.", "trap": "familiar-term", "difficulty": 1, "outline": "V.A.3"}, {"id": "gen-con-010", "part": "general", "topic": "Contracts", "q": "A seller and buyer shake hands on an oral agreement for the sale of a house at an agreed price. Neither signs anything. The agreement is best described as", "a": ["Voidable by the buyer", "Valid and enforceable", "Void", "Unenforceable"], "c": 3, "why": "An oral contract to sell land may contain every element of a contract, but a court will not enforce it under the Statute of Frauds. Void means no contract existed at all, which is not the case here.", "trap": "familiar-term", "difficulty": 2, "outline": "V.A.3"}, {"id": "gen-con-011", "part": "general", "topic": "Contracts", "q": "Which agreement generally must be in writing to be enforceable?", "a": ["A homeowner's promise to pay a painter $3,000 to paint the house next week", "An agreement among roommates to split the electric bill", "A promise to pay a neighbor for shoveling snow this winter", "A lease with a term of two years"], "c": 3, "why": "Leases longer than one year involve an interest in land and fall under the Statute of Frauds. The other agreements are short service or personal arrangements that can be oral.", "trap": "wrong-context", "difficulty": 2, "outline": "V.A.3"}, {"id": "gen-con-012", "part": "general", "topic": "Contracts", "q": "An offer to purchase becomes a binding contract when", "a": ["The buyer's deposit check has been cashed and has cleared", "The signed offer is delivered to the listing broker's office", "The offeree's acceptance is communicated to the offeror", "The offeree signs it, even if the offeror has not been told"], "c": 2, "why": "Acceptance has to be communicated to create a contract. Signing without communicating it leaves the offeror free to withdraw.", "trap": "too-simple", "difficulty": 1, "outline": "V.A.4"}, {"id": "gen-con-013", "part": "general", "topic": "Contracts", "q": "A buyer offers $400,000. The seller signs the offer but changes the price to $410,000. The buyer has not responded. What is the status of the buyer's $400,000 offer?", "a": ["It remains open, so the seller can still accept $400,000", "It became a binding contract at $400,000", "It became a binding contract at $410,000", "It was terminated by the seller's counteroffer"], "c": 3, "why": "Changing any term is a counteroffer, which rejects and ends the original offer. The seller cannot later go back and accept $400,000 unless the buyer offers it again.", "trap": "too-simple", "difficulty": 2, "outline": "V.A.4"}, {"id": "gen-con-014", "part": "general", "topic": "Contracts", "q": "A buyer's offer says it stays open until Friday at 5 p.m. On Thursday morning the buyer emails the listing broker withdrawing the offer. That afternoon the seller signs an acceptance. Which is true?", "a": ["A contract exists, because the Friday deadline had not passed", "No contract exists, because the offer was withdrawn before acceptance", "A contract exists, because the seller signed before Friday", "The buyer must pay the seller damages for withdrawing early"], "c": 1, "why": "An offeror may revoke at any time before acceptance unless the offeree paid to keep it open (an option). A stated deadline is the latest the offer can be accepted, not a promise to keep it open.", "trap": "opposite", "difficulty": 2, "outline": "V.A.4"}, {"id": "gen-con-015", "part": "general", "topic": "Contracts", "q": "Each of the following would terminate an offer EXCEPT", "a": ["The passing of the deadline stated in the offer", "The seller's counteroffer at a higher purchase price", "The seller asking a question about the buyer's financing", "Death of the buyer-offeror before the seller accepts"], "c": 2, "why": "A simple question or inquiry does not change any terms, so it is not a counteroffer and does not end the offer. Death of the offeror, a counteroffer and a lapsed deadline all terminate it.", "trap": "familiar-term", "difficulty": 3, "outline": "V.A.4"}, {"id": "gen-con-016", "part": "general", "topic": "Contracts", "q": "A seller refused to close. The buyer waited several years without acting while the seller, believing the matter was over, built an addition. The buyer then sued for specific performance. Although the legal filing deadline had not expired, the court denied relief because of the unreasonable delay. This is the doctrine of", "a": ["Statute of Frauds", "Statute of limitations", "Laches", "Accord and satisfaction"], "c": 2, "why": "Laches lets a court refuse relief when unreasonable delay harmed the other side, even inside the statutory deadline. The statute of limitations is the fixed legal deadline itself, which had not run.", "trap": "familiar-term", "difficulty": 3, "outline": "V.A.5"}, {"id": "gen-con-017", "part": "general", "topic": "Contracts", "q": "A buyer signs a purchase agreement only because the seller threatened to harm him if he did not. The contract is", "a": ["Void, so neither party can enforce it", "Voidable by the seller", "Voidable by the buyer", "Valid and binding on both parties"], "c": 2, "why": "A contract signed under duress lacks free consent, so the victim may choose to cancel or keep it. The party who made the threat has no right to cancel.", "trap": "opposite", "difficulty": 2, "outline": "V.A.6"}, {"id": "gen-con-018", "part": "general", "topic": "Contracts", "q": "After signing a purchase and sale agreement, a buyer learns the seller lied when asked whether the basement had ever flooded. Closing has not yet occurred. Which best describes the buyer's position?", "a": ["It is void, so neither the buyer nor the seller is bound by it", "It is voidable, so the buyer may choose to rescind or to go forward", "The buyer must close anyway, because the agreement was already signed", "The buyer can recover damages, but only after closing occurs"], "c": 1, "why": "Fraud makes a contract voidable at the option of the injured party. It is not automatically void, so the choice to cancel or continue belongs to the buyer.", "trap": "familiar-term", "difficulty": 3, "outline": "V.A.6"}, {"id": "gen-con-019", "part": "general", "topic": "Contracts", "q": "An owner tells several brokers, 'I will pay a fee to whichever of you brings me a buyer.' None of the brokers promises to do anything. This arrangement is a", "a": ["Executed contract", "Bilateral contract", "Unilateral contract", "Void contract"], "c": 2, "why": "Only the owner has promised, and payment is earned by performing an act, which makes it unilateral. A bilateral contract needs promises from both sides.", "trap": "familiar-term", "difficulty": 2, "outline": "V.A.7"}, {"id": "gen-con-020", "part": "general", "topic": "Contracts", "q": "In an option agreement, the party who has the right, but not the obligation, to buy the property is the", "a": ["Optionor", "Grantor", "Vendor", "Optionee"], "c": 3, "why": "The optionee pays for the right to decide. The optionor is the owner who is bound to sell if the optionee exercises the option.", "trap": "familiar-term", "difficulty": 1, "outline": "V.A.8"}, {"id": "gen-con-021", "part": "general", "topic": "Contracts", "q": "An owner receives $2,000 for a 90-day option to buy her land at a set price. Sixty days later a different buyer offers more, and the owner wants to sell to that buyer. Which is true?", "a": ["The owner must keep the offer open to the optionee for the full 90 days", "The optionee must now buy or lose the right", "The owner may cancel by returning the $2,000", "The owner may sell to the new buyer if she gives written notice"], "c": 0, "why": "The option money buys an irrevocable offer for the stated period, so the owner is bound and the optionee alone decides. Refunding the money does not let the owner back out.", "trap": "opposite", "difficulty": 2, "outline": "V.A.8"}, {"id": "gen-con-022", "part": "general", "topic": "Contracts", "q": "A tenant's lease gives her a right of first refusal on the building. The landlord has received no offers and has no plans to sell. The tenant wants to buy now. Which is true?", "a": ["She can force a sale, but only after giving the landlord 30 days' notice", "She cannot force a sale; her right arises only if the landlord decides to sell", "She can force a sale at fair market value whenever she chooses to buy", "She can force a sale at the price stated in the lease at any time"], "c": 1, "why": "A right of first refusal lets the holder match an offer once the owner decides to sell. Forcing a sale at a set price on the holder's own timing describes an option, not a right of first refusal.", "trap": "wrong-context", "difficulty": 3, "outline": "V.A.8"}, {"id": "gen-con-023", "part": "general", "topic": "Contracts", "q": "A seller signs a buyer's offer with no changes. At 3 p.m. the listing agent emails the signed copy to the buyer's agent. At 4 p.m. the buyer calls to withdraw the offer. Which is true?", "a": ["The buyer may withdraw, because the buyer had not yet read the email", "The buyer may withdraw, because no deposit had been paid yet", "A binding contract exists, because acceptance was communicated first", "No contract exists until both parties sign a purchase and sale agreement"], "c": 2, "why": "Once an unconditional acceptance is communicated, the offer can no longer be revoked. Delivery to the buyer's agent counts as communication, whether or not the buyer had read it yet.", "trap": "opposite", "difficulty": 2, "outline": "V.A.9"}, {"id": "gen-con-024", "part": "general", "topic": "Contracts", "q": "Under federal and most state electronic-transaction laws, an electronic signature on a purchase agreement", "a": ["Is valid only if a paper copy is later signed in ink by both parties", "Generally has the same legal effect as a handwritten signature", "Cannot be used for contracts to buy or sell real estate", "Is valid only for leases with a term of one year or less"], "c": 1, "why": "Laws like the federal ESIGN Act and state electronic-transaction acts give electronic signatures the same effect as ink. The main risks are identity and security, not legal validity.", "trap": "opposite", "difficulty": 1, "outline": "V.A.10"}, {"id": "gen-con-025", "part": "general", "topic": "Contracts", "q": "A buyer assigns his purchase and sale agreement, which does not prohibit assignment, to his sister. The seller never agrees to release him. If the sister fails to close, the original buyer", "a": ["Has no liability unless he signed the deed", "Is fully released, because the contract was assigned", "Remains secondarily liable to the seller", "Is released, because the seller did not object"], "c": 2, "why": "In an assignment the assignee becomes primarily liable but the assignor stays secondarily liable. A full release of the original party happens only through a novation.", "trap": "familiar-term", "difficulty": 2, "outline": "V.A.11"}, {"id": "gen-con-026", "part": "general", "topic": "Contracts", "q": "A court orders a seller who refused to close to convey the property as promised. This remedy is", "a": ["Specific performance", "Liquidated damages", "Rescission", "Compensatory damages"], "c": 0, "why": "Specific performance forces the breaching party to do what the contract requires, and courts allow it for land because every parcel is unique. The other remedies give money or undo the contract.", "trap": "familiar-term", "difficulty": 1, "outline": "V.A.12"}, {"id": "gen-con-027", "part": "general", "topic": "Contracts", "q": "A purchase agreement states that if the buyer defaults, the seller may keep the deposit as liquidated damages and this is the seller's sole remedy. The buyer walks away without a legal excuse. The seller may", "a": ["Sue for specific performance to force the buyer to buy", "Keep the deposit and also sue for the full purchase price", "Keep the deposit, but not sue the buyer for additional damages", "Keep the deposit only if a court first approves it"], "c": 2, "why": "When the contract makes the deposit the seller's sole remedy, the parties agreed in advance on what the seller recovers. Suing for more would ignore that agreed limit.", "trap": "too-simple", "difficulty": 2, "outline": "V.A.12"}, {"id": "gen-con-028", "part": "general", "topic": "Contracts", "q": "A seller refuses to close because prices have risen sharply since the contract was signed. The buyer was ready to close and still wants this particular home. The buyer's best remedy is to", "a": ["Sue for specific performance", "Keep the earnest money as liquidated damages", "Ask the listing broker to sign the deed for the seller", "Sue for nominal damages"], "c": 0, "why": "Specific performance gets the buyer the unique property itself. Keeping the deposit as liquidated damages is the seller's remedy when a buyer defaults, not the buyer's.", "trap": "wrong-context", "difficulty": 3, "outline": "V.A.12"}, {"id": "gen-con-029", "part": "general", "topic": "Contracts", "q": "A remedy that undoes a contract and puts the parties back where they were before it was made is", "a": ["Cancellation", "Rescission", "Specific performance", "Reformation"], "c": 1, "why": "Rescission treats the contract as if it never existed, so each party returns what it received. Cancellation ends a contract going forward, and reformation rewrites it to fix a mistake.", "trap": "familiar-term", "difficulty": 1, "outline": "V.A.13"}, {"id": "gen-con-030", "part": "general", "topic": "Contracts", "q": "A lender agrees to let a qualified buyer take over a seller's loan and releases the seller from all further liability. Replacing the old party with a new one this way is", "a": ["Accord and satisfaction", "Novation", "Subordination", "Assignment"], "c": 1, "why": "A novation substitutes a new party or contract and releases the original party. In a simple assignment the original party usually stays secondarily liable.", "trap": "familiar-term", "difficulty": 1, "outline": "V.A.13"}, {"id": "gen-con-031", "part": "general", "topic": "Contracts", "q": "After a purchase and sale agreement is signed, the buyer and seller agree by phone to lower the price by $5,000 for a roof repair. What is the proper way to make this change binding?", "a": ["The listing agent writes the new price on the agreement and initials it", "The buyer's lender notes the change in the loan file", "Nothing more, because both parties agreed verbally", "A written amendment signed or initialed by both buyer and seller"], "c": 3, "why": "Changes to a real estate contract must be in writing and agreed by all parties, so both must sign or initial. An agent's initials do not bind the buyer or seller.", "trap": "too-simple", "difficulty": 2, "outline": "V.B.1"}, {"id": "gen-con-032", "part": "general", "topic": "Contracts", "q": "Is an earnest money deposit required for a purchase agreement to be a valid contract?", "a": ["No; but the agreement is voidable by the seller until a deposit is made", "Yes; the deposit must be at least 5% of the price", "No; the parties' mutual promises are enough consideration", "Yes; without a deposit there is no consideration"], "c": 2, "why": "Earnest money shows good faith and gives the seller security, but mutual promises already supply consideration. A deposit is customary, not a legal requirement for validity.", "trap": "familiar-term", "difficulty": 2, "outline": "V.B.2"}, {"id": "gen-con-033", "part": "general", "topic": "Contracts", "q": "A deal falls apart and both the buyer and seller demand the $15,000 deposit held in the listing broker's escrow account. They cannot agree. The broker should", "a": ["Return the funds to the buyer, because the buyer paid them", "Release the funds to the seller, because the broker represents the seller", "Keep holding the funds until the parties agree in writing or a court decides", "Split the funds evenly between the parties"], "c": 2, "why": "A broker holding a disputed deposit cannot choose a winner and must hold it until there is a written agreement or a court order. Representing the seller does not give the broker the power to decide who gets the money.", "trap": "wrong-context", "difficulty": 3, "outline": "V.B.2"}, {"id": "gen-con-034", "part": "general", "topic": "Contracts", "q": "A buyer with a mortgage contingency applies promptly and in good faith, but the lender denies the loan. Before the contingency deadline, the buyer gives the seller written notice with the denial. Usually the buyer", "a": ["Can end the contract and get the deposit back", "Loses the deposit, because the buyer could not perform", "Must keep applying until a lender approves", "Must close using cash from other sources"], "c": 0, "why": "This is the situation the contingency was written for: timely written notice lets the buyer terminate and recover the deposit. The deposit is lost only when a buyer defaults without a contractual excuse.", "trap": "opposite", "difficulty": 2, "outline": "V.B.3"}, {"id": "gen-con-035", "part": "general", "topic": "Contracts", "q": "A buyer's inspection contingency expired on Tuesday with no notice given. On Thursday the buyer reads the inspection report again and wants to cancel over a minor issue. Which is most accurate?", "a": ["The contingency has lapsed, so cancelling now could put the deposit at risk", "The buyer can cancel, because an inspection contingency lasts until closing", "The seller must make the repair before the buyer can be held to the contract", "The buyer can cancel, because the seller has not been harmed by the delay"], "c": 0, "why": "Contingencies must be used within their deadlines, and a missed deadline usually means the buyer is treated as having waived it. Cancelling afterward without another excuse may be a default.", "trap": "too-simple", "difficulty": 3, "outline": "V.B.3"}, {"id": "gen-con-036", "part": "general", "topic": "Contracts", "q": "A seller accepts an offer that depends on the buyer selling her current home, but keeps the property on the market. If another acceptable offer arrives, the first buyer has 72 hours to remove the home-sale condition or the deal ends. This provision is a", "a": ["Time-is-of-the-essence clause", "Right of first refusal", "Liquidated damages clause", "Kick-out (escape) clause"], "c": 3, "why": "A kick-out clause lets the seller keep marketing while giving the first buyer a short window to drop the contingency. A right of first refusal lets someone match an offer before the owner sells; it is not a way to escape a contingent deal.", "trap": "wrong-context", "difficulty": 2, "outline": "V.B.3"}, {"id": "gen-con-037", "part": "general", "topic": "Contracts", "q": "A purchase agreement says the buyer's obligation depends on a satisfactory home inspection. This type of provision is a", "a": ["Covenant of quiet enjoyment", "Contingency", "Liquidated damages clause", "Novation"], "c": 1, "why": "A contingency is a condition that must be met before a party is bound to go forward. It gives the buyer a defined way out if the condition fails.", "trap": "too-simple", "difficulty": 1, "outline": "V.B.3"}, {"id": "gen-con-038", "part": "general", "topic": "Contracts", "q": "A tenant with three years left on a lease transfers the entire remaining term to another business, which takes over the lease. This is", "a": ["An assignment", "A sublease", "A novation, which releases the original tenant", "A lease-purchase"], "c": 0, "why": "Transferring the whole remaining term is an assignment, while a sublease transfers only part of it. It becomes a novation only if the landlord releases the original tenant.", "trap": "familiar-term", "difficulty": 1, "outline": "V.B.4"}, {"id": "gen-con-039", "part": "general", "topic": "Contracts", "q": "A tenant rents a house under an agreement that applies part of each month's rent toward the purchase price if she buys within two years. This is a", "a": ["Ground lease", "Percentage lease", "Sale-leaseback", "Lease-purchase agreement"], "c": 3, "why": "A lease-purchase (rent-to-own) credits part of the rent toward buying. In a sale-leaseback the owner sells the property and then rents it back, which runs the other way.", "trap": "familiar-term", "difficulty": 1, "outline": "V.B.5"}, {"id": "gen-con-040", "part": "general", "topic": "Contracts", "q": "A commercial tenant pays base rent plus the property taxes, insurance and maintenance costs. This lease is best described as a", "a": ["Net lease", "Graduated lease", "Gross lease", "Percentage lease"], "c": 0, "why": "In a net lease the tenant pays some or all operating costs on top of rent; when it pays all three, it is often called a triple net lease. In a gross lease the landlord pays those costs.", "trap": "opposite", "difficulty": 2, "outline": "V.B.6"}, {"id": "gen-con-041", "part": "general", "topic": "Contracts", "q": "A lease that charges a base rent plus a share of the tenant's gross sales is most common for", "a": ["Retail stores in a shopping mall", "Vacant farmland leased for crops", "Apartments in a large complex", "Single-family homes rented to families"], "c": 0, "why": "A percentage lease ties part of the rent to the tenant's sales, which fits retail businesses. Residential leases are usually gross leases with a flat rent.", "trap": "wrong-context", "difficulty": 1, "outline": "V.B.6"}, {"id": "gen-con-042", "part": "general", "topic": "Contracts", "q": "The seller signed a purchase and sale agreement yesterday. Today the listing agent receives a higher offer. The seller has never said to stop presenting offers. The agent should", "a": ["Reject the offer, because the property is already under contract", "Present it to the seller, noting the seller is already under contract", "Forward the offer to the first buyer so they can match it", "Hold the offer and present it only if the first deal fails"], "c": 1, "why": "Unless the seller has told the agent otherwise, all offers are presented until closing. The seller is still bound by the signed agreement, so the agent should also suggest the seller talk to an attorney.", "trap": "too-simple", "difficulty": 2, "outline": "V.C"}, {"id": "gen-con-043", "part": "general", "topic": "Contracts", "q": "A listing agent has two offers on a property. The agent for one buyer asks the price in the other buyer's offer. The listing agent may reveal it", "a": ["Freely, because offers are public once received", "Only if the other buyer's agent is from the same firm", "Only if the seller authorizes it", "Never, even if the seller wants it disclosed"], "c": 2, "why": "The terms of competing offers are confidential information the agent shares only on the seller's instructions. Saying it can never be shared goes too far, because the seller controls that decision.", "trap": "opposite", "difficulty": 2, "outline": "V.C"}, {"id": "gen-con-044", "part": "general", "topic": "Contracts", "q": "A seller with two strong offers wants to send counteroffers to both buyers at the same time. What is the main risk the listing agent should explain?", "a": ["The seller loses the right to accept any further offers that arrive", "Both buyers could accept, binding the seller to two contracts", "The first buyer's original offer stays open until formally rejected", "Sending counteroffers to two buyers at the same time is illegal"], "c": 1, "why": "Each counteroffer can become a contract when accepted, so countering both at once can create two binding sales. Multiple-counteroffer forms solve this by requiring the seller's final confirmation.", "trap": "too-simple", "difficulty": 3, "outline": "V.C"}, {"id": "gen-agy-001", "part": "general", "topic": "Agency", "q": "A broker hired under a listing agreement to find a buyer for one property is usually what type of agent?", "a": ["Subagent", "Special agent", "Universal agent", "General agent"], "c": 1, "why": "A special agent is authorized for one specific task or transaction, such as selling one home. A general agent handles an ongoing range of matters, like a property manager.", "trap": "familiar-term", "difficulty": 1, "outline": "VI.A.1"}, {"id": "gen-agy-002", "part": "general", "topic": "Agency", "q": "A manager has ongoing authority to sign leases, collect rents and hire repair contractors for an owner's apartment complex. The manager is a", "a": ["Facilitator", "Special agent", "General agent", "Universal agent"], "c": 2, "why": "Ongoing authority over a range of acts in a business makes a general agent. A special agent is limited to a single job, like one sale.", "trap": "familiar-term", "difficulty": 1, "outline": "VI.A.1"}, {"id": "gen-agy-003", "part": "general", "topic": "Agency", "q": "A listing agent hosting an open house tells an unrepresented visitor, 'Stick with me and I'll make sure you get it for the lowest price,' and then advises him on how much to offer. The biggest risk is that the agent has", "a": ["Done nothing wrong, because no buyer agreement was ever signed", "Created a subagency relationship with another brokerage firm", "Become a facilitator who represents neither the buyer nor the seller", "Created an implied agency with the buyer, an undisclosed dual agency"], "c": 3, "why": "Agency can arise from conduct, not just a signed agreement. By advising the buyer against the seller's interest, the agent may now represent both sides without consent, which is undisclosed dual agency.", "trap": "wrong-context", "difficulty": 3, "outline": "VI.A.1"}, {"id": "gen-agy-004", "part": "general", "topic": "Agency", "q": "Under which type of listing does the broker earn the fee even if the owner sells the property alone, with no help from any broker?", "a": ["Net listing", "Exclusive agency", "Exclusive right to sell", "Open listing"], "c": 2, "why": "An exclusive right to sell pays the listing broker no matter who sells. An exclusive agency listing pays the broker if any broker sells, but not if the owner finds the buyer.", "trap": "familiar-term", "difficulty": 1, "outline": "VI.A.2"}, {"id": "gen-agy-005", "part": "general", "topic": "Agency", "q": "An owner signs an exclusive agency listing with one broker. During the term, the owner's coworker buys the house directly from the owner, without any broker's involvement. The listing broker is entitled to", "a": ["Reimbursement of advertising costs only, by law", "Half the commission", "No commission", "The full commission"], "c": 2, "why": "Exclusive agency keeps the owner's right to sell the property without paying a fee. Only the exclusive right to sell would pay the broker in this case.", "trap": "familiar-term", "difficulty": 2, "outline": "VI.A.2"}, {"id": "gen-agy-006", "part": "general", "topic": "Agency", "q": "An owner gives open listings to two brokers. Broker B produces the buyer who purchases the property. Who earns a commission?", "a": ["Neither, because open listings pay no commission", "Only Broker B", "Broker A, because that listing was signed first", "Both brokers, split equally"], "c": 1, "why": "With an open listing only the broker who is the procuring cause of the sale gets paid. Signing first earns nothing.", "trap": "too-simple", "difficulty": 2, "outline": "VI.A.2"}, {"id": "gen-agy-007", "part": "general", "topic": "Agency", "q": "A seller tells a broker, 'Get me $300,000 net and you can keep anything above that as your fee.' Why is this arrangement a problem?", "a": ["The seller must pay the minimum commission rate set by the state board", "Commissions must always be stated as a percentage of the sale price", "It pits the broker's interest against the seller's, and many states ban it", "Only an open listing is allowed to include a fixed-dollar broker fee"], "c": 2, "why": "A net listing rewards the broker for underpricing to the seller or squeezing the buyer, so it is illegal or strongly discouraged in many states. Flat-dollar fees are allowed; the problem is the conflict of interest.", "trap": "none", "difficulty": 3, "outline": "VI.A.2"}, {"id": "gen-agy-008", "part": "general", "topic": "Agency", "q": "Under the practice changes from the 2024 NAR settlement, when must an MLS-participant agent have a written agreement with a buyer?", "a": ["Only if the buyer will pay the agent directly", "Before writing the buyer's first offer", "When the purchase and sale agreement is signed", "Before touring a home with the buyer"], "c": 3, "why": "The settlement rules require the written buyer agreement before touring. Waiting until the offer was a common older practice and no longer meets the rule.", "trap": "too-simple", "difficulty": 2, "outline": "VI.A.3"}, {"id": "gen-agy-009", "part": "general", "topic": "Agency", "q": "Since the 2024 NAR settlement rule changes, offers of compensation to buyers' brokers", "a": ["Must be set by the local REALTOR association", "Are prohibited in every form, inside or outside the MLS", "Must appear in every MLS listing", "May not be published in the MLS"], "c": 3, "why": "The MLS can no longer carry offers of buyer-broker compensation, so that pay is negotiated separately. It is not banned outright: sellers and buyers may still agree to pay buyer agents outside the MLS.", "trap": "opposite", "difficulty": 2, "outline": "VI.A.3"}, {"id": "gen-agy-010", "part": "general", "topic": "Agency", "q": "A licensee who helps both a buyer and a seller complete a transaction without representing either one is usually called a", "a": ["Dual agent", "Designated agent", "Subagent", "Transaction broker"], "c": 3, "why": "A transaction broker (also called a facilitator) represents no one and owes no fiduciary duties, though it must still be honest. A dual agent represents both parties, with limited duties to each.", "trap": "familiar-term", "difficulty": 1, "outline": "VI.A.4"}, {"id": "gen-agy-011", "part": "general", "topic": "Agency", "q": "Under traditional subagency, a broker from a cooperating firm shows a listed home to a buyer. That cooperating broker owes fiduciary duties to the", "a": ["Seller", "Buyer and seller equally", "Buyer", "No one, because the broker is from another firm"], "c": 0, "why": "A subagent works through the listing broker for the seller, so the buyer is only a customer. Treating the buyer as the client is the opposite of how subagency works.", "trap": "opposite", "difficulty": 2, "outline": "VI.A.4"}, {"id": "gen-agy-012", "part": "general", "topic": "Agency", "q": "One brokerage holds a listing, and a buyer working with another agent in the same brokerage wants to buy it. The broker appoints one agent to represent only the seller and the other to represent only the buyer, with written consent. Which is true?", "a": ["Both agents become facilitators who owe no fiduciary duties to anyone", "Each agent represents only their own client; the broker is a disclosed dual agent", "Both agents become dual agents representing the buyer and the seller", "The firm must refer the buyer to an agent at a different brokerage"], "c": 1, "why": "In designated agency each designated agent gives full representation to one client, while the broker over both is in a disclosed dual role. The agents themselves are not dual agents.", "trap": "too-simple", "difficulty": 3, "outline": "VI.A.4"}, {"id": "gen-agy-013", "part": "general", "topic": "Agency", "q": "A disclosed dual agent knows the seller would accept $20,000 less than the list price. The buyer asks, 'What's the lowest they'll take?' The agent should", "a": ["Decline to reveal it, because that is the seller's confidential information", "Reveal it only if the buyer signs a confidentiality agreement", "Reveal it, then tell the seller what the buyer asked", "Reveal it, because a dual agent owes full disclosure to both parties"], "c": 0, "why": "A dual agent must keep each party's bargaining position confidential, including the seller's lowest price and the buyer's highest. Full disclosure of one client's secrets would betray the other client.", "trap": "opposite", "difficulty": 2, "outline": "VI.C.1"}, {"id": "gen-agy-014", "part": "general", "topic": "Agency", "q": "A seller signs a durable power of attorney naming her son to handle the sale of her house. The seller dies before closing. At closing, can the son sign the deed under that power of attorney?", "a": ["Yes, if the purchase agreement was signed before the death", "Yes, if the son is also named in the will", "Yes, because a durable power survives the principal's death", "No, because a power of attorney ends at the principal's death"], "c": 3, "why": "A durable power of attorney survives the principal's incapacity but not death. After death the estate's personal representative handles the sale.", "trap": "too-simple", "difficulty": 3, "outline": "VI.A.5"}, {"id": "gen-agy-015", "part": "general", "topic": "Agency", "q": "Each of the following would normally terminate a listing agreement EXCEPT", "a": ["Expiration of the listing's stated term", "Destruction of the house by fire", "Death of the seller during the listing term", "The listing salesperson moving to another firm"], "c": 3, "why": "The listing belongs to the broker, not the salesperson, so it stays with the firm when a salesperson leaves. Death, destruction of the property and expiration all end the agency.", "trap": "wrong-context", "difficulty": 2, "outline": "VI.A.6"}, {"id": "gen-agy-016", "part": "general", "topic": "Agency", "q": "Three months into a six-month exclusive listing, the seller fires the broker for no reason. Which is most accurate?", "a": ["The seller can end it, but may owe the broker damages", "The seller has no power to end the listing before it expires", "The listing continues automatically until the term ends", "The broker may complete the sale over the seller's objection"], "c": 0, "why": "A principal always has the power to revoke an agency, though not always the right, so a revocation without cause can expose the seller to damages. The broker can never force the sale.", "trap": "opposite", "difficulty": 2, "outline": "VI.A.6"}, {"id": "gen-agy-017", "part": "general", "topic": "Agency", "q": "A listing expired without a sale. Months later the former listing agent is working with a buyer who wants that same house. The buyer asks why the owner seemed so eager to sell. The agent knows from the old listing that the owner is behind on the mortgage. The agent should", "a": ["Keep it confidential; that duty survives the end of the agency", "Tell the buyer, because the listing agreement has now expired", "Tell the buyer, because the agent now owes duties to the buyer", "Tell the buyer, but only if the information appears in MLS history"], "c": 0, "why": "Confidentiality survives the end of the agency relationship. The agent's new duty to the buyer does not allow revealing a former client's confidential financial information.", "trap": "too-simple", "difficulty": 3, "outline": "VI.A.6"}, {"id": "gen-agy-018", "part": "general", "topic": "Agency", "q": "The fiduciary duty that requires an agent to promptly follow a client's lawful instructions is", "a": ["Obedience", "Accounting", "Loyalty", "Reasonable care"], "c": 0, "why": "Obedience means carrying out the client's lawful instructions. Loyalty is the separate duty to put the client's interest above everyone else's, including the agent's.", "trap": "familiar-term", "difficulty": 1, "outline": "VI.B.1"}, {"id": "gen-agy-019", "part": "general", "topic": "Agency", "q": "A seller instructs her listing agent not to show the home to families with young children. The agent should", "a": ["Follow it, but only for buyers from other brokerages", "Follow it, as long as the instruction is in writing", "Refuse, because the duty of obedience covers only lawful instructions", "Follow the instruction, because of the duty of obedience"], "c": 2, "why": "Refusing to deal with families with children violates fair housing law, and obedience never requires breaking the law. Having it in writing does not make an illegal instruction acceptable.", "trap": "too-simple", "difficulty": 2, "outline": "VI.B.1"}, {"id": "gen-agy-020", "part": "general", "topic": "Agency", "q": "A salesperson deposits a buyer's earnest money check into her personal checking account until the offer is accepted. This violates the duty of", "a": ["Confidentiality", "Obedience", "Disclosure", "Accounting"], "c": 3, "why": "Accounting requires safekeeping of client money in a proper escrow or trust account, and mixing it with personal funds is commingling. Salespeople should hand deposits to their broker.", "trap": "familiar-term", "difficulty": 1, "outline": "VI.B.1"}, {"id": "gen-agy-021", "part": "general", "topic": "Agency", "q": "A buyer's agent learns from public court filings that the seller must sell within 30 days to avoid foreclosure. Should the agent share this with her buyer client?", "a": ["No, because it would be unfair to the seller", "Only if the listing agent agrees to its release", "Yes, under her duty of disclosure to the buyer", "No, because it is the seller's confidential information"], "c": 2, "why": "The buyer's agent owes disclosure to her own client, and the information came from public records. Confidentiality protects the agent's own client's secrets, not the other party's.", "trap": "opposite", "difficulty": 3, "outline": "VI.B.1"}, {"id": "gen-agy-022", "part": "general", "topic": "Agency", "q": "A seller tells his listing agent about a recurring roof leak and asks her not to mention it to buyers. A buyer, who is a customer, asks about the roof. The agent should", "a": ["Say she has no knowledge of the condition of the roof", "Disclose it, because known material defects must be disclosed", "Stay silent, because of the duty of confidentiality to the seller", "Disclose it only if the sale is not an 'as is' sale"], "c": 1, "why": "Confidentiality does not cover known material defects; honesty toward customers requires disclosing them. An 'as is' clause does not excuse hiding a known defect.", "trap": "wrong-context", "difficulty": 2, "outline": "VI.B.2"}, {"id": "gen-agy-023", "part": "general", "topic": "Agency", "q": "A seller's agent owes a buyer who is a customer, not a client,", "a": ["Confidentiality of the buyer's maximum price", "Honesty and fair dealing", "Full loyalty", "Obedience to the buyer's lawful instructions"], "c": 1, "why": "Customers are owed honesty, fair dealing and disclosure of known material defects. Loyalty, obedience and confidentiality are fiduciary duties reserved for clients.", "trap": "opposite", "difficulty": 1, "outline": "VI.B.2"}, {"id": "gen-agy-024", "part": "general", "topic": "Agency", "q": "An unrepresented buyer at a showing asks the seller's agent, 'What should I offer for this place?' The best response is to", "a": ["Suggest an offer 10% below list price, since the buyer is unrepresented", "Give factual data like recent sales, but explain she represents the seller", "Recommend full price, because that is what is best for her client", "Refuse to give the buyer any information about the property"], "c": 1, "why": "A seller's agent can give a customer honest facts but cannot negotiate for or advise the buyer against her own client. Refusing all information goes too far, because customers are still owed honest help with facts.", "trap": "too-simple", "difficulty": 3, "outline": "VI.B.2"}, {"id": "gen-agy-025", "part": "general", "topic": "Agency", "q": "In general, a licensee should disclose whom she represents to a consumer", "a": ["When the purchase and sale agreement is being signed by the parties", "At the closing, when the commission is paid", "Only if the consumer specifically asks about it", "At first substantive contact, before confidential information is shared"], "c": 3, "why": "Agency must be disclosed early so the consumer knows not to reveal confidential information to an agent working for the other side. Waiting until the purchase agreement is too late.", "trap": "too-simple", "difficulty": 2, "outline": "VI.C.1"}, {"id": "gen-agy-026", "part": "general", "topic": "Agency", "q": "A broker represents both the buyer and the seller in the same deal without telling either of them. This undisclosed dual agency", "a": ["Automatically becomes a facilitator relationship", "Is allowed as long as the price is fair to both sides", "Is allowed if the broker discloses it before closing", "Is illegal and can cost the broker the commission and license"], "c": 3, "why": "Dual agency is legal only with the informed written consent of both parties given in advance. Disclosing it at closing does not cure it.", "trap": "too-simple", "difficulty": 2, "outline": "VI.C.1"}, {"id": "gen-agy-027", "part": "general", "topic": "Agency", "q": "A listing agent wants to buy her client's property for herself. What must she do?", "a": ["Disclose her licensee status and interest in writing to the seller", "Have a relative sign the offer so the seller is not pressured", "Get advance approval from the state licensing board", "Nothing more, as long as she offers the full list price"], "c": 0, "why": "Loyalty requires disclosing any personal interest so the client can decide with full information. Paying full price does not remove the conflict, and using a relative would hide it.", "trap": "too-simple", "difficulty": 2, "outline": "VI.C.2"}, {"id": "gen-agy-028", "part": "general", "topic": "Agency", "q": "A buyer's agent wants to recommend a mortgage company owned by her spouse. What is the proper course?", "a": ["Disclose the relationship in writing and let the buyer pick any lender", "Recommend it only after the buyer signs a purchase agreement", "Recommend it without comment, since referrals are part of the service", "Accept a referral fee from the lender, as long as the buyer closes"], "c": 0, "why": "Agents must disclose financial interests in businesses they recommend, and federal law (RESPA) bans fees for referring settlement services. Disclosure lets the client decide freely.", "trap": "familiar-term", "difficulty": 3, "outline": "VI.C.2"}, {"id": "gen-agy-029", "part": "general", "topic": "Agency", "q": "The commission rate in a listing agreement is set by", "a": ["The state real estate licensing board", "The multiple listing service", "The local REALTOR association", "Negotiation between the broker and the client"], "c": 3, "why": "Commissions are always negotiable between the broker and the client. No board, association or MLS sets them, and fixing rates among competitors is illegal.", "trap": "wrong-context", "difficulty": 1, "outline": "VI.A.2"}, {"id": "gen-agy-030", "part": "general", "topic": "Agency", "q": "A happy seller wants to hand the listing salesperson a $1,000 bonus check directly at closing. The salesperson should", "a": ["Have the payment go through her employing broker", "Accept it, as long as it is under the commission amount", "Accept it, because it is a gift and not a commission", "Accept it, as long as the buyer is told"], "c": 0, "why": "A salesperson may be paid for real estate work only by her employing broker. Calling it a gift does not change that it is payment for her services.", "trap": "wrong-context", "difficulty": 2, "outline": "VI.A.2"}, {"id": "gen-agy-031", "part": "general", "topic": "Practice of Real Estate", "q": "Two owners of competing brokerages agree over lunch that both will charge sellers a 6% commission. This is", "a": ["Price fixing, a violation of antitrust law", "Market allocation", "Tying", "Legal, because each broker can set its own rate"], "c": 0, "why": "Competitors agreeing on rates is price fixing under the Sherman Antitrust Act. Each firm may set its own rate on its own, but not by agreement with competitors.", "trap": "familiar-term", "difficulty": 2, "outline": "X.B.2"}, {"id": "gen-agy-032", "part": "general", "topic": "Practice of Real Estate", "q": "Several brokerages agree with each other not to cooperate with a new low-fee brokerage in town. This is", "a": ["Market allocation", "A group boycott", "Lawful competition, because each firm chooses whom to work with", "Price fixing"], "c": 1, "why": "Competitors agreeing together to shut out another firm is a group boycott. One firm deciding on its own not to work with someone is legal; agreeing to it with competitors is not.", "trap": "familiar-term", "difficulty": 2, "outline": "X.B.2"}, {"id": "gen-own-001", "part": "general", "topic": "Property Ownership", "q": "A seller is packing to move. Unless the purchase contract says otherwise, which item normally stays with the house?", "a": ["Patio furniture on the deck", "A large area rug in the living room", "A ceiling light fixture wired into the electrical system", "A freestanding refrigerator that plugs into the wall"], "c": 2, "why": "A light wired into the house is attached, so it became a fixture (real property) and conveys with the house. The fridge is tempting because it is an appliance, but a plug-in, freestanding fridge is movable personal property.", "trap": "none", "difficulty": 1, "outline": "I.A"}, {"id": "gen-own-002", "part": "general", "topic": "Property Ownership", "q": "A tenant who runs a bakery bolted three commercial ovens to the floor of a leased storefront. When the lease ends, the ovens are generally:", "a": ["Emblements that the tenant may return later to collect", "Appurtenances that pass with the building to any future buyer", "Real property of the landlord, because they are bolted down", "Trade fixtures the tenant may remove before the lease ends, repairing any damage caused"], "c": 3, "why": "Equipment a tenant installs for its business is a trade fixture and stays the tenant's personal property, so the tenant may remove it (and must fix any damage). 'Bolted down = fixture' is the trap: the landlord-tenant relationship and business purpose override the method of attachment.", "trap": "familiar-term", "difficulty": 2, "outline": "I.A"}, {"id": "gen-own-003", "part": "general", "topic": "Property Ownership", "q": "Which legal description method starts at a point of beginning, follows directions and distances around the boundary, and must return to that point?", "a": ["Metes and bounds", "Street address with assessor's parcel number", "Lot and block (recorded plat)", "Government (rectangular) survey"], "c": 0, "why": "Metes (measurements) and bounds (boundaries/monuments) trace the perimeter from a point of beginning and must close back on it. The rectangular survey also uses measured lines, but it locates land by townships and sections, not by walking the boundary.", "trap": "familiar-term", "difficulty": 1, "outline": "I.B.1"}, {"id": "gen-own-004", "part": "general", "topic": "Property Ownership", "q": "A deed describes a parcel as 'Lot 14 on a subdivision plan recorded with the registry of deeds.' This is which type of legal description?", "a": ["Government (rectangular) survey", "Lot and block (recorded plat)", "Informal description, not a legal description", "Metes and bounds"], "c": 1, "why": "A reference to a numbered lot on a recorded subdivision map is the lot and block (recorded plat) method. It is a complete legal description because the recorded plan supplies the exact dimensions, so it is not merely informal.", "trap": "none", "difficulty": 1, "outline": "I.B.2"}, {"id": "gen-own-005", "part": "general", "topic": "Property Ownership", "q": "Under the government survey system, how many acres are in the NE 1/4 of the SW 1/4 of a section?", "a": ["10", "40", "80", "160"], "c": 1, "why": "A section is 640 acres. Work from the end of the description: 640 x 1/4 = 160 (SW 1/4), then 160 x 1/4 = 40 acres. Stopping after one step gives 160, the most common mistake.", "trap": "math-step", "difficulty": 3, "outline": "I.B.3"}, {"id": "gen-own-006", "part": "general", "topic": "Property Ownership", "q": "An L-shaped one-story house has a main section measuring 40 ft x 30 ft and a wing measuring 20 ft x 15 ft. What is its total square footage?", "a": ["1,200 sq ft", "1,500 sq ft", "1,800 sq ft", "2,700 sq ft"], "c": 1, "why": "Split the L into rectangles: 40 x 30 = 1,200, plus 20 x 15 = 300, total 1,500 sq ft. 1,200 forgets the wing; 2,700 multiplies the combined lengths and widths, which overcounts space that does not exist.", "trap": "math-step", "difficulty": 2, "outline": "I.B.4"}, {"id": "gen-own-007", "part": "general", "topic": "Property Ownership", "q": "A rectangular parcel measures 330 feet by 660 feet. Approximately how many acres does it contain?", "a": ["2.5 acres", "4.5 acres", "5 acres", "50 acres"], "c": 2, "why": "330 x 660 = 217,800 sq ft; divided by 43,560 sq ft per acre = 5 acres. Answers like 50 come from slipping a decimal or using the wrong acre figure; always divide by 43,560.", "trap": "math-step", "difficulty": 2, "outline": "I.B.5"}, {"id": "gen-own-008", "part": "general", "topic": "Property Ownership", "q": "A home is sold at a foreclosure sale. Which claim is normally paid first from the proceeds, even though it arose after the first mortgage was recorded?", "a": ["A personal credit card balance of the owner", "A judgment lien recorded before the mortgage", "A home equity line of credit", "Unpaid real estate taxes owed to the town"], "c": 3, "why": "Real estate taxes and special assessments take priority over other liens regardless of when they arose. The earlier-recorded judgment is the trap: 'first in time' governs the other liens, but not property taxes.", "trap": "familiar-term", "difficulty": 2, "outline": "I.C.1"}, {"id": "gen-own-009", "part": "general", "topic": "Property Ownership", "q": "The owner of a back lot has a recorded right of way over the front lot's driveway. The front lot is sold, and the new deed does not mention the right of way. What happens to it?", "a": ["It continues, because an easement appurtenant runs with the land", "It ends unless the back-lot owner re-records it within 30 days of the sale", "It becomes a license the new owner may revoke", "It ends, because the new deed did not mention it"], "c": 0, "why": "An easement appurtenant is attached to the land itself, so it passes automatically with both parcels whether or not the next deed repeats it. Assuming that silence in the deed ends it is the trap; a sale is not one of the ways an easement terminates.", "trap": "too-simple", "difficulty": 2, "outline": "I.C.2"}, {"id": "gen-own-010", "part": "general", "topic": "Property Ownership", "q": "A homeowner tells a coworker he may keep his kayak on her side yard for the summer. No money or writing is involved. The coworker has:", "a": ["A license", "An easement by prescription", "An easement in gross", "A leasehold estate"], "c": 0, "why": "Informal, personal permission to use land is a license: it is revocable and not an interest in the land. A prescriptive easement requires use WITHOUT permission for the statutory period, so permission rules it out.", "trap": "familiar-term", "difficulty": 1, "outline": "I.C.2"}, {"id": "gen-own-011", "part": "general", "topic": "Property Ownership", "q": "A buyer's survey shows that the neighbor's garage extends two feet over the seller's lot line. This is:", "a": ["A license that ends automatically when the property is sold", "An easement in gross held by the neighbor", "An encroachment, which can affect title and value and should be resolved before closing", "A private nuisance"], "c": 2, "why": "A structure physically crossing the boundary without a right to be there is an encroachment, usually discovered by survey. A nuisance is a non-physical interference such as noise or odors, so it does not fit a building over the line.", "trap": "familiar-term", "difficulty": 2, "outline": "I.C.3"}, {"id": "gen-own-012", "part": "general", "topic": "Property Ownership", "q": "Dana has openly fenced in and gardened a strip of her neighbor's yard, continuously and exclusively, for longer than the state's adverse possession period. When she started, the neighbor wrote her a note saying 'feel free to use that strip.' Can Dana claim title to it?", "a": ["Yes, but only after recording the neighbor's note at the registry", "No, because adverse possession can never apply to part of a lot", "Yes, because her use was open, continuous and exclusive for the full period", "No, because use with the owner's permission is not hostile, so it cannot ripen into adverse possession"], "c": 3, "why": "Adverse possession requires hostile use, meaning use WITHOUT the owner's permission, in addition to being open, continuous and exclusive for the statutory period. Meeting the time and visibility tests is the trap: the written permission defeats the claim no matter how long the use lasts.", "trap": "too-simple", "difficulty": 3, "outline": "I.C.4"}, {"id": "gen-own-013", "part": "general", "topic": "Property Ownership", "q": "An agent is asked to list a house whose owner recently died with a will. Before the sale can close, who normally must sign the deed?", "a": ["The executor (personal representative) appointed through probate, acting with court authority", "The state, because the owner died", "Any adult heir who is living in the home", "The listing broker, acting for the family"], "c": 0, "why": "Title to a decedent's property is dealt with through probate, and the court-appointed personal representative conveys it. Escheat to the state happens only when someone dies with no will AND no heirs, which is not the case here.", "trap": "familiar-term", "difficulty": 2, "outline": "I.C.4"}, {"id": "gen-own-014", "part": "general", "topic": "Property Ownership", "q": "A landowner sells an energy company the right to extract natural gas beneath her land but keeps her house and yard. She has:", "a": ["Transferred her riparian rights", "Granted an easement appurtenant", "Separated the subsurface (mineral) rights from the surface rights", "Given up her entire fee simple estate"], "c": 2, "why": "Subsurface rights are part of the bundle of rights and can be sold apart from the surface, which the owner keeps. Riparian rights concern water bordering the land, not minerals below it.", "trap": "wrong-context", "difficulty": 1, "outline": "I.C.5"}, {"id": "gen-own-015", "part": "general", "topic": "Property Ownership", "q": "Ownership in severalty means the property is owned by:", "a": ["Several people holding equal shares", "One person or one legal entity alone", "Two or more people with a right of survivorship", "A married couple as a single unit"], "c": 1, "why": "Severalty means the owner's interest is 'severed' from everyone else's: a sole owner, which may be one person or one entity such as a corporation. The word sounds like 'several,' which is exactly the trap.", "trap": "familiar-term", "difficulty": 1, "outline": "I.D.1"}, {"id": "gen-own-016", "part": "general", "topic": "Property Ownership", "q": "Three friends own a property as tenants in common: Ana holds 1/2, Ben 1/4, and Cy 1/4. Cy dies, leaving everything to his niece by will. What is the result?", "a": ["Ana receives Cy's share because she holds the largest interest", "The ownership automatically converts to a joint tenancy", "Ana and Ben split Cy's share by right of survivorship", "The niece receives Cy's 1/4 interest and becomes a tenant in common with Ana and Ben"], "c": 3, "why": "Tenancy in common has no right of survivorship, so a co-owner's share passes by will or inheritance. Survivorship is the defining feature of joint tenancy, which is why it is the tempting wrong answer.", "trap": "familiar-term", "difficulty": 2, "outline": "I.D.2"}, {"id": "gen-own-017", "part": "general", "topic": "Property Ownership", "q": "Rosa, Sam, and Tia own land as joint tenants. While alive, Rosa deeds her interest to Uma. Later Sam dies. Who owns the land now?", "a": ["Tia, Uma, and Sam's heirs each own 1/3", "Tia owns all of it by survivorship", "Tia owns 2/3 and Uma owns 1/3, as tenants in common", "Tia and Uma each own 1/2 as joint tenants"], "c": 2, "why": "Rosa's deed breaks the joint tenancy only for her 1/3: Uma becomes a tenant in common, while Sam and Tia remain joint tenants with each other. When Sam dies, his share goes to Tia by survivorship (not to his heirs), so Tia holds 2/3 and Uma 1/3. Uma never joins the joint tenancy.", "trap": "math-step", "difficulty": 3, "outline": "I.D.3"}, {"id": "gen-own-018", "part": "general", "topic": "Property Ownership", "q": "A buyer purchases an apartment in a cooperative. What does the buyer receive?", "a": ["A deed to the use of a unit for one specific week each year", "A life estate in the unit", "A deed to the unit and an undivided interest in the common areas", "Shares of stock in the corporation that owns the building, plus a proprietary lease"], "c": 3, "why": "In a co-op the corporation owns the real estate; buyers get stock and a proprietary lease, which is personal property. A unit deed with an undivided interest in common areas describes a condominium, not a co-op.", "trap": "wrong-context", "difficulty": 1, "outline": "I.D.4"}, {"id": "gen-own-019", "part": "general", "topic": "Property Ownership", "q": "A homeowner deeds her house into a revocable living trust, naming a trust company as trustee and her children as beneficiaries. Who holds legal title?", "a": ["The beneficiaries", "The trustee", "The probate court", "The homeowner, in her own name"], "c": 1, "why": "Property placed in a trust is titled in the trustee, who holds legal title for the beneficiaries. The beneficiaries are the tempting answer because they benefit, but they hold only an equitable (beneficial) interest.", "trap": "familiar-term", "difficulty": 2, "outline": "I.D.5"}, {"id": "gen-own-020", "part": "general", "topic": "Property Ownership", "q": "Investors want to buy rental buildings in a form that limits their personal liability and avoids double taxation of profits. Which form best fits?", "a": ["A limited liability company (LLC)", "A C corporation", "A sole proprietorship", "A general partnership"], "c": 0, "why": "An LLC combines limited liability with pass-through taxation. A C corporation also limits liability, but its profits are taxed at the corporate level and again as dividends; a general partnership passes income through but leaves partners personally liable.", "trap": "familiar-term", "difficulty": 2, "outline": "I.D.6"}, {"id": "gen-own-021", "part": "general", "topic": "Property Ownership", "q": "Alma deeds her house 'to Bruno for the life of Bruno, then to Celia.' Alma dies, and two years later Bruno dies. Who owns the house now?", "a": ["The state, by escheat", "Alma's heirs, by reversion", "Celia, in fee simple, as remainderman", "Bruno's heirs, by inheritance"], "c": 2, "why": "Bruno held a life estate that ended at his own death; Celia's remainder then becomes a fee simple. Alma's death is irrelevant, and a reversion would only exist if the deed had not named a third party to take after Bruno.", "trap": "familiar-term", "difficulty": 3, "outline": "I.D.7"}, {"id": "gen-land-001", "part": "general", "topic": "Land Use Controls", "q": "A home is assessed at $420,000. The tax rate is $12.50 per $1,000 of assessed value, and the town bills in four equal quarterly installments. How much is each quarterly bill?", "a": ["$437.50", "$525.00", "$1,312.50", "$5,250.00"], "c": 2, "why": "Annual tax = ($420,000 / 1,000) x $12.50 = $5,250; divided by 4 quarters = $1,312.50. $5,250 is the full year (stopping a step early), and $437.50 is a monthly figure.", "trap": "math-step", "difficulty": 3, "outline": "II.A.1"}, {"id": "gen-land-002", "part": "general", "topic": "Land Use Controls", "q": "A town installs new sidewalks on one street and charges the cost only to the owners whose lots front that street. This charge is:", "a": ["A special assessment, a specific lien on the benefited properties", "A general lien on all of each owner's assets", "An ad valorem tax on all property in town", "An exercise of eminent domain"], "c": 0, "why": "A special assessment charges only the properties that benefit from a public improvement and attaches as a specific lien on them. An ad valorem tax is levied on all taxable property based on value, not just on one street.", "trap": "familiar-term", "difficulty": 2, "outline": "II.A.1"}, {"id": "gen-land-003", "part": "general", "topic": "Land Use Controls", "q": "An owner dies without a will. His only living relative is a sister. What happens to his house?", "a": ["The state takes it by escheat because there was no will", "The sister inherits it under the state's laws of descent (intestate succession)", "The town takes it by eminent domain", "It must be sold at auction with proceeds going to the state"], "c": 1, "why": "Dying intestate means state law decides the heirs; a sister is an heir. Escheat applies only when there is no will AND no heirs, so it is the tempting but wrong choice here.", "trap": "familiar-term", "difficulty": 2, "outline": "II.A.2"}, {"id": "gen-land-004", "part": "general", "topic": "Land Use Controls", "q": "A state widens a highway and takes a 20-foot strip of a homeowner's front yard. Which statement is correct?", "a": ["No payment is owed because road widening is an exercise of police power", "The owner can stop the taking by refusing to sign a deed", "The state must buy the owner's entire parcel", "The owner is entitled to just compensation and may challenge the amount in court"], "c": 3, "why": "Taking property for public use is eminent domain, carried out through condemnation, and requires just compensation, which the owner may contest. Police power regulates use without payment, but it does not allow the government to take ownership.", "trap": "opposite", "difficulty": 2, "outline": "II.A.2"}, {"id": "gen-land-005", "part": "general", "topic": "Land Use Controls", "q": "Zoning ordinances are an exercise of which government power?", "a": ["Escheat", "Police power", "Eminent domain", "Taxation"], "c": 1, "why": "Zoning regulates land use for public health, safety and welfare, which is police power, and no compensation is owed. Eminent domain is the tempting choice, but it involves taking title and paying for it.", "trap": "familiar-term", "difficulty": 1, "outline": "II.B"}, {"id": "gen-land-006", "part": "general", "topic": "Land Use Controls", "q": "A corner store has operated legally for decades. The town rezones the area for residential use only. The store may usually keep operating as:", "a": ["A legal nonconforming use", "A variance", "A special (conditional) use permit", "An illegal use that must close at once"], "c": 0, "why": "A use that was lawful before a zoning change is usually allowed to continue as a nonconforming ('grandfathered') use, often with limits on expansion or rebuilding. A variance is a permission the owner applies for because of a hardship; nothing was applied for here.", "trap": "familiar-term", "difficulty": 2, "outline": "II.B"}, {"id": "gen-land-007", "part": "general", "topic": "Land Use Controls", "q": "An owner's lot is so narrow and oddly shaped that no reasonable house can meet the required side setbacks. To build closer to the line, the owner should seek:", "a": ["A building code waiver from the inspector", "Nonconforming use status", "A deed restriction", "A variance"], "c": 3, "why": "A variance relaxes a zoning requirement where strict enforcement causes a hardship due to the land's unusual shape. Nonconforming use applies to a use that existed before the rule, not to a new house.", "trap": "familiar-term", "difficulty": 2, "outline": "II.B"}, {"id": "gen-land-008", "part": "general", "topic": "Land Use Controls", "q": "Which government control sets minimum standards for wiring, plumbing, and fire safety in new construction?", "a": ["The town's master plan", "Zoning ordinances", "Subdivision covenants (CC&Rs)", "Building codes, enforced through permits and inspections"], "c": 3, "why": "Building codes govern construction methods and materials and are enforced by permits and inspections. Zoning controls what use and how much building goes where, not how the wiring is installed.", "trap": "wrong-context", "difficulty": 1, "outline": "II.B"}, {"id": "gen-land-009", "part": "general", "topic": "Land Use Controls", "q": "A developer wants to divide a 20-acre tract into 40 house lots with new streets. Before selling lots, the developer generally must:", "a": ["Record private covenants (CC&Rs), which take the place of town approval", "Obtain only a building permit for the first house", "Obtain approval of a subdivision plan under local subdivision regulations and record the approved plan", "Obtain a separate variance for each lot"], "c": 2, "why": "Subdivision regulations require the planning authority to approve lot layout, streets and utilities before the plan is recorded and lots are sold. Private CC&Rs may also be recorded, but they never replace the government's approval.", "trap": "too-simple", "difficulty": 2, "outline": "II.B"}, {"id": "gen-land-010", "part": "general", "topic": "Land Use Controls", "q": "Local zoning allows fences up to 6 feet tall. The subdivision's recorded covenants limit fences to 4 feet. An owner wants a 5-foot fence. Which is correct?", "a": ["Zoning always overrides private restrictions, so the 5-foot fence is allowed", "The stricter covenant controls, so neighbors or the association can enforce the 4-foot limit", "The covenants bind only the developer, not later owners", "The building inspector enforces the covenants when issuing the permit"], "c": 1, "why": "When public and private rules differ, the owner must obey both, so the more restrictive one controls; covenants are enforced privately by other owners or the association. Zoning overriding covenants is the trap: zoning only sets the outer limit of what the government allows.", "trap": "opposite", "difficulty": 3, "outline": "II.C.2"}, {"id": "gen-land-011", "part": "general", "topic": "Land Use Controls", "q": "A deed conveys land to a town 'but if the land is ever used for anything other than a public library, the grantor may re-enter and reclaim it.' The town holds:", "a": ["A fee simple subject to a condition subsequent", "A fee simple determinable", "A life estate", "An easement in gross"], "c": 0, "why": "'But if' language with an optional right of re-entry creates a fee simple subject to a condition subsequent; the grantor must act to reclaim. A fee simple determinable ('so long as') ends automatically when the condition is broken.", "trap": "familiar-term", "difficulty": 3, "outline": "II.C.1"}, {"id": "gen-land-012", "part": "general", "topic": "Land Use Controls", "q": "Which recorded deed restriction would a court refuse to enforce?", "a": ["A rule that the home may be sold only to buyers of a certain race or religion", "A requirement that exterior colors be approved by an architectural committee", "A ban on commercial use of the lot", "A minimum house size of 1,800 square feet"], "c": 0, "why": "Restrictions that discriminate based on race, religion or other protected classes are void and unenforceable under fair housing law. Size, use and design restrictions are ordinary private controls that courts do enforce.", "trap": "none", "difficulty": 1, "outline": "II.C.1"}, {"id": "gen-land-013", "part": "general", "topic": "Land Use Controls", "q": "A condominium's recorded documents prohibit renting units for less than six months. A unit owner wants to list the unit as a weekly vacation rental. Which is correct?", "a": ["The restriction binds only owners who voted for it", "The restriction is void because each owner holds fee simple title", "The owner is bound by the restriction, and the association can enforce it", "Only the town can enforce use restrictions on private property"], "c": 2, "why": "Buying into a condominium means accepting its master deed, bylaws and rules, which the association enforces (for example by fines or court action). Fee simple ownership does not free an owner from recorded private restrictions.", "trap": "too-simple", "difficulty": 3, "outline": "II.C.3"}, {"id": "gen-val-001", "part": "general", "topic": "Valuation", "q": "Market value is best defined as the:", "a": ["Highest price a buyer could possibly be persuaded to pay", "Most probable price in a competitive, open market with informed parties acting without undue pressure", "Price actually paid in the most recent sale of the property", "Value the town assessor uses for property taxes"], "c": 1, "why": "Market value is the MOST PROBABLE price under normal, arm's-length conditions. 'Highest price' is the trap; and a past sale price or an assessed value can differ from market value.", "trap": "familiar-term", "difficulty": 1, "outline": "III.A.1"}, {"id": "gen-val-002", "part": "general", "topic": "Valuation", "q": "A seller asks her listing salesperson for a written appraisal to use in a divorce settlement. The salesperson should:", "a": ["Prepare an appraisal, since a real estate license covers valuation", "Prepare an appraisal as long as she charges no fee", "Prepare an appraisal only if her broker reviews and signs it", "Explain that she can provide a CMA (opinion of price) but not an appraisal, and refer the seller to a licensed or certified appraiser"], "c": 3, "why": "Appraisals are done by state-licensed or certified appraisers; calling a licensee's valuation an appraisal is unauthorized appraisal practice. A broker's signature or not charging a fee does not change that.", "trap": "too-simple", "difficulty": 3, "outline": "III.A.2"}, {"id": "gen-val-003", "part": "general", "topic": "Valuation", "q": "What is the FIRST step in the appraisal process?", "a": ["Reconcile the value indications", "Estimate the value of the land as if vacant", "Define the problem: purpose, type of value sought, property, and effective date", "Gather data on comparable sales"], "c": 2, "why": "An appraiser first defines the problem, because the purpose and type of value decide what data to collect. Gathering comparable sales comes after the problem is defined.", "trap": "none", "difficulty": 1, "outline": "III.A.3"}, {"id": "gen-val-004", "part": "general", "topic": "Valuation", "q": "For a typical owner-occupied single-family home, an appraiser's approaches indicate: sales comparison $512,000, cost $540,000, income $480,000. The most likely final opinion of value is about:", "a": ["$540,000, the highest indication", "$512,000, giving the most weight to sales comparison", "$480,000, the most conservative indication", "$510,667, the average of the three"], "c": 1, "why": "Reconciliation weighs each approach by its reliability for the property type; for homes, sales comparison carries the most weight. Averaging ($1,532,000 / 3 = $510,667) is the classic trap: reconciliation is never a simple average.", "trap": "math-step", "difficulty": 3, "outline": "III.A.3"}, {"id": "gen-val-005", "part": "general", "topic": "Valuation", "q": "The sales comparison approach is based mainly on which principle?", "a": ["Anticipation", "Regression", "Contribution", "Substitution"], "c": 3, "why": "Substitution says a buyer will not pay more than the cost of an equally desirable substitute, which is why comparable sales indicate value. Contribution concerns what one feature adds, which is used for adjustments but is not the foundation of the approach.", "trap": "familiar-term", "difficulty": 1, "outline": "III.B.1"}, {"id": "gen-val-006", "part": "general", "topic": "Valuation", "q": "An owner builds a $1.2 million custom home in a neighborhood of $450,000 houses. Its market value will likely be held down by:", "a": ["Regression", "Anticipation", "Plottage", "Progression"], "c": 0, "why": "Regression: the most expensive home in an area is pulled down toward its neighbors' values (overimprovement). Progression is the opposite effect, where a modest home gains from nicer neighbors.", "trap": "opposite", "difficulty": 2, "outline": "III.B.1"}, {"id": "gen-val-007", "part": "general", "topic": "Valuation", "q": "An owner spends $70,000 on an in-ground pool. An appraiser finds that buyers in the area pay only about $25,000 more for homes with pools. Which principle explains the gap?", "a": ["Substitution", "Change", "Highest and best use", "Contribution"], "c": 3, "why": "Contribution says a feature is worth what it adds to market value, not what it cost. Substitution is tempting because comps are involved, but the question is about the value of one component.", "trap": "familiar-term", "difficulty": 2, "outline": "III.B.1"}, {"id": "gen-val-008", "part": "general", "topic": "Valuation", "q": "A property's highest and best use must be:", "a": ["Legally permitted, physically possible, financially feasible, and the most productive", "The use the current owner prefers", "The use producing the highest gross income, regardless of zoning", "The property's current use"], "c": 0, "why": "Highest and best use is tested in order: legal, physically possible, financially feasible, maximally productive. The current use may not be the best one, and a use that zoning forbids fails the very first test.", "trap": "too-simple", "difficulty": 2, "outline": "III.B.1"}, {"id": "gen-val-009", "part": "general", "topic": "Valuation", "q": "Subject home: 2 baths, no garage, updated kitchen. A comparable sold for $465,000 with 2.5 baths (half bath worth $8,000), a 2-car garage (worth $20,000), and an outdated kitchen (update worth $12,000). What is the adjusted price of the comparable?", "a": ["$425,000", "$449,000", "$481,000", "$505,000"], "c": 1, "why": "Adjust the comp toward the subject: subtract for features the comp has that the subject lacks, add for what it lacks. $465,000 - $8,000 - $20,000 + $12,000 = $449,000. Reversing the signs gives $481,000.", "trap": "opposite", "difficulty": 3, "outline": "III.B.2"}, {"id": "gen-val-010", "part": "general", "topic": "Valuation", "q": "Which comparable sale would an appraiser generally consider most reliable?", "a": ["A similar home on the same street that sold four years ago", "A nearby home that sold at a foreclosure auction last month", "A similar nearby home that sold recently and needs the fewest adjustments", "An active listing on the same street with a high asking price"], "c": 2, "why": "The best comps are recent, nearby, similar, arm's-length sales needing the fewest adjustments. A foreclosure auction is recent and close but not an arm's-length sale, so its price may not reflect market value.", "trap": "none", "difficulty": 2, "outline": "III.B.2"}, {"id": "gen-val-011", "part": "general", "topic": "Valuation", "q": "Using the cost approach: land value $120,000; building of 2,400 sq ft at a current cost of $200 per sq ft; accrued depreciation 15% of building cost. What is the indicated value?", "a": ["$408,000", "$510,000", "$528,000", "$600,000"], "c": 2, "why": "Building new = 2,400 x $200 = $480,000. Less 15% ($72,000) = $408,000. Add land: $408,000 + $120,000 = $528,000. $510,000 depreciates the land too, but land does not depreciate.", "trap": "math-step", "difficulty": 3, "outline": "III.B.3"}, {"id": "gen-val-012", "part": "general", "topic": "Valuation", "q": "A new highway interchange is built next to a quiet neighborhood, and traffic noise lowers home values. This loss is:", "a": ["External (economic) obsolescence", "Functional obsolescence", "Incurable physical deterioration", "Curable physical deterioration"], "c": 0, "why": "A cause outside the property lines is external (economic) obsolescence, and the owner cannot cure it. Functional obsolescence is a design or layout flaw inside the property.", "trap": "familiar-term", "difficulty": 2, "outline": "III.B.3"}, {"id": "gen-val-013", "part": "general", "topic": "Valuation", "q": "The cost approach is most appropriate for valuing:", "a": ["A 15-year-old unit in a large condominium complex", "A six-unit apartment building bought for its rents", "A vacant building lot", "A newly built fire station with few comparable sales"], "c": 3, "why": "The cost approach works best for new or special-purpose buildings that rarely sell. The six-unit building is tempting because it is commercial, but it produces rent, so the income approach fits it better.", "trap": "wrong-context", "difficulty": 2, "outline": "III.B.3"}, {"id": "gen-val-014", "part": "general", "topic": "Valuation", "q": "An 8-unit building rents for $1,500 per unit per month. Vacancy and collection loss is 5%. Annual operating expenses are $52,000, and annual mortgage payments are $40,000. Using a 7.5% cap rate, what is the indicated value (rounded)?", "a": ["$597,333", "$1,130,667", "$1,226,667", "$1,920,000"], "c": 1, "why": "Gross = 8 x $1,500 x 12 = $144,000; less 5% = $136,800 effective gross; less $52,000 expenses = $84,800 NOI; $84,800 / 0.075 = $1,130,667. Subtracting the mortgage payments gives $597,333, but debt service is not an operating expense.", "trap": "math-step", "difficulty": 3, "outline": "III.B.4"}, {"id": "gen-val-015", "part": "general", "topic": "Valuation", "q": "If net operating income stays the same but investors demand a higher capitalization rate, the property's value will:", "a": ["Stay the same", "Decrease", "Increase only if vacancy falls", "Increase"], "c": 1, "why": "Value = NOI / cap rate, so a larger divisor gives a smaller value. A higher rate signals more perceived risk, so buyers pay less for the same income.", "trap": "opposite", "difficulty": 1, "outline": "III.B.4"}, {"id": "gen-val-016", "part": "general", "topic": "Valuation", "q": "Small rental houses in an area have recently sold at a gross rent multiplier of 150, based on monthly rent. The subject rents for $2,400 per month. What is its estimated value?", "a": ["$336,000", "$360,000", "$384,000", "$4,320,000"], "c": 1, "why": "Value = monthly GRM x monthly rent = 150 x $2,400 = $360,000. Using annual rent ($28,800) with a monthly multiplier gives $4,320,000; match the multiplier to the rent period.", "trap": "math-step", "difficulty": 2, "outline": "III.B.4"}, {"id": "gen-val-017", "part": "general", "topic": "Valuation", "q": "Which statement about a comparative market analysis (CMA) is correct?", "a": ["It is prepared by a licensee to help price a property and is not an appraisal", "It relies mainly on the cost approach", "It may be called an appraisal if it uses at least three comparables", "It is required by lenders for most federally related mortgage loans"], "c": 0, "why": "A CMA is a licensee's analysis of recent sales, pending and active listings used for pricing, and must not be presented as an appraisal. Lenders' valuation requirements call for an appraisal by a licensed or certified appraiser, not a CMA.", "trap": "wrong-context", "difficulty": 2, "outline": "III.C.1"}, {"id": "gen-val-018", "part": "general", "topic": "Valuation", "q": "A bank pays a broker to estimate the likely selling price of a foreclosed home it owns, based on a drive-by and recent sales. The broker's report is a:", "a": ["Assessment", "Automated valuation model (AVM)", "Broker price opinion (BPO)", "Certified appraisal"], "c": 2, "why": "An estimate of price by a broker for a lender or owner, usually for a fee, is a broker price opinion. It is not an appraisal, because only a licensed or certified appraiser can produce one.", "trap": "familiar-term", "difficulty": 1, "outline": "III.C.1"}, {"id": "gen-val-019", "part": "general", "topic": "Valuation", "q": "A buyer shows his agent an online automated estimate that is $40,000 higher than the agent's CMA. The best explanation is that an AVM:", "a": ["Is an appraisal, so it overrides the CMA", "Is always more accurate because it uses more sales", "Is prepared by a licensed appraiser who reviews each listing", "Uses computer models and public data and does not see the home's condition or recent upgrades, so it can miss the mark"], "c": 3, "why": "An AVM is a statistical model; it never inspects the property, so condition and local details can throw it off. It is not an appraisal and is not prepared by an appraiser.", "trap": "too-simple", "difficulty": 2, "outline": "III.C.2"}, {"id": "gen-fin-001", "part": "general", "topic": "Financing", "q": "A buyer purchases a home for $400,000 and makes a 12.5% down payment. The lender charges 1.5 discount points. How much do the points cost?", "a": ["$750", "$5,250", "$6,000", "$7,500"], "c": 1, "why": "Loan = $400,000 - 12.5% ($50,000) = $350,000. Points are based on the LOAN: $350,000 x 1.5% = $5,250. Applying them to the $400,000 price gives $6,000, the classic trap.", "trap": "math-step", "difficulty": 3, "outline": "IV.A.1"}, {"id": "gen-fin-002", "part": "general", "topic": "Financing", "q": "A home's contract price is $500,000, but it appraises at $480,000. The lender's maximum loan-to-value is 90%. Ignoring closing costs, how much cash must the buyer bring to pay the full price?", "a": ["$20,000", "$48,000", "$50,000", "$68,000"], "c": 3, "why": "LTV uses the LOWER of price or appraisal: $480,000 x 90% = $432,000 max loan. Cash = $500,000 - $432,000 = $68,000. Basing the loan on the price gives $50,000, ignoring the low appraisal.", "trap": "math-step", "difficulty": 3, "outline": "IV.A.1"}, {"id": "gen-fin-003", "part": "general", "topic": "Financing", "q": "Under federal law, borrower-paid PMI on a conventional loan ends automatically when the balance is scheduled to reach what percentage of the home's original value (if payments are current)?", "a": ["75%", "78%", "80%", "90%"], "c": 1, "why": "PMI terminates automatically at 78% of original value. At 80% the borrower may REQUEST cancellation, which is why 80% is the tempting answer.", "trap": "familiar-term", "difficulty": 1, "outline": "IV.A.1"}, {"id": "gen-fin-004", "part": "general", "topic": "Financing", "q": "A $300,000, 30-year loan at 6% has a monthly principal and interest payment of $1,798.65. How much of the FIRST payment goes to principal?", "a": ["$298.65", "$1,500.00", "$1,798.65", "$18,000.00"], "c": 0, "why": "First month's interest = $300,000 x 6% / 12 = $1,500. Principal = $1,798.65 - $1,500 = $298.65. $1,500 is the interest portion, not the principal.", "trap": "math-step", "difficulty": 2, "outline": "IV.A.1"}, {"id": "gen-fin-005", "part": "general", "topic": "Financing", "q": "PITI stands for:", "a": ["Payment, index, term, and interest", "Principal, interest, title, and inspection", "Principal, interest, taxes, and insurance", "Points, interest, taxes, and insurance"], "c": 2, "why": "PITI is the full monthly housing payment: principal and interest on the loan plus property taxes and homeowner's insurance, often collected in escrow. Points are a one-time charge at closing, not part of the monthly payment.", "trap": "familiar-term", "difficulty": 1, "outline": "IV.A.1"}, {"id": "gen-fin-006", "part": "general", "topic": "Financing", "q": "A borrower earns $96,000 a year. The lender allows 28% of gross monthly income for housing and 36% for total debt. Her monthly debts are a $450 car payment, a $300 student loan, and a $50 minimum credit card payment. What is the maximum PITI she qualifies for?", "a": ["$1,440", "$2,080", "$2,240", "$2,880"], "c": 1, "why": "Monthly gross = $8,000. Housing limit = 28% = $2,240. Total limit = 36% = $2,880, minus $800 debts = $2,080. The lower figure controls, so $2,080; $2,240 ignores the back-end test.", "trap": "math-step", "difficulty": 3, "outline": "IV.A.2"}, {"id": "gen-fin-007", "part": "general", "topic": "Financing", "q": "Which monthly obligation is included in a borrower's back-end (total debt) ratio?", "a": ["The electric bill", "The cell phone bill", "Groceries", "The minimum payment on an auto loan"], "c": 3, "why": "The back-end ratio adds housing to recurring debts that appear on the credit report, such as car loans, student loans and minimum card payments. Utilities and living expenses are real costs, but they are not debts and are not counted.", "trap": "familiar-term", "difficulty": 1, "outline": "IV.A.2"}, {"id": "gen-fin-008", "part": "general", "topic": "Financing", "q": "A seller wants the buyer to take over her mortgage. The lender says the entire balance becomes due if title is transferred. Which mortgage clause gives the lender this right?", "a": ["Alienation (due-on-sale) clause", "Prepayment clause", "Defeasance clause", "Subordination clause"], "c": 0, "why": "The alienation (due-on-sale) clause lets the lender call the loan due when the property is sold or transferred, which blocks assumption without approval. Defeasance does the opposite job: it cancels the mortgage once the debt is paid.", "trap": "familiar-term", "difficulty": 2, "outline": "IV.A.3"}, {"id": "gen-fin-009", "part": "general", "topic": "Financing", "q": "Which statement correctly describes a promissory note?", "a": ["It is recorded to give the lender a security interest in the property", "It is signed by the lender, promising to fund the loan", "It is the borrower's written promise to repay, stating the amount, interest rate and payment terms, and it is evidence of the debt", "It transfers ownership of the property to the lender"], "c": 2, "why": "The note is the debt itself: a signed promise to pay with its terms, making the borrower personally liable. The security instrument that is recorded and pledges the property is the mortgage (or deed of trust), not the note.", "trap": "wrong-context", "difficulty": 2, "outline": "IV.A.4"}, {"id": "gen-fin-010", "part": "general", "topic": "Financing", "q": "In a mortgage loan, the party who gives the mortgage (the borrower) is called the:", "a": ["Mortgagee", "Trustee", "Mortgagor", "Beneficiary"], "c": 2, "why": "The borrower gives the mortgage to the lender, so the borrower is the mortgagor and the lender is the mortgagee. Mixing up the -or/-ee endings is the trap.", "trap": "opposite", "difficulty": 1, "outline": "IV.A.4"}, {"id": "gen-fin-011", "part": "general", "topic": "Financing", "q": "A conventional loan is one that:", "a": ["Is not insured or guaranteed by a government agency", "Always has a fixed rate and a 30-year term", "Is insured by FHA", "Always requires 20% down"], "c": 0, "why": "'Conventional' means no government insurance or guarantee (unlike FHA, VA and USDA loans). Conventional loans can have less than 20% down; private mortgage insurance usually covers the extra risk.", "trap": "familiar-term", "difficulty": 1, "outline": "IV.B.1"}, {"id": "gen-fin-012", "part": "general", "topic": "Financing", "q": "A loan's payments are figured on a 30-year schedule, but the entire remaining balance is due at the end of year 7. This is a:", "a": ["Interest-only loan", "Graduated payment loan", "Fully amortized loan", "Partially amortized (balloon) loan"], "c": 3, "why": "Payments that reduce principal but do not pay it off by maturity leave a balloon payment, a risky feature if the borrower cannot refinance or sell. A fully amortized loan reaches a zero balance with its last regular payment.", "trap": "familiar-term", "difficulty": 2, "outline": "IV.B.2"}, {"id": "gen-fin-013", "part": "general", "topic": "Financing", "q": "An ARM started at 4.25%. At the first adjustment the index is 4.10% and the margin is 2.75%. The loan has a 2% cap per adjustment. What is the new interest rate?", "a": ["2.75%", "4.10%", "6.25%", "6.85%"], "c": 2, "why": "Index + margin = 6.85%, but the rate can rise only 2 points per adjustment: 4.25% + 2% = 6.25%. 6.85% ignores the periodic cap.", "trap": "math-step", "difficulty": 3, "outline": "IV.B.3"}, {"id": "gen-fin-014", "part": "general", "topic": "Financing", "q": "Which statement about FHA and VA loans is correct?", "a": ["FHA insures loans made by approved lenders; VA guarantees part of loans made to eligible veterans", "FHA mortgage insurance protects the borrower if he loses his job", "FHA guarantees loans; VA insures them", "FHA and VA lend money directly to buyers"], "c": 0, "why": "FHA INSURES and VA GUARANTEES; in both cases an approved private lender makes the loan, and the protection is for the lender. Swapping 'insures' and 'guarantees' is the classic trap.", "trap": "opposite", "difficulty": 1, "outline": "IV.B.4"}, {"id": "gen-fin-015", "part": "general", "topic": "Financing", "q": "USDA Rural Development guaranteed loans are designed for:", "a": ["Homes in major city centers only", "Eligible veterans and surviving spouses only", "Investors buying buildings with 5 or more units", "Low-to-moderate income buyers purchasing in eligible rural areas, often with no down payment"], "c": 3, "why": "USDA loans support homeownership in eligible rural areas for buyers within income limits, often with no down payment. Zero-down financing for veterans is the VA program, which is the tempting mix-up.", "trap": "wrong-context", "difficulty": 1, "outline": "IV.B.4"}, {"id": "gen-fin-016", "part": "general", "topic": "Financing", "q": "Under a land contract (contract for deed), during the payment period:", "a": ["The seller keeps legal title, and the buyer has possession and equitable title", "A bank holds legal title in escrow and collects payments", "The buyer has no right to occupy until the final payment", "The buyer gets a deed at signing and gives the seller a mortgage"], "c": 0, "why": "In a land contract the seller finances the sale and keeps legal title until the buyer finishes paying, while the buyer occupies the property. A deed at signing with a mortgage back to the seller describes a purchase-money mortgage, a different form of owner financing.", "trap": "familiar-term", "difficulty": 2, "outline": "IV.B.4"}, {"id": "gen-fin-017", "part": "general", "topic": "Financing", "q": "A 72-year-old homeowner with a paid-off house wants monthly income from her equity without making monthly loan payments. Which loan best fits?", "a": ["A wraparound mortgage", "A bridge loan", "A home equity line of credit", "A reverse mortgage"], "c": 3, "why": "A reverse mortgage pays the owner from her equity, and the balance grows until she sells, moves out permanently or dies. A HELOC also taps equity but requires regular payments.", "trap": "wrong-context", "difficulty": 2, "outline": "IV.B.4"}, {"id": "gen-fin-018", "part": "general", "topic": "Financing", "q": "A couple wants to buy a new home before their current home sells, using short-term financing secured by their existing equity until the sale closes. This is a:", "a": ["Blanket mortgage", "Bridge loan", "Reverse mortgage", "Construction loan"], "c": 1, "why": "A bridge loan is short-term financing that 'bridges' the gap between buying and selling. A construction loan is also short-term, but it funds building in draws as work is completed.", "trap": "familiar-term", "difficulty": 2, "outline": "IV.B.4"}, {"id": "gen-fin-019", "part": "general", "topic": "Financing", "q": "A title company offers a salesperson a $50 gift card for every buyer she sends to it. Under RESPA, this is:", "a": ["Legal if the gift card is under $100", "Legal because the salesperson is not the lender", "An illegal kickback, even if small and disclosed", "Legal if disclosed to the buyer in writing"], "c": 2, "why": "RESPA forbids giving or accepting anything of value for referring settlement-service business; fees must be for services actually performed. Disclosure makes an affiliated business arrangement legal, but it does not cure a referral payment.", "trap": "too-simple", "difficulty": 2, "outline": "IV.C.1"}, {"id": "gen-fin-020", "part": "general", "topic": "Financing", "q": "Which advertising phrase, used alone, is a 'trigger term' that requires full Truth-in-Lending disclosures?", "a": ["\"Easy monthly payments\"", "\"Financing available\"", "\"Only $1,850 per month!\"", "\"6.9% APR\""], "c": 2, "why": "A specific payment amount is a trigger term, so the ad must then state the down payment, repayment terms and APR. Stating the APR by itself is allowed and triggers nothing more.", "trap": "familiar-term", "difficulty": 2, "outline": "IV.C.2"}, {"id": "gen-fin-021", "part": "general", "topic": "Financing", "q": "Under TRID, the borrower must receive the Closing Disclosure at least how long before closing (consummation)?", "a": ["10 calendar days", "3 business days", "30 days", "1 business day"], "c": 1, "why": "The Closing Disclosure must be received at least 3 business days before consummation. The other 3-day TRID deadline (Loan Estimate within 3 business days AFTER application) runs on a different clock, which is the usual mix-up.", "trap": "familiar-term", "difficulty": 1, "outline": "IV.C.3"}, {"id": "gen-fin-022", "part": "general", "topic": "Financing", "q": "During a loan application, a loan officer asks a married applicant whether she plans to have children soon, to judge whether her income will continue. Under the Equal Credit Opportunity Act this question is:", "a": ["Allowed if asked of every applicant", "Required to document income stability", "Allowed for FHA loans only", "Prohibited"], "c": 3, "why": "ECOA bars discrimination based on sex and marital status, and lenders may not ask about childbearing plans. Asking everyone the same question does not make a prohibited inquiry lawful.", "trap": "too-simple", "difficulty": 3, "outline": "IV.C.4"}, {"id": "gen-fin-023", "part": "general", "topic": "Financing", "q": "Which sequence of the lending process is in the correct order?", "a": ["Application, Loan Estimate, appraisal and processing, underwriting approval, Closing Disclosure, closing", "Underwriting approval, application, appraisal, Closing Disclosure, Loan Estimate", "Application, Closing Disclosure, underwriting, Loan Estimate, closing", "Loan Estimate, application, closing, appraisal, Closing Disclosure"], "c": 0, "why": "The Loan Estimate follows the application, the file is processed and underwritten, and the Closing Disclosure comes last before closing. Any order that places the Closing Disclosure before underwriting is wrong, because final terms are not known until approval.", "trap": "none", "difficulty": 2, "outline": "IV.C.5"}, {"id": "gen-fin-024", "part": "general", "topic": "Financing", "q": "A homeowner refinances her principal residence with a new lender. Under the Truth in Lending Act, she may cancel the loan:", "a": ["Only if the lender agrees", "Within 3 business days after closing, under the right of rescission", "Within 30 days after closing", "Never, because rescission applies only to loans used to buy a home"], "c": 1, "why": "The right of rescission covers refinances (with a new lender) and home equity loans secured by a principal residence. It does NOT apply to purchase-money loans, which is the opposite of the trap answer.", "trap": "opposite", "difficulty": 3, "outline": "IV.C.2"}, {"id": "gen-prac-001", "part": "general", "topic": "Practice of Real Estate", "q": "Which of these is a protected class under the federal Fair Housing Act?", "a": ["Familial status", "Marital status", "Age", "Source of income"], "c": 0, "why": "Familial status (a household with a child under 18, including pregnancy or pending custody) is one of the seven federal classes. Marital status, age and source of income are protected by some states, not by the federal Act.", "trap": "familiar-term", "difficulty": 1, "outline": "X.A.2"}, {"id": "gen-prac-002", "part": "general", "topic": "Practice of Real Estate", "q": "A woman owns a two-family house and lives in one unit. She rents the other unit herself, with no broker and no discriminatory advertising. Which statement is most accurate?", "a": ["She may be exempt from the 1968 Fair Housing Act, but she still may not refuse a tenant because of race", "She is exempt from every federal fair housing law, including race", "She is exempt only if a licensed broker handles the rental", "She cannot be exempt because the building has more than one unit"], "c": 0, "why": "Owner-occupied buildings of 2 to 4 units can be exempt from the 1968 Act if no broker and no discriminatory ad are used. The Civil Rights Act of 1866 has no exemptions, so race discrimination is still illegal; that is why 'exempt from every law' is wrong.", "trap": "too-simple", "difficulty": 2, "outline": "X.A.1"}, {"id": "gen-prac-003", "part": "general", "topic": "Practice of Real Estate", "q": "An agent shows a buyer only homes in neighborhoods where most residents share the buyer's national origin, even though the buyer asked to see the whole town. This practice is called:", "a": ["Blockbusting", "Redlining", "Steering", "Puffing"], "c": 2, "why": "Steering means channeling buyers toward or away from areas based on a protected class. Blockbusting is scaring owners into selling; redlining is a lender refusing loans in an area.", "trap": "familiar-term", "difficulty": 1, "outline": "X.A.4"}, {"id": "gen-prac-004", "part": "general", "topic": "Practice of Real Estate", "q": "A lender declines all loan applications for homes in one neighborhood because of the racial makeup of its residents, regardless of each applicant's credit. This is:", "a": ["Steering", "Redlining", "Blockbusting", "Disparate advertising"], "c": 1, "why": "Redlining is refusing or limiting loans in an area because of who lives there. Steering is done by agents showing homes, not by lenders denying credit.", "trap": "familiar-term", "difficulty": 2, "outline": "X.A.4"}, {"id": "gen-prac-005", "part": "general", "topic": "Practice of Real Estate", "q": "An agent mails postcards to a street saying, 'Families of a certain religion are moving in. Sell now before prices drop. Call me today.' This is:", "a": ["Steering", "Redlining", "Lawful prospecting, because it contains a phone number", "Blockbusting"], "c": 3, "why": "Blockbusting (panic peddling) uses fear that a protected group is moving in to get owners to sell. Steering involves directing buyers, not frightening sellers.", "trap": "familiar-term", "difficulty": 2, "outline": "X.A.4"}, {"id": "gen-prac-006", "part": "general", "topic": "Practice of Real Estate", "q": "Which listing description is acceptable under fair housing advertising rules?", "a": ["Ideal for a young professional couple", "Three-bedroom ranch, fenced yard, two blocks from the commuter rail", "Quiet building, no children", "Perfect for a Catholic family, steps from St. Anne's"], "c": 1, "why": "Fair housing ads describe the property, not the people who should live there. The other choices state a preference by age or familial status, familial status, or religion.", "trap": "familiar-term", "difficulty": 1, "outline": "X.A.5"}, {"id": "gen-prac-007", "part": "general", "topic": "Practice of Real Estate", "q": "A tenant with a documented disability asks to keep an emotional support animal in a building with a no-pets policy. The landlord agrees but wants to charge the standard $500 pet deposit. Under federal fair housing law:", "a": ["The deposit is allowed because only trained service dogs are exempt from pet fees", "The landlord may refuse the animal because the building bans all pets", "The animal is a reasonable accommodation, so no pet deposit may be charged, though the tenant is still liable for any damage", "The deposit is allowed if it is refundable"], "c": 2, "why": "Under the Fair Housing Act an assistance animal, including an emotional support animal, is a reasonable accommodation, not a pet, so pet fees and deposits do not apply. The 'trained service dog only' idea comes from the ADA, which governs public places, not housing.", "trap": "wrong-context", "difficulty": 3, "outline": "X.A.6"}, {"id": "gen-prac-008", "part": "general", "topic": "Practice of Real Estate", "q": "Under the federal Fair Housing Act, a tenant who uses a wheelchair asks to install grab bars in the bathroom of a privately owned apartment. Generally:", "a": ["The landlord must allow the modification, and the tenant usually pays for it", "The landlord must allow it and must pay for it", "The landlord may refuse because it changes the unit", "The landlord may allow it only if the tenant pays double the security deposit"], "c": 0, "why": "A reasonable modification changes the physical unit; federally the landlord must permit it but the tenant generally pays (and may have to restore the unit if reasonable). Some states, not the federal Act, require landlords of larger buildings to pay.", "trap": "opposite", "difficulty": 2, "outline": "X.A.6"}, {"id": "gen-prac-009", "part": "general", "topic": "Practice of Real Estate", "q": "A person who believes they faced housing discrimination wants to file an administrative complaint with HUD. The deadline is generally:", "a": ["180 days after the incident", "2 years after the incident", "90 days after the incident", "1 year after the incident"], "c": 3, "why": "HUD complaints must be filed within 1 year. Two years is the deadline for a private suit in federal court, which is the number people mix up.", "trap": "familiar-term", "difficulty": 1, "outline": "X.A.1"}, {"id": "gen-prac-010", "part": "general", "topic": "Practice of Real Estate", "q": "The owners of two competing brokerages agree that both firms will charge every seller a 6% commission. This is an example of:", "a": ["Market allocation", "A group boycott", "Price fixing", "A tie-in arrangement"], "c": 2, "why": "Competitors agreeing on the fees they will charge is price fixing, a per se violation of the Sherman Antitrust Act. Market allocation would be dividing up territories or customers instead.", "trap": "none", "difficulty": 1, "outline": "X.B.2"}, {"id": "gen-prac-011", "part": "general", "topic": "Practice of Real Estate", "q": "Two brokers agree that one will take listings only north of the river and the other only south of it, so they stop competing. This is:", "a": ["Price fixing", "A group boycott", "Market allocation", "Steering"], "c": 2, "why": "Dividing a market by geography, price range or customer type is market allocation, an antitrust violation. No fee was agreed, so it is not price fixing.", "trap": "familiar-term", "difficulty": 2, "outline": "X.B.2"}, {"id": "gen-prac-012", "part": "general", "topic": "Practice of Real Estate", "q": "At a networking lunch, an agent from another firm says, 'We should all stop discounting. Let's everyone stick to 5% this year.' What is the best response?", "a": ["Agree, as long as nothing is put in writing", "Agree, because salespeople, unlike brokers, are not covered by antitrust law", "Agree, as long as 5% is the customary rate in the area", "Object clearly and leave the conversation, because even discussing fees with competitors can be evidence of a conspiracy"], "c": 3, "why": "Commission rates must be set independently by each firm. A spoken agreement is still a conspiracy, and antitrust law applies to every licensee; that is why 'nothing in writing' fails.", "trap": "too-simple", "difficulty": 3, "outline": "X.B.2"}, {"id": "gen-prac-013", "part": "general", "topic": "Practice of Real Estate", "q": "A broker agrees to sell a developer's lots only if the developer also hires the broker's affiliated company to manage the finished homes. This is best described as:", "a": ["Price fixing", "A tie-in (tying) arrangement", "Market allocation", "Commingling"], "c": 1, "why": "Conditioning one product or service on the purchase of another is a tying arrangement, which antitrust law can prohibit. No competitors agreed on fees, so it is not price fixing.", "trap": "none", "difficulty": 2, "outline": "X.B.2"}, {"id": "gen-prac-014", "part": "general", "topic": "Practice of Real Estate", "q": "To treat a real estate salesperson as an independent contractor for federal tax purposes, all of these are required EXCEPT:", "a": ["The broker withholds income tax from each commission check", "The salesperson holds a real estate license", "Substantially all pay is based on sales output, not hours worked", "A written contract states the salesperson will not be treated as an employee for tax purposes"], "c": 0, "why": "The IRS 'statutory nonemployee' test has three parts: licensed, paid on output, and a written contract saying not an employee. Withholding tax is what an employer does for an employee, so it is the opposite of the test.", "trap": "opposite", "difficulty": 2, "outline": "X.B.1"}, {"id": "gen-prac-015", "part": "general", "topic": "Practice of Real Estate", "q": "A brokerage that makes telemarketing calls must check its call lists against the National Do Not Call Registry at least every:", "a": ["90 days", "6 months", "12 months", "31 days"], "c": 3, "why": "Telemarketers must download the registry and scrub their lists at least every 31 days. Ninety days is a familiar-sounding number with no role in this rule.", "trap": "familiar-term", "difficulty": 1, "outline": "X.B.3"}, {"id": "gen-prac-016", "part": "general", "topic": "Practice of Real Estate", "q": "A consumer whose number is on the National Do Not Call Registry sent an online inquiry about a listing two months ago. She has never bought or sold through the firm. May an agent make a sales call to her?", "a": ["Yes, an inquiry creates an established business relationship for 3 months", "Yes, for up to 18 months after the inquiry", "No, a registered number may never be called", "Yes, but only between 9 a.m. and 5 p.m."], "c": 0, "why": "An inquiry or application allows calls for 3 months; 2 months is inside that window. The 18-month window applies only after an actual transaction, which she never had.", "trap": "familiar-term", "difficulty": 3, "outline": "X.B.3"}, {"id": "gen-prac-017", "part": "general", "topic": "Practice of Real Estate", "q": "A broker deposits a buyer's earnest money into the firm's general operating account. This is:", "a": ["Commingling", "Conversion", "Novation", "Escheat"], "c": 0, "why": "Mixing client money with the broker's own funds is commingling. Conversion is the more serious step of actually using client money for the broker's own purposes.", "trap": "familiar-term", "difficulty": 1, "outline": "X.C.2"}, {"id": "gen-prac-018", "part": "general", "topic": "Practice of Real Estate", "q": "A broker uses money from the escrow account to pay the office rent, planning to put it back next week. This is:", "a": ["Conversion, and repaying the money later does not cure the violation", "Commingling, but it is allowed if repaid within 30 days", "Permitted, because the broker controls the escrow account", "Permitted if the clients are told afterward"], "c": 0, "why": "Spending client funds for the broker's own use is conversion (theft of trust funds), even if repaid. Commingling is only mixing funds, not spending them.", "trap": "familiar-term", "difficulty": 2, "outline": "X.C.2"}, {"id": "gen-prac-019", "part": "general", "topic": "Practice of Real Estate", "q": "A mortgage lender offers an agent a $50 gift card for every buyer the agent refers. Under RESPA:", "a": ["Accepting is legal if the agent tells the buyer", "Accepting is legal if the total stays under $600 a year", "Accepting is an illegal kickback, even though the amount is small", "Accepting is legal because the agent is not a lender"], "c": 2, "why": "RESPA Section 8 bans giving or accepting anything of value for referring settlement-service business. Disclosure does not make a referral fee legal; that is only the rule for properly structured affiliated businesses.", "trap": "too-simple", "difficulty": 2, "outline": "IV.C.1"}, {"id": "gen-prac-020", "part": "general", "topic": "Practice of Real Estate", "q": "Which payment is permitted under RESPA?", "a": ["A title company paying an agent $100 for each closing the agent sends it", "A listing broker sharing a commission with the cooperating broker who brought the buyer", "A home inspector buying an agent dinner every month in return for referrals", "A lender paying an agent's MLS dues in exchange for referrals"], "c": 1, "why": "Commission splits between brokers for real estate services they performed are allowed. The other payments are things of value given for referrals, which RESPA prohibits.", "trap": "familiar-term", "difficulty": 2, "outline": "IV.C.1"}, {"id": "gen-prac-021", "part": "general", "topic": "Practice of Real Estate", "q": "A brokerage owns part of a title insurance company, and its agents suggest that company to buyers. Under RESPA this affiliated business arrangement is lawful if:", "a": ["The title company's prices are lower than its competitors'", "The buyer gets a written disclosure of the relationship and estimated charges, and is not required to use the company", "The buyer signs a waiver giving up the right to choose a title company", "The agents receive no commission on the sale"], "c": 1, "why": "Affiliated business arrangements are allowed with written disclosure, no required use, and returns based only on ownership. Low prices alone do not remove the disclosure and free-choice requirements.", "trap": "too-simple", "difficulty": 3, "outline": "IV.C.1"}, {"id": "gen-prac-022", "part": "general", "topic": "Practice of Real Estate", "q": "A seller tells his agent the house has 2,400 square feet, and the agent advertises that number. A buyer's appraisal later shows 2,000 square feet. What should the agent have done?", "a": ["Nothing, because a seller's statement protects the agent", "Verified the figure from a reliable source, or stated the source and advised buyers to verify it", "Rounded the figure down to be safe", "Left square footage out of all advertising"], "c": 1, "why": "Licensees must use due diligence on facts they publish. Relying blindly on the seller does not protect an agent who repeats a figure he could have checked.", "trap": "too-simple", "difficulty": 2, "outline": "X.C.3"}, {"id": "gen-prac-023", "part": "general", "topic": "Practice of Real Estate", "q": "An agent posts a new listing on her personal social media page. Which statement is correct?", "a": ["Personal pages are exempt from advertising rules", "Rules apply only if the agent pays to boost the post", "The post is advertising, so fair housing, truth-in-advertising and brokerage identification rules apply", "Only the broker's posts are covered by advertising rules"], "c": 2, "why": "Any public promotion of a listing is advertising, whatever the platform. Whether the post is paid or on a personal page does not change the rules.", "trap": "wrong-context", "difficulty": 1, "outline": "X.B.4"}, {"id": "gen-disc-001", "part": "general", "topic": "Property Disclosures", "q": "The federal lead-based paint disclosure rule applies to the sale or lease of most housing built before:", "a": ["1971", "1978", "1986", "1990"], "c": 1, "why": "Lead paint was banned for residential use nationally in 1978, so pre-1978 housing is covered. 1971 is a state-level date in some places, which is why it tempts people.", "trap": "familiar-term", "difficulty": 1, "outline": "VII.B.2"}, {"id": "gen-disc-002", "part": "general", "topic": "Property Disclosures", "q": "Under the federal lead rule, a buyer of pre-1978 housing must be offered an opportunity to conduct a lead inspection or risk assessment of:", "a": ["3 business days, which cannot be waived", "10 days, which the buyer may waive", "30 days, which the buyer may waive", "No set period; it is up to the seller"], "c": 1, "why": "Federal law gives buyers 10 days (or another period they agree to) and they may waive it in writing. Three business days is the rescission and Closing Disclosure clock, a different law.", "trap": "familiar-term", "difficulty": 2, "outline": "VII.B.2"}, {"id": "gen-disc-003", "part": "general", "topic": "Property Disclosures", "q": "When selling pre-1978 housing, federal law requires the seller to do all of the following EXCEPT:", "a": ["Give the buyer the EPA lead hazard information pamphlet", "Disclose any known lead-based paint and provide available reports", "Remove all lead-based paint before closing", "Include the Lead Warning Statement in the sales contract"], "c": 2, "why": "The federal rule is a disclosure rule; it does not require the seller to remove or abate lead. Pamphlet, known information and reports, and the warning statement are all required.", "trap": "opposite", "difficulty": 2, "outline": "VII.B.2"}, {"id": "gen-disc-004", "part": "general", "topic": "Property Disclosures", "q": "A material fact is best described as a fact that:", "a": ["The seller has written down in a disclosure form", "A reasonable buyer would consider important to the decision to buy or the price to pay", "Appears in the public records", "Was discovered by a licensed home inspector"], "c": 1, "why": "Materiality is about whether the fact would affect a reasonable person's decision or price. A fact can be material whether or not it is written down or recorded anywhere.", "trap": "none", "difficulty": 1, "outline": "VII.C"}, {"id": "gen-disc-005", "part": "general", "topic": "Property Disclosures", "q": "A cracked foundation hidden behind a finished basement wall, which an ordinary inspection would not reveal, is a:", "a": ["Latent defect", "Patent defect", "Functional obsolescence", "Stigma"], "c": 0, "why": "A latent defect is hidden and not discoverable by reasonable inspection, so known latent defects must be disclosed. A patent defect is one that is plainly visible.", "trap": "familiar-term", "difficulty": 1, "outline": "VII.C"}, {"id": "gen-disc-006", "part": "general", "topic": "Property Disclosures", "q": "A seller tells the listing agent, 'Don't mention that the roof leaks in heavy rain. That's confidential.' The agent should:", "a": ["Keep the leak secret, because the duty of confidentiality requires it", "Keep the leak secret unless a buyer asks directly about the roof", "Tell the seller the leak must be disclosed to buyers, and withdraw from the listing if the seller refuses", "Disclose the leak only to buyers who are represented by an agent"], "c": 2, "why": "Confidentiality and obedience never extend to hiding known material defects; agents owe honesty to all parties. Following an unlawful instruction is not part of the duty of obedience.", "trap": "familiar-term", "difficulty": 3, "outline": "VII.C"}, {"id": "gen-disc-007", "part": "general", "topic": "Property Disclosures", "q": "A home where a well-known crime occurred several years ago, with no physical damage to the house, is often called:", "a": ["A brownfield", "A stigmatized property", "An encroachment", "A nonconforming use"], "c": 1, "why": "A stigmatized property carries a psychological impact (death, crime, rumors) rather than a physical defect. State laws differ on whether stigmas must be disclosed, but the term is the same.", "trap": "none", "difficulty": 1, "outline": "VII.C"}, {"id": "gen-disc-008", "part": "general", "topic": "Property Disclosures", "q": "A buyer asks the listing agent whether the previous owner had AIDS. The agent knows the owner did. The agent should:", "a": ["Answer truthfully, because it is a material fact", "Answer only if the buyer puts the question in writing", "Tell the buyer to ask the seller directly instead", "Decline to answer, because HIV/AIDS is a disability protected by fair housing law"], "c": 3, "why": "HIV/AIDS is a handicap under the federal Fair Housing Act, and disclosing it to steer a buyer would be discriminatory; it is not a material fact about the property. Sending the buyer to the seller only shifts the same improper disclosure.", "trap": "opposite", "difficulty": 3, "outline": "VII.C"}, {"id": "gen-disc-009", "part": "general", "topic": "Property Disclosures", "q": "The EPA recommends fixing a home when indoor radon levels are at or above:", "a": ["10 pCi/L", "0.4 pCi/L", "40 pCi/L", "4 picocuries per liter (pCi/L)"], "c": 3, "why": "The EPA action level for radon is 4 pCi/L. Radon is a radioactive gas from the soil that enters through foundation cracks; only testing can detect it.", "trap": "familiar-term", "difficulty": 1, "outline": "VII.B.1"}, {"id": "gen-disc-010", "part": "general", "topic": "Property Disclosures", "q": "A home inspector finds intact, undamaged asbestos insulation on old heating pipes. The usual guidance is:", "a": ["Have the homeowner remove it right away", "Sand and repaint it", "Ignore it, since asbestos is only dangerous if eaten", "Leave it undisturbed or have it encapsulated by a professional, and monitor it"], "c": 3, "why": "Asbestos is dangerous when fibers become airborne (friable). Disturbing intact material, such as an amateur removal, releases fibers and creates the hazard.", "trap": "too-simple", "difficulty": 2, "outline": "VII.B.1"}, {"id": "gen-disc-011", "part": "general", "topic": "Property Disclosures", "q": "Under the federal Superfund law (CERCLA), a buyer purchases land that a prior owner contaminated with hazardous waste. Who can be held liable for cleanup?", "a": ["Only the party who actually dumped the waste", "The current owner, even though a prior owner caused it, along with other responsible parties", "Only the government agency that discovered it", "No one, if the contamination happened before the current owner bought"], "c": 1, "why": "CERCLA liability is strict, joint and several, and retroactive, so current owners can be liable for past contamination. That is why buyers of commercial land order environmental site assessments before buying.", "trap": "too-simple", "difficulty": 3, "outline": "VII.B.1"}, {"id": "gen-disc-012", "part": "general", "topic": "Property Disclosures", "q": "During a showing, a buyer notices the seller's fence appears to be several feet onto the neighbor's land. What should the agent recommend?", "a": ["A survey to locate the boundary lines", "An appraisal", "A radon test", "A title insurance endorsement only"], "c": 0, "why": "A possible encroachment or boundary problem calls for a survey. An appraisal estimates value; it does not locate boundary lines.", "trap": "none", "difficulty": 1, "outline": "VII.A.2"}, {"id": "gen-disc-013", "part": "general", "topic": "Property Disclosures", "q": "A buyer plans to open a home daycare and add a rental unit over the garage. Before the buyer commits, the agent should advise:", "a": ["Checking local zoning and any recorded deed restrictions or HOA rules for those uses", "Relying on the seller's statement that the neighbors would not mind", "Nothing, because owners may use their property any way they wish", "Getting a home warranty to cover the uses"], "c": 0, "why": "Planned uses are red flags for both public controls (zoning) and private controls (deed restrictions, covenants, HOA rules). Ownership does not override land use controls.", "trap": "too-simple", "difficulty": 3, "outline": "VII.A.3"}, {"id": "gen-title-001", "part": "general", "topic": "Transfer of Title", "q": "Which type of deed gives the buyer the greatest protection?", "a": ["Special warranty deed", "Quitclaim deed (in most states)", "General warranty deed", "Sheriff's deed"], "c": 2, "why": "A general warranty deed defends title against claims from any time, even before the grantor owned it. A special warranty deed covers only the grantor's own period of ownership.", "trap": "none", "difficulty": 1, "outline": "IX.A"}, {"id": "gen-title-002", "part": "general", "topic": "Transfer of Title", "q": "In most states, a former spouse is asked to sign a deed releasing any interest she might have in a property, without making any promises about the title. Which deed fits?", "a": ["Quitclaim deed", "General warranty deed", "Special warranty deed", "Deed of trust"], "c": 0, "why": "A quitclaim conveys whatever interest the grantor has, if any, with no warranties, which makes it the standard tool for clearing a possible cloud. A deed of trust secures a loan; it does not release an owner's interest.", "trap": "familiar-term", "difficulty": 2, "outline": "IX.A"}, {"id": "gen-title-003", "part": "general", "topic": "Transfer of Title", "q": "Title to real estate generally passes from seller to buyer when:", "a": ["The deed is recorded at the registry", "The seller signs the deed", "A valid deed is delivered by the grantor and accepted by the grantee", "The purchase and sale agreement is signed"], "c": 2, "why": "Delivery and acceptance transfer title. Recording comes afterward and protects the buyer against third parties; it does not create the transfer.", "trap": "familiar-term", "difficulty": 2, "outline": "IX.C.1"}, {"id": "gen-title-004", "part": "general", "topic": "Transfer of Title", "q": "The main purpose of recording a deed is to:", "a": ["Make the deed valid between buyer and seller", "Give constructive notice to the world and protect the buyer's priority", "Transfer title from seller to buyer", "Replace the need for title insurance"], "c": 1, "why": "Recording puts everyone on notice and sets priority. A deed is already valid between the parties once delivered and accepted, even if it is never recorded.", "trap": "opposite", "difficulty": 2, "outline": "IX.C.2"}, {"id": "gen-title-005", "part": "general", "topic": "Transfer of Title", "q": "An owner sells a lot to Buyer 1, who does not record the deed. The owner then sells the same lot to Buyer 2, who pays fair value, has no notice of the first sale, and records right away. Who generally has the better claim?", "a": ["Buyer 1, because that sale happened first", "Buyer 2, the good-faith buyer who recorded first", "Neither; the lot returns to the owner", "Both share ownership as tenants in common"], "c": 1, "why": "An unrecorded deed does not protect against a later good-faith purchaser for value who records first. 'First in time' loses here because Buyer 1 failed to give public notice.", "trap": "too-simple", "difficulty": 3, "outline": "IX.C.2"}, {"id": "gen-title-006", "part": "general", "topic": "Transfer of Title", "q": "An owner's title insurance policy generally:", "a": ["Decreases in coverage as the mortgage is paid down", "Protects only the lender", "Is paid with a one-time premium and protects the owner as long as the owner or heirs hold an interest", "Must be renewed every year"], "c": 2, "why": "An owner's policy is a single premium at closing and lasts as long as the owner or heirs have an interest. Coverage that shrinks with the loan balance describes the lender's policy.", "trap": "familiar-term", "difficulty": 2, "outline": "IX.B.1"}, {"id": "gen-title-007", "part": "general", "topic": "Transfer of Title", "q": "A title search shows a mortgage from 15 years ago that the seller says was paid off, but no discharge was ever recorded. What is the usual fix?", "a": ["Ignore it, because old mortgages expire automatically after 10 years", "Have the buyer sign a quitclaim deed to the seller", "Add the old mortgage amount to the sale price", "Obtain and record a discharge (release) from the old lender or its successor"], "c": 3, "why": "An unreleased mortgage is a cloud on title until a discharge is recorded (or, if the lender cannot be found, a court action clears it). Having the buyer sign a quitclaim does nothing about the lender's recorded interest.", "trap": "too-simple", "difficulty": 2, "outline": "IX.B.2"}, {"id": "gen-title-008", "part": "general", "topic": "Transfer of Title", "q": "Marketable title is best described as title that:", "a": ["Is reasonably free of defects, so a prudent buyer would accept it", "Has no mortgages recorded against it at any time in its history", "Is held by a single owner", "Has been registered with a court"], "c": 0, "why": "Marketable title means reasonably free from serious defects or doubts, not a history with zero liens. Paid-off and released mortgages do not make title unmarketable.", "trap": "none", "difficulty": 1, "outline": "IX.B.3"}, {"id": "gen-title-009", "part": "general", "topic": "Transfer of Title", "q": "The seller paid this year's property taxes in full in advance. The sale closes mid-year. On the settlement statement, the tax proration is:", "a": ["A credit to the buyer and a debit to the seller", "A debit to both parties", "Not shown, because the taxes are already paid", "A credit to the seller and a debit to the buyer"], "c": 3, "why": "The seller paid for days the buyer will own, so the buyer reimburses the seller: credit seller, debit buyer. The reverse applies when taxes are paid in arrears and still unpaid.", "trap": "opposite", "difficulty": 2, "outline": "IX.C.3"}, {"id": "gen-title-010", "part": "general", "topic": "Transfer of Title", "q": "A seller of a four-unit building holds $6,000 in tenant security deposits. Closing is on the 10th of the month. At closing the deposits are:", "a": ["Prorated by the number of days each party owns the property", "Kept by the seller as income", "Split equally between buyer and seller", "Credited to the buyer in full, because the buyer takes over the duty to return them"], "c": 3, "why": "Security deposits belong to the tenants, so the full amount transfers to the new owner. They are not income, so they are never prorated by days.", "trap": "too-simple", "difficulty": 3, "outline": "IX.C.3"}, {"id": "gen-title-011", "part": "general", "topic": "Transfer of Title", "q": "Which is most typical when buying a bank-owned (REO) property after foreclosure?", "a": ["The bank guarantees the condition of all systems for one year", "It is sold as-is, the bank has little knowledge of its condition, and the buyer should inspect carefully", "The former owner must complete a full condition disclosure", "No title insurance is available on foreclosed property"], "c": 1, "why": "Lenders usually sell REO property as-is and often never lived in it, so they offer limited disclosures. Title insurance is still available and recommended.", "trap": "none", "difficulty": 2, "outline": "IX.D.1"}, {"id": "gen-title-012", "part": "general", "topic": "Transfer of Title", "q": "In a short sale, the seller's lender must approve the sale because:", "a": ["The buyer is assuming the seller's loan", "The closing must happen in less than 30 days", "The property is being sold at a sheriff's auction", "The sale price will not cover what is owed on the loan"], "c": 3, "why": "A short sale means the proceeds fall 'short' of the loan payoff, so the lender must agree to accept less. A sheriff's auction is a foreclosure, which is a different process.", "trap": "none", "difficulty": 1, "outline": "IX.D.2"}, {"id": "gen-title-013", "part": "general", "topic": "Transfer of Title", "q": "A home is being sold from the estate of an owner who died. Who usually signs the deed?", "a": ["The executor or court-appointed personal representative, often with court approval", "The listing agent under the listing agreement", "Any adult heir named in the will", "The county recorder"], "c": 0, "why": "In probate the personal representative has authority to sell, sometimes only with court approval. A single heir cannot convey the estate's title alone.", "trap": "familiar-term", "difficulty": 2, "outline": "IX.D.3"}, {"id": "gen-pm-001", "part": "general", "topic": "Property Management", "q": "A property manager who handles leasing, rent collection, repairs and bill paying for an owner is usually that owner's:", "a": ["General agent", "Special agent", "Universal agent", "Subagent"], "c": 0, "why": "A property manager has ongoing authority over a range of tasks, which makes a general agent. A listing broker with one task (find a buyer) is the classic special agent.", "trap": "familiar-term", "difficulty": 1, "outline": "VIII.A"}, {"id": "gen-pm-002", "part": "general", "topic": "Property Management", "q": "Which screening practice is proper for a property manager?", "a": ["Asking applicants whether they plan to have children", "Requiring a higher deposit from applicants with disabilities", "Running credit checks only on applicants who seem likely to have bad credit", "Applying the same written income, credit and reference standards to every applicant"], "c": 3, "why": "Consistent written criteria applied to everyone is the fair housing safe practice. Checking only some applicants is disparate treatment, even if the checks themselves are legal.", "trap": "wrong-context", "difficulty": 2, "outline": "VIII.A.1"}, {"id": "gen-pm-003", "part": "general", "topic": "Property Management", "q": "To set the rent for a vacant apartment, a property manager should mainly rely on:", "a": ["The owner's mortgage payment plus a profit", "The rent the previous tenant paid five years ago", "The highest rent advertised anywhere in the city", "Rents for comparable units in the area, adjusted for differences"], "c": 3, "why": "Rents are set by the market, through a comparison of similar units. The owner's costs do not determine what tenants will pay.", "trap": "too-simple", "difficulty": 2, "outline": "VIII.A.3"}, {"id": "gen-pm-004", "part": "general", "topic": "Property Management", "q": "Tenant security deposits collected by a property manager should be kept:", "a": ["In the manager's business operating account", "In the owner's personal checking account to pay bills", "In a trust or escrow account separate from the manager's own funds", "In cash in the office safe"], "c": 2, "why": "Deposits are other people's money and must be kept apart from the manager's funds. Putting them in the operating account would be commingling.", "trap": "familiar-term", "difficulty": 1, "outline": "VIII.A.5"}, {"id": "gen-pm-005", "part": "general", "topic": "Property Management", "q": "Changing furnace filters every three months to prevent breakdowns is an example of:", "a": ["Corrective maintenance", "Construction (new improvements)", "Preventive maintenance", "Deferred maintenance"], "c": 2, "why": "Preventive maintenance heads off problems before they happen. Corrective maintenance fixes something already broken.", "trap": "familiar-term", "difficulty": 1, "outline": "VIII.A.4"}, {"id": "gen-pm-006", "part": "general", "topic": "Property Management", "q": "A property manager runs a small retail building open to the public. Under the Americans with Disabilities Act, the owner must generally:", "a": ["Rebuild the entire building to new-construction standards immediately", "Make changes only if a disabled tenant pays for them", "Do nothing, because the ADA covers only housing", "Remove architectural barriers to access where this is readily achievable"], "c": 3, "why": "Title III of the ADA covers public accommodations and requires barrier removal that is readily achievable (easy and inexpensive). The ADA covers public places; housing falls under the Fair Housing Act instead.", "trap": "wrong-context", "difficulty": 3, "outline": "VIII.A.2"}, {"id": "gen-pm-007", "part": "general", "topic": "Property Management", "q": "A manager earns 7% of rent actually collected. The building has 12 units at $1,500 per month, and 2 units were vacant all month. What is the manager's fee for the month?", "a": ["$1,050", "$1,260", "$210", "$12,600"], "c": 0, "why": "Collected rent = 10 units x $1,500 = $15,000; x 7% = $1,050. $1,260 uses all 12 units (scheduled rent), but the fee is based on rent collected.", "trap": "math-step", "difficulty": 2, "outline": "VIII.A.5"}, {"id": "gen-math-001", "part": "general", "topic": "Real Estate Math", "q": "A rectangular parcel measures 330 feet by 660 feet. How many acres is it?", "a": ["2.5 acres", "10 acres", "5 acres", "41.25 acres"], "c": 2, "why": "330 x 660 = 217,800 sq ft; / 43,560 = 5 acres. 2.5 acres comes from halving as if it were a triangle; 41.25 divides by 5,280 (feet in a mile) instead of 43,560.", "trap": "math-step", "difficulty": 1, "outline": "I.B.5"}, {"id": "gen-math-002", "part": "general", "topic": "Real Estate Math", "q": "A triangular parcel has a 400-foot base and a 544.5-foot height. Land sells for $60,000 per acre. What is the parcel worth?", "a": ["$300,000", "$150,000", "$163,350", "$75,000"], "c": 1, "why": "Area = 1/2 x 400 x 544.5 = 108,900 sq ft; / 43,560 = 2.5 acres; x $60,000 = $150,000. $300,000 forgets the 1/2 for a triangle; $163,350 uses 40,000 sq ft per acre.", "trap": "math-step", "difficulty": 3, "outline": "I.B.5"}, {"id": "gen-math-003", "part": "general", "topic": "Real Estate Math", "q": "A driveway 60 feet long and 12 feet wide will be paved for $45 per square yard. What is the cost?", "a": ["$32,400", "$10,800", "$3,600", "$1,200"], "c": 2, "why": "60 x 12 = 720 sq ft; / 9 = 80 sq yd; x $45 = $3,600. $32,400 skips the conversion to square yards; $10,800 divides by 3 instead of 9.", "trap": "math-step", "difficulty": 2, "outline": "I.B.4"}, {"id": "gen-math-004", "part": "general", "topic": "Real Estate Math", "q": "A home sells for $425,000 with a 5% commission split equally between the listing and buyer brokerages. The listing agent receives 60% of her brokerage's share. How much does the listing agent receive?", "a": ["$6,375", "$12,750", "$10,625", "$4,250"], "c": 0, "why": "$425,000 x 5% = $21,250; / 2 = $10,625 brokerage share; x 60% = $6,375. $12,750 takes 60% of the whole commission instead of the brokerage's half.", "trap": "math-step", "difficulty": 2, "outline": "XI.A.1"}, {"id": "gen-math-005", "part": "general", "topic": "Real Estate Math", "q": "An agent's firm earned a $13,950 commission on a $310,000 sale. What was the commission rate?", "a": ["4.0%", "4.5%", "5.0%", "2.2%"], "c": 1, "why": "Rate = commission / price = 13,950 / 310,000 = 0.045 = 4.5%. Dividing the other way (310,000 / 13,950 = 22.2) leads to the 2.2% choice.", "trap": "math-step", "difficulty": 1, "outline": "XI.A.1"}, {"id": "gen-math-006", "part": "general", "topic": "Real Estate Math", "q": "Total commission on a sale is $18,000. First, a 25% referral fee is paid off the top to an out-of-state broker. The rest is split 50/50 between the two firms. The selling agent gets 70% of her firm's share. What does she receive?", "a": ["$6,300", "$6,750", "$4,500", "$4,725"], "c": 3, "why": "$18,000 x 75% = $13,500 after referral; / 2 = $6,750; x 70% = $4,725. $6,300 forgets the referral fee ($9,000 x 70%); $6,750 forgets the agent's 70%.", "trap": "math-step", "difficulty": 3, "outline": "XI.A.1"}, {"id": "gen-math-007", "part": "general", "topic": "Real Estate Math", "q": "A seller wants to net $380,000 after paying a 5% commission and $4,000 in other closing costs. What is the minimum sale price, to the nearest dollar?", "a": ["$403,200", "$400,000", "$404,211", "$403,000"], "c": 2, "why": "Price = (380,000 + 4,000) / (1 - 0.05) = 384,000 / 0.95 = $404,210.53, about $404,211. $403,200 multiplies by 1.05, but the commission is a percent of the sale price, not of the net.", "trap": "math-step", "difficulty": 3, "outline": "XI.A.1"}, {"id": "gen-math-008", "part": "general", "topic": "Real Estate Math", "q": "A home sells for $500,000. The seller pays a 4.5% commission, a $310,000 mortgage payoff, a $2,280 transfer tax and a $1,200 attorney fee. The buyer's $25,000 deposit is held in escrow and applied to the price. What are the seller's net proceeds?", "a": ["$164,020", "$139,020", "$167,500", "$186,520"], "c": 0, "why": "500,000 - 22,500 - 310,000 - 2,280 - 1,200 = $164,020. The deposit is part of the $500,000 price going to the seller, so subtracting it ($139,020) is wrong.", "trap": "math-step", "difficulty": 3, "outline": "XI.A.1"}, {"id": "gen-math-009", "part": "general", "topic": "Real Estate Math", "q": "A home is assessed at $360,000. The tax rate is $14.50 per $1,000 of assessed value. What is the annual tax?", "a": ["$52,200", "$522", "$2,610", "$5,220"], "c": 3, "why": "360,000 / 1,000 = 360; x $14.50 = $5,220. $52,200 treats the rate as per $100; $2,610 is half a year.", "trap": "math-step", "difficulty": 1, "outline": "XI.A.3"}, {"id": "gen-math-010", "part": "general", "topic": "Real Estate Math", "q": "A town must raise $6,000,000 from property taxes. The total assessed value of all taxable property is $480,000,000. What is the tax rate per $1,000 of assessed value?", "a": ["$1.25", "$12.50", "$125.00", "$80.00"], "c": 1, "why": "6,000,000 / 480,000,000 = 0.0125 per dollar; x 1,000 = $12.50 per $1,000. $80.00 comes from dividing upside down (480 million / 6 million).", "trap": "math-step", "difficulty": 2, "outline": "XI.A.3"}, {"id": "gen-math-011", "part": "general", "topic": "Real Estate Math", "q": "Using the 30-day-month (360-day year) method: annual property taxes of $4,320 for the calendar year have not been paid. Closing is May 20, and the seller is responsible for the day of closing. What is the proration?", "a": ["$1,680 credit to the seller", "$2,640 credit to the buyer", "$1,800 credit to the buyer", "$1,680 credit to the buyer"], "c": 3, "why": "Monthly $360, daily $12. Seller owes Jan 1 to May 20 = 4 months + 20 days = $1,440 + $240 = $1,680. Taxes are unpaid, so the buyer (who will pay the bill) gets the credit. $2,640 is the buyer's own share of the year.", "trap": "math-step", "difficulty": 3, "outline": "XI.A.3"}, {"id": "gen-math-012", "part": "general", "topic": "Real Estate Math", "q": "Using the actual-days method (365-day year): the seller prepaid this calendar year's $5,475 property tax. Closing is September 30, and the seller is responsible for the day of closing. What is the proration?", "a": ["$1,380 credit to the buyer", "$1,368.75 credit to the seller", "$4,095 credit to the seller", "$1,380 credit to the seller"], "c": 3, "why": "Daily = 5,475 / 365 = $15. Buyer owns Oct 1 to Dec 31 = 31 + 30 + 31 = 92 days; x $15 = $1,380, credited to the seller who prepaid. $1,368.75 uses the 30-day method, which the stem did not ask for.", "trap": "math-step", "difficulty": 3, "outline": "XI.A.3"}, {"id": "gen-math-013", "part": "general", "topic": "Real Estate Math", "q": "Using actual days: a seller collected June rent of $2,400 on June 1. Closing is June 18 (June has 30 days), and the seller is responsible for the day of closing. What is the rent proration?", "a": ["$960 credit to the seller", "$1,440 credit to the buyer", "$960 credit to the buyer", "$1,040 credit to the buyer"], "c": 2, "why": "Daily rent = 2,400 / 30 = $80. Buyer owns June 19-30 = 12 days; x $80 = $960, credited to the buyer because the seller already collected it. $1,040 counts the closing day (13 days) for the buyer.", "trap": "math-step", "difficulty": 2, "outline": "XI.A.3"}, {"id": "gen-math-014", "part": "general", "topic": "Real Estate Math", "q": "What is the first month's interest on a $280,000 loan at 6% annual interest?", "a": ["$16,800", "$140", "$14,000", "$1,400"], "c": 3, "why": "280,000 x 0.06 = $16,800 per year; / 12 = $1,400. $16,800 forgets to convert yearly interest to monthly.", "trap": "math-step", "difficulty": 1, "outline": "XI.A.5"}, {"id": "gen-math-015", "part": "general", "topic": "Real Estate Math", "q": "A borrower's first monthly interest charge is $1,125 on a loan at 6% annual interest. What is the loan amount?", "a": ["$18,750", "$81,000", "$675,000", "$225,000"], "c": 3, "why": "1,125 x 12 = $13,500 per year; / 0.06 = $225,000. $18,750 divides the monthly figure by the annual rate without multiplying by 12 first.", "trap": "math-step", "difficulty": 2, "outline": "XI.A.5"}, {"id": "gen-math-016", "part": "general", "topic": "Real Estate Math", "q": "A buyer agrees to pay $350,000 for a home that appraises at $340,000. The loan is $272,000. What is the loan-to-value ratio?", "a": ["77.7%", "97.1%", "80%", "128.7%"], "c": 2, "why": "Lenders use the lower of price or appraisal: 272,000 / 340,000 = 80%. 77.7% divides by the $350,000 price instead.", "trap": "math-step", "difficulty": 2, "outline": "XI.B.3"}, {"id": "gen-math-017", "part": "general", "topic": "Real Estate Math", "q": "A buyer pays $300,000 with a 90% loan-to-value loan. The lender charges 2 discount points. How much are the points?", "a": ["$6,000", "$540", "$5,400", "$600"], "c": 2, "why": "Loan = 300,000 x 0.90 = $270,000; 2 points = 2% of the loan = $5,400. $6,000 figures the points on the price, but points are a percent of the loan.", "trap": "math-step", "difficulty": 2, "outline": "XI.B.4"}, {"id": "gen-math-018", "part": "general", "topic": "Real Estate Math", "q": "A buyer purchases for $400,000 with an 80% loan and pays 1 point. Other closing costs are $6,500. The buyer already paid a $20,000 earnest money deposit. How much cash must the buyer bring to closing?", "a": ["$89,700", "$69,700", "$70,500", "$66,500"], "c": 1, "why": "Down payment $80,000 + point (1% of $320,000 loan) $3,200 + $6,500 - $20,000 deposit = $69,700. $89,700 forgets the deposit already paid; $70,500 figures the point on the price.", "trap": "math-step", "difficulty": 3, "outline": "XI.A.2"}, {"id": "gen-math-019", "part": "general", "topic": "Real Estate Math", "q": "Price $300,000; loan $240,000; buyer's closing costs $9,000; seller credit to the buyer $6,000; buyer's deposit already paid $15,000. How much cash does the buyer need at closing?", "a": ["$48,000", "$60,000", "$63,000", "$54,000"], "c": 0, "why": "60,000 down + 9,000 costs - 6,000 seller credit - 15,000 deposit = $48,000. $60,000 adds the seller credit instead of subtracting it; it is a credit to the buyer.", "trap": "math-step", "difficulty": 3, "outline": "XI.A.2"}, {"id": "gen-math-020", "part": "general", "topic": "Real Estate Math", "q": "A building has gross scheduled rent of $96,000 a year, a 5% vacancy rate, operating expenses of $31,200, and mortgage payments of $24,000 a year. At a 6% cap rate, what is its value?", "a": ["$1,000,000", "$600,000", "$1,080,000", "$1,600,000"], "c": 0, "why": "Effective gross = 96,000 x 0.95 = $91,200; NOI = 91,200 - 31,200 = $60,000; / 0.06 = $1,000,000. $600,000 subtracts the mortgage, but debt service is not an operating expense.", "trap": "math-step", "difficulty": 3, "outline": "XI.B.2"}, {"id": "gen-math-021", "part": "general", "topic": "Real Estate Math", "q": "An investor pays $600,000 for a property with net operating income of $45,000. What is the cap rate?", "a": ["13.3%", "7.5%", "0.75%", "75%"], "c": 1, "why": "Cap rate = NOI / value = 45,000 / 600,000 = 0.075 = 7.5%. 13.3% divides the price by the income, upside down.", "trap": "math-step", "difficulty": 1, "outline": "XI.B.2"}, {"id": "gen-math-022", "part": "general", "topic": "Real Estate Math", "q": "A home bought for $250,000 sells three years later for $310,000. What is the percentage of appreciation?", "a": ["19.4%", "124%", "24%", "8%"], "c": 2, "why": "Gain 60,000 / original 250,000 = 24%. 19.4% divides by the selling price; percent change is always based on the starting value. 8% spreads it per year, which was not asked.", "trap": "math-step", "difficulty": 2, "outline": "XI.B.2"}, {"id": "gen-math-023", "part": "general", "topic": "Real Estate Math", "q": "An owner sold a property for $345,000, a 15% profit over what she paid. What did she pay?", "a": ["$293,250", "$300,000", "$396,750", "$51,750"], "c": 1, "why": "Sale = 115% of cost, so cost = 345,000 / 1.15 = $300,000. $293,250 subtracts 15% of the sale price, but the profit was 15% of the cost.", "trap": "math-step", "difficulty": 3, "outline": "XI.B.2"}, {"id": "gen-math-024", "part": "general", "topic": "Real Estate Math", "q": "An investor pays $450,000 for a property; the land is worth $90,000. Using straight-line depreciation over a 40-year economic life, what is the annual depreciation?", "a": ["$9,000", "$11,250", "$2,250", "$13,091"], "c": 0, "why": "Only the building depreciates: 450,000 - 90,000 = $360,000 / 40 = $9,000 per year. $11,250 depreciates the land too.", "trap": "math-step", "difficulty": 2, "outline": "XI.B.2"}, {"id": "gen-math-025", "part": "general", "topic": "Real Estate Math", "q": "A loan's monthly principal and interest is $1,800. Annual property taxes are $5,400 and annual homeowner's insurance is $1,320. What is the monthly PITI payment?", "a": ["$8,520", "$2,360", "$2,250", "$1,910"], "c": 1, "why": "Taxes 5,400 / 12 = $450; insurance 1,320 / 12 = $110; 1,800 + 450 + 110 = $2,360. $8,520 adds annual amounts to a monthly payment; $2,250 leaves out insurance.", "trap": "math-step", "difficulty": 2, "outline": "XI.A.5"}, {"id": "gen-math-026", "part": "general", "topic": "Real Estate Math", "q": "A property sells for $350,000. The transfer tax is $2.00 per $500 of the price. What is the transfer tax?", "a": ["$1,400", "$700", "$7,000", "$2,800"], "c": 0, "why": "350,000 / 500 = 700 units; x $2.00 = $1,400. $700 figures it per $1,000 instead of per $500.", "trap": "math-step", "difficulty": 2, "outline": "XI.A.4"}, {"id": "gen-math-027", "part": "general", "topic": "Real Estate Math", "q": "A home is worth $520,000. The owner owes $310,000 on a first mortgage and $45,000 on a home equity line. What is the owner's equity?", "a": ["$210,000", "$355,000", "$475,000", "$165,000"], "c": 3, "why": "Equity = value - all debts = 520,000 - 310,000 - 45,000 = $165,000. $210,000 forgets the home equity line, which is also a lien.", "trap": "math-step", "difficulty": 1, "outline": "XI.B.1"}, {"id": "ma-req-001", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A salesperson writes a print ad for a three-bedroom ranch her firm has listed. Under 254 CMR 3.00, what must the ad contain?", "a": ["Her own license number and personal cell phone, with no other contact", "The seller's name and the reason for selling", "The name of her broker, identified as a real estate broker", "A statement that the Board of Registration has reviewed the ad"], "c": 2, "why": "254 CMR 3.00 requires every licensee ad to identify the broker by name and show that it is placed by a broker. A salesperson's license number and phone alone do not meet that rule; the broker's identity must appear.", "trap": "familiar-term", "difficulty": 1, "outline": "III.A.2"}, {"id": "ma-req-002", "part": "ma", "topic": "Requirements Governing Licensees", "q": "Which of these ads would violate the Massachusetts rule against \"blind\" advertising?", "a": ["\"Sunny 2BR condo near the T. Text 617-555-0142.\" (no firm or broker named)", "\"Sunny 2BR condo near the T. Bayview Realty, Broker, 617-555-0142.\"", "\"Sunny 2BR condo near the T. Ask for Dana at Bayview Realty, a licensed broker.\"", "\"Sunny 2BR condo near the T. Bayview Realty (broker), info@bayviewrealty.example\""], "c": 0, "why": "A blind ad gives only a phone number, P.O. box, email or address and hides that a broker placed it, which 254 CMR 3.00 forbids. The other ads all name the brokerage as a broker, so adding a salesperson's name or using email instead of a phone is fine.", "trap": "too-simple", "difficulty": 2, "outline": "III.A.2"}, {"id": "ma-req-003", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A seller tells the listing agent the roof is \"basically new.\" The agent has already read the seller's own inspection report, which says the roof is about 22 years old and near the end of its life. The agent advertises \"NEW ROOF.\" Which is correct?", "a": ["She is protected, because she only repeated what the seller told her about the roof", "She may be disciplined, because she knew the claim was false", "Only the seller can be held liable, since the roof claim originally came from the seller", "It is lawful puffing, because whether a roof is \"new\" is a matter of opinion"], "c": 1, "why": "254 CMR 3.00 bans false or misleading ads, and c.112 §87AAA lets the Board act on knowing misrepresentation. Relying on the seller is no defense when the agent had actual knowledge the statement was false, and a roof's age is a fact, not puffing.", "trap": "wrong-context", "difficulty": 3, "outline": "III.A.1"}, {"id": "ma-req-004", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A rental ad reads: \"Charming one-bedroom, ideal for a young professional single.\" What is the problem with this ad?", "a": ["It fails to state the amount of the security deposit, which every MA rental ad must include", "It uses puffing, which Massachusetts allows in sales ads but not in rental ads", "There is no problem, because the ad does not mention any federally protected class", "It describes the people wanted rather than the property, implying age and marital-status preferences"], "c": 3, "why": "Ads must describe the property, not the preferred tenant. Under c.151B and 254 CMR 3.00, age and marital status are protected in Massachusetts even though federal law does not list them, so \"no federal class named\" is not a defense.", "trap": "familiar-term", "difficulty": 2, "outline": "III.A.4"}, {"id": "ma-req-005", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A Massachusetts salesperson may be affiliated with how many brokers at the same time?", "a": ["Two, if both brokers agree in writing", "Up to three, if the Board is notified", "Any number, as long as each listing names the correct broker", "One"], "c": 3, "why": "A salesperson works under one broker at a time and is supervised and paid only through that broker. Written consent from two brokers does not create an exception.", "trap": "none", "difficulty": 1, "outline": "III.B"}, {"id": "ma-req-006", "part": "ma", "topic": "Requirements Governing Licensees", "q": "From whom may a salesperson lawfully receive a commission on a sale she helped close?", "a": ["Only the broker she is affiliated with", "Directly from the seller at closing", "From the closing attorney's settlement check", "From the cooperating broker on the other side"], "c": 0, "why": "Under MA license law a salesperson is paid only by her own broker. Taking money straight from the seller, the closing attorney or another firm bypasses the broker and is a violation.", "trap": "familiar-term", "difficulty": 1, "outline": "III.C.1"}, {"id": "ma-req-007", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A seller says to a broker: \"I need $610,000 in my pocket. List it for whatever you like and keep anything above that.\" What should the broker do?", "a": ["Decline, because a net listing is a ground for discipline", "Accept it, as long as the net arrangement is put in a signed written agreement", "Accept it, as long as the list price is supported by a comparative market analysis", "Accept it, but only after disclosing the net arrangement to every buyer"], "c": 0, "why": "c.112 §87AAA lists accepting a net listing as a ground for discipline. Putting it in writing or supporting it with a CMA does not make it legal; the broker should offer a normal commission agreement instead.", "trap": "too-simple", "difficulty": 2, "outline": "III.C.2"}, {"id": "ma-req-008", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A broker pays $1,500 to an unlicensed acquaintance who located a buyer and negotiated the price with the seller on the broker's behalf. Which statement is correct?", "a": ["The payment is lawful, because only the broker signed the listing agreement", "The broker violated the license law by paying an unlicensed person", "The payment is lawful if the acquaintance reports it as income on his taxes", "Only the acquaintance can be penalized; the broker who paid did nothing wrong"], "c": 1, "why": "Finding prospects and negotiating for another for pay are broker acts, so the acquaintance needed a license. c.112 §87AAA makes paying an unlicensed person who needed a license a ground for discipline against the broker who paid.", "trap": "opposite", "difficulty": 3, "outline": "III.C.1"}, {"id": "ma-req-009", "part": "ma", "topic": "Requirements Governing Licensees", "q": "While managing repairs for a seller client, a broker sends the work to a contractor who quietly pays the broker 10% of each bill. The seller is never told. This is BEST described as:", "a": ["A lawful referral fee because the contractor is licensed", "Commingling of escrow funds", "An undisclosed dual agency", "An undisclosed secret profit, which is a ground for discipline"], "c": 3, "why": "Taking an undisclosed rebate or profit on a principal's expenses is a separate ground for discipline under c.112 §87AAA. It is not commingling, because no client deposit was mixed with the broker's own money.", "trap": "wrong-context", "difficulty": 2, "outline": "III.C"}, {"id": "ma-req-010", "part": "ma", "topic": "Requirements Governing Licensees", "q": "When must a licensee give the Massachusetts Mandatory Licensee-Consumer Relationship Disclosure to a consumer?", "a": ["When the purchase and sale agreement is signed", "At the first phone call, before any other conversation", "At closing, along with the settlement statement", "At the first personal meeting to discuss a specific property"], "c": 3, "why": "254 CMR 3.00 sets the trigger as the first personal meeting where a specific property is discussed. The P&S and closing are far too late, and a general phone call is not the trigger.", "trap": "familiar-term", "difficulty": 1, "outline": "III.D.1"}, {"id": "ma-req-011", "part": "ma", "topic": "Requirements Governing Licensees", "q": "At a Sunday open house, dozens of visitors walk through. How can the listing agent meet the relationship disclosure requirement?", "a": ["Post a conspicuous sign or provide a handout stating whom the agent represents", "Have every visitor sign the disclosure form before entering", "Nothing is required, because an open house is not a personal meeting", "Mail the disclosure form to each visitor within 10 days"], "c": 0, "why": "Under 254 CMR 3.00 an open house can be covered by a conspicuously posted or handed-out notice of the agent's relationship. Disclosure is still required, so \"nothing is required\" is wrong, and individual signatures are not needed.", "trap": "too-simple", "difficulty": 2, "outline": "III.D.1"}, {"id": "ma-req-012", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A buyer meeting with an agent about a specific house refuses to sign the relationship disclosure form. What should the agent do?", "a": ["Stop working with the buyer, because a signed form is mandatory before any help", "Send the unsigned form to the Board of Registration within 7 days of the meeting", "Note on the form the date it was given and that the buyer declined to sign", "Sign the buyer's name on the form after getting permission over the phone"], "c": 2, "why": "Under 254 CMR 3.00(13)(a) the licensee notes the date the disclosure was provided and that the consumer declined to sign, and keeps it for three years. The consumer does not have to sign or give a reason, so ending the relationship is not required, and signing for the buyer would be falsifying a document.", "trap": "opposite", "difficulty": 2, "outline": "III.D.1"}, {"id": "ma-req-013", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A listing agent's sister wants to make an offer on the agent's listing. What must the agent do?", "a": ["Nothing, as long as the sister pays full asking price", "Disclose it verbally to the seller only", "Refer the sister to another firm; relatives may never buy a licensee's listing", "Disclose the family relationship in writing to all parties and get written acknowledgment"], "c": 3, "why": "254 CMR 3.00 requires written disclosure, with written acknowledgment, when a licensee or a relative has a financial interest in a transaction. Relatives are not banned from buying, but a verbal notice to one party is not enough.", "trap": "too-simple", "difficulty": 2, "outline": "III.D.2"}, {"id": "ma-req-014", "part": "ma", "topic": "Requirements Governing Licensees", "q": "Broker Lena lists a building lot for Mr. Ortiz. A month later she decides she wants to buy the lot for her own investment. What must she do FIRST?", "a": ["Have a salesperson in her own office write the offer so that the conflict of interest is avoided", "Disclose in writing that she now wants to buy and is acting as a buyer, and get his acknowledgment", "Lower the list price first, so that her purchase is fair to Mr. Ortiz as the seller", "Notify the Board of Registration, which must approve any licensee's purchase of a listing"], "c": 1, "why": "Under 254 CMR 3.00 a broker who wants to buy a property she has listed must first disclose in writing that she is now a buyer and not the owner's agent. Using a salesperson from her own firm hides the conflict; it does not cure it.", "trap": "wrong-context", "difficulty": 3, "outline": "III.D.2"}, {"id": "ma-req-015", "part": "ma", "topic": "Requirements Governing Licensees", "q": "In September 2025 a landlord hires a broker to find a tenant for an apartment. A renter sees the listing and signs a lease. Who pays the broker's fee?", "a": ["The tenant, because the tenant benefits from finding the apartment", "The landlord and tenant split it equally", "The tenant, if the fee is stated in the listing", "The landlord, because the landlord hired the broker"], "c": 3, "why": "Under the Massachusetts law effective August 1, 2025, the party who engaged the broker pays the rental broker fee. Putting the fee in the listing does not let a landlord pass it to a tenant who never hired the broker.", "trap": "opposite", "difficulty": 2, "outline": "III.D.3"}, {"id": "ma-req-016", "part": "ma", "topic": "Requirements Governing Licensees", "q": "Under the current Massachusetts rental broker-fee rule, in which situation may a tenant lawfully be charged the broker's fee?", "a": ["The landlord listed the unit with the broker and the tenant called about the ad", "The tenant signed a written agreement hiring the broker to find her an apartment", "The property manager hired the broker and added the fee to the first month's rent", "The landlord's broker told the tenant that tenant-paid fees are customary in Boston"], "c": 1, "why": "Since August 1, 2025, a tenant pays only when the tenant engaged the broker. A property manager adding a landlord-side fee to the first month's rent is the exact pass-through the law bans, and \"custom\" is no exception.", "trap": "wrong-context", "difficulty": 3, "outline": "III.D.3"}, {"id": "ma-req-017", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A broker the tenant has hired will charge that tenant a fee. At the first personal meeting with the prospective tenant, what written disclosure does 254 CMR 7.00 require?", "a": ["Only the broker's license number and the name of the broker's supervising firm", "Whether a fee applies, its amount, when it is due, and whether it is owed if no tenancy results", "The landlord's income, mortgage balance and the number of units the landlord owns", "A copy of the State Sanitary Code and the local Board of Health's phone number"], "c": 1, "why": "254 CMR 7.00 requires a written rental fee notice covering whether a fee applies, how much, when it is due and whether it is owed if no tenancy is created. A license number alone is far less than the rule requires.", "trap": "too-simple", "difficulty": 2, "outline": "III.D.3"}, {"id": "ma-req-018", "part": "ma", "topic": "Requirements Governing Licensees", "q": "What is required before a Massachusetts licensee may act as a dual agent?", "a": ["Verbal consent of the seller only, since the seller is the listing client", "Informed written consent of both the buyer and the seller", "Advance approval of the arrangement from the Board of Registration", "Nothing, as long as the broker owns the firm and supervises both agents"], "c": 1, "why": "Dual agency is legal in Massachusetts only with the informed written consent of both clients (254 CMR 3.00). Seller-only or verbal consent is not enough, and acting without consent is undisclosed dual agency, a ground for discipline under c.112 §87AAA.", "trap": "familiar-term", "difficulty": 1, "outline": "III.E.5"}, {"id": "ma-req-019", "part": "ma", "topic": "Requirements Governing Licensees", "q": "Seaside Realty lists a home. A buyer client of the same firm wants to buy it. With the parties' consent, the broker appoints Ana to represent only the seller and Ben to represent only the buyer. This is:", "a": ["Designated agency", "Subagency", "Facilitation", "Undisclosed dual agency"], "c": 0, "why": "Designated agency is when one firm appoints different licensees to represent the seller and the buyer, each fully, after consent and notice. Subagency involves a cooperating broker from another firm working for the seller.", "trap": "familiar-term", "difficulty": 2, "outline": "III.E.2"}, {"id": "ma-req-020", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A licensee acting as a facilitator in a Massachusetts transaction:", "a": ["Owes full fiduciary duties of loyalty and confidentiality to both buyer and seller", "Represents the seller only, as a subagent working through the listing broker", "May keep known material defects secret, because no agency relationship exists", "Assists the parties but represents neither one as an agent"], "c": 3, "why": "A facilitator does not represent either party and owes no fiduciary loyalty, but must still be honest and disclose known material defects. Full fiduciary duties to both sides describes no role at all: even a dual agent, who represents both parties with informed written consent, has limited duties where their interests conflict.", "trap": "opposite", "difficulty": 1, "outline": "III.E.6"}, {"id": "ma-req-021", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A cooperating broker from a different firm shows a listing and, by agreement, works for the seller through the listing broker. This relationship is called:", "a": ["Designated agency", "Buyer agency", "Facilitation", "Subagency"], "c": 3, "why": "A subagent is a broker from another firm who represents the seller through the listing broker. Designated agency happens inside one firm, and buyer agency represents the buyer.", "trap": "familiar-term", "difficulty": 1, "outline": "III.E.7"}, {"id": "ma-req-022", "part": "ma", "topic": "Requirements Governing Licensees", "q": "Salesperson Raj has a written buyer agency agreement with the Lins. When the Lins look at a home listed by Raj's own firm, Raj privately tells the seller he will \"get you top dollar from these folks.\" No one signs a dual agency consent. Which is correct?", "a": ["Raj has engaged in undisclosed dual agency, a ground for discipline", "Raj acted properly because the listing belongs to his firm", "Raj is a facilitator, so no consent is needed", "Only the listing agent can be disciplined"], "c": 0, "why": "Acting for both sides without both parties' knowledge and written consent is undisclosed dual agency under c.112 §87AAA. Having the listing in the same firm is what makes consent necessary; it does not excuse the missing consent.", "trap": "wrong-context", "difficulty": 3, "outline": "III.E.5"}, {"id": "ma-req-023", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A seller signed a P&S last week. A second, higher written offer now arrives at the listing office. The seller has not given any instruction about later offers. What should the listing agent do?", "a": ["Hold it, because the property is already under agreement", "Present the new offer to the seller promptly", "Give it to the first buyer's agent so the first buyer can match it", "Return it to the offeror without telling the seller"], "c": 1, "why": "254 CMR 3.00 requires offers to be conveyed to the owner promptly, and an existing P&S does not by itself end that duty unless the seller has given other instructions. Steering the offer to the first buyer so they can match it is not the agent's call; the seller decides what happens next.", "trap": "too-simple", "difficulty": 2, "outline": "III.F"}, {"id": "ma-req-024", "part": "ma", "topic": "Requirements Governing Licensees", "q": "After a purchase and sale agreement is signed, the broker must make sure a copy goes to:", "a": ["Only the broker's own client", "Only the seller", "Both the buyer and the seller", "The Board of Registration within 10 days"], "c": 2, "why": "c.112 §87AAA makes failing to give both the buyer and the seller a copy of the P&S a ground for discipline. Giving it only to your own client is not enough, and the Board does not collect P&S copies.", "trap": "too-simple", "difficulty": 1, "outline": "III.F"}, {"id": "ma-req-025", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A buyer asks an agent whether she really needs a lawyer for her purchase. Under 254 CMR 3.00, the agent:", "a": ["Should tell her a lawyer is unnecessary for a standard sale", "Must not advise her against using an attorney", "May advise against a lawyer only if the agent is a buyer's agent", "Must act as her lawyer if she does not hire one"], "c": 1, "why": "254 CMR 3.00 forbids licensees from advising anyone against using an attorney. An agent also may not give legal advice, so offering to act as her lawyer is wrong too.", "trap": "opposite", "difficulty": 1, "outline": "III.F"}, {"id": "ma-req-026", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A salesperson receives a $15,000 deposit check from a buyer at an open house. What must the salesperson do?", "a": ["Deposit it in her personal account until the P&S is signed", "Hold it in her desk until the seller accepts", "Turn it over to her broker immediately", "Cash it and give the seller a receipt"], "c": 2, "why": "Salespersons may not hold client funds. They pass deposits to the broker at once, and the broker places them in escrow under 254 CMR 3.00. Any personal account or desk drawer is a violation.", "trap": "wrong-context", "difficulty": 1, "outline": "III.G"}, {"id": "ma-req-027", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A buyer backs out after the inspection contingency has expired. The buyer demands the $20,000 deposit back; the seller demands it be released to her. The broker holds it in escrow. Absent a written agreement of both parties or a court order, the broker should:", "a": ["Release them to the seller as liquidated damages", "Return them to the buyer, who supplied the money", "Keep the funds in escrow", "Keep them as the commission earned"], "c": 2, "why": "Under 254 CMR 3.00 escrow money is not the broker's, and the broker may not pick a winner in a dispute. It stays in escrow until both parties agree in writing or a court decides. Paying either side is choosing for them.", "trap": "opposite", "difficulty": 3, "outline": "III.G"}, {"id": "ma-req-028", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A broker short on payroll moves a client's escrowed deposit into the firm's operating account for two days, then puts it back. This is:", "a": ["Permitted if the funds are returned within a week", "Commingling, a ground for suspension or revocation", "Permitted if the escrow account earns interest", "Only a problem if the client complains"], "c": 1, "why": "Mixing a principal's money with the broker's own funds is commingling under c.112 §87AAA and 254 CMR 3.00, no matter how briefly or whether it is repaid. No complaint is needed for the Board to act.", "trap": "familiar-term", "difficulty": 2, "outline": "III.G"}, {"id": "ma-req-029", "part": "ma", "topic": "Requirements Governing Licensees", "q": "Which record must a Massachusetts broker keep for the escrow account?", "a": ["Only the bank's year-end interest tax form for the escrow account", "A ledger of each deposit's date, source, amount and every withdrawal", "A list of the salespersons who brought in each deposit, with their home addresses", "No separate records, as long as the bank keeps its own monthly statements"], "c": 1, "why": "254 CMR 3.00 requires brokers to keep escrow records showing what came in, from whom, and what went out, and the Board may inspect them. Bank statements alone do not replace the broker's own ledger.", "trap": "none", "difficulty": 2, "outline": "III.H"}, {"id": "ma-req-030", "part": "ma", "topic": "Requirements Governing Licensees", "q": "A buyer who is a customer (not a client) of the listing agent asks, \"Which home inspector should I use?\" What may the listing agent do under c.112 §87YY½?", "a": ["On request, give the full list of licensed inspectors, but not name one", "Recommend the inspector the listing office uses on most of its sales", "Recommend any inspector she likes, as long as that inspector holds a MA license", "Refuse to discuss home inspections at all, and tell the buyer to ask a lawyer"], "c": 0, "why": "A listing agent may not directly recommend a specific home inspector, but may provide the full list of licensed inspectors on request. Only a broker with a written buyer agency relationship may recommend a specific inspector, so \"any licensed inspector\" is wrong.", "trap": "wrong-context", "difficulty": 3, "outline": "III.I"}, {"id": "ma-req-031", "part": "ma", "topic": "Requirements Governing Licensees", "q": "Under Massachusetts law, when must a licensee give a buyer the state's consumer brochure about home inspections?", "a": ["At the signing of the first written contract to purchase", "At the closing, together with the deed and settlement statement", "When the home inspector arrives to begin the inspection", "Only if the buyer asks for it in writing before making an offer"], "c": 0, "why": "c.112 §87YY½ requires the home inspection brochure at the signing of the first written purchase contract. Giving it at the inspection or closing is too late to help the buyer choose.", "trap": "familiar-term", "difficulty": 1, "outline": "III.I"}, {"id": "ma-fh-001", "part": "ma", "topic": "MA Fair Housing", "q": "Which of these is protected under Massachusetts fair housing law (c.151B) but NOT named in the federal Fair Housing Act?", "a": ["National origin", "Familial status", "Handicap", "Gender identity"], "c": 3, "why": "Gender identity was added to c.151B in Massachusetts and is not named in the federal Act. National origin, familial status and handicap are all federal classes, so they are not MA-only additions.", "trap": "familiar-term", "difficulty": 1, "outline": "VII.A"}, {"id": "ma-fh-002", "part": "ma", "topic": "MA Fair Housing", "q": "All of the following are protected classes under Massachusetts fair housing law EXCEPT:", "a": ["Political party membership", "Genetic information", "Military or veteran status", "Receipt of public or rental assistance"], "c": 0, "why": "c.151B protects genetic information, veteran/military status and public assistance recipients, among others. Political affiliation is not a protected housing class in MA.", "trap": "none", "difficulty": 2, "outline": "VII.A"}, {"id": "ma-fh-003", "part": "ma", "topic": "MA Fair Housing", "q": "An owner lives in one unit of her two-family house. Her ad for the other unit says \"No Section 8.\" Is she covered by the owner-occupied two-family exemption?", "a": ["Yes; the owner-occupied two-family exemption applies to every protected class", "No; the public-assistance class has no owner-occupancy exemption", "Yes, because she is renting the unit herself without using a broker", "No, but only because the discriminatory statement was published in an ad"], "c": 1, "why": "Under c.151B the owner-occupied two-family exemption does not cover discrimination against public assistance or housing subsidy recipients. Refusing Section 8 is illegal in that situation even with no broker involved.", "trap": "wrong-context", "difficulty": 3, "outline": "VII.A"}, {"id": "ma-fh-004", "part": "ma", "topic": "MA Fair Housing", "q": "An owner lives in one unit of a three-family house and refuses to rent another unit to a veteran because of his military service. Under Massachusetts law:", "a": ["She has violated c.151B; the MA owner-occupancy exemption is limited to two-family houses", "She is exempt, because owner-occupied buildings of up to four units are exempt", "She is exempt, because veteran status is only a federal class", "She is exempt as long as she did not advertise"], "c": 0, "why": "The federal \"Mrs. Murphy\" exemption reaches owner-occupied buildings of up to four units, but MA limits its exemption to owner-occupied two-family houses. Veteran/military status is a MA class, not a federal one.", "trap": "familiar-term", "difficulty": 3, "outline": "VII.A"}, {"id": "ma-fh-005", "part": "ma", "topic": "MA Fair Housing", "q": "Which agency receives and investigates housing discrimination complaints under Massachusetts law?", "a": ["The Board of Registration of Real Estate Brokers and Salespersons", "The local Board of Health", "The Massachusetts Department of Environmental Protection", "The Massachusetts Commission Against Discrimination (MCAD)"], "c": 3, "why": "MCAD enforces c.151B. The Board of Registration licenses and disciplines agents and must suspend a license after a final MCAD finding, but it is not the agency where discrimination complaints are filed.", "trap": "familiar-term", "difficulty": 1, "outline": "VII.B"}, {"id": "ma-fh-006", "part": "ma", "topic": "MA Fair Housing", "q": "How long does a person have to file a housing discrimination complaint with MCAD?", "a": ["6 months after the alleged discrimination", "300 days after the alleged discrimination", "1 year after the alleged discrimination", "90 days after the alleged discrimination"], "c": 1, "why": "c.151B §5 sets 300 days to file with MCAD. Six months is an old deadline found in outdated books, and one year is the federal HUD deadline.", "trap": "opposite", "difficulty": 1, "outline": "VII.B"}, {"id": "ma-fh-007", "part": "ma", "topic": "MA Fair Housing", "q": "MCAD finds that a respondent with no prior discrimination findings violated c.151B. What is the maximum civil penalty?", "a": ["$25,000", "$50,000", "$2,500", "$10,000"], "c": 3, "why": "Under c.151B §5 the civil penalty is up to $10,000 with no prior violation, up to $25,000 with one other violation in 5 years, and up to $50,000 with two or more in 7 years. $25,000 is the second-offense tier.", "trap": "wrong-context", "difficulty": 2, "outline": "VII.D"}, {"id": "ma-fh-008", "part": "ma", "topic": "MA Fair Housing", "q": "A broker receives a final MCAD finding of housing discrimination. A second discriminatory act by the same broker occurred 18 months after the first one, and MCAD's finding on it also becomes final and is reported to the Board. What must the Board of Registration do?", "a": ["Suspend the license for 60 days", "Revoke the license permanently", "Issue a warning, since suspensions apply only to the first finding", "Suspend the license for 90 days"], "c": 3, "why": "c.112 §87AAA requires a 60-day suspension after a final MCAD finding and a 90-day suspension when another violation occurred within 2 years of a prior violation. The second act came 18 months after the first, inside the 2-year window, so 60 days is the first-finding answer, not this one.", "trap": "math-step", "difficulty": 3, "outline": "VII.D"}, {"id": "ma-fh-009", "part": "ma", "topic": "MA Fair Housing", "q": "A tenant who uses a wheelchair in a 14-unit apartment building asks for a ramp at the building entrance. Under Massachusetts law, who generally pays for this reasonable modification?", "a": ["The tenant, because federal law makes the tenant pay for modifications", "The tenant and the landlord, who split the cost equally", "The local housing authority, which funds all accessibility ramps", "The landlord, because the building has 10 or more units"], "c": 3, "why": "c.151B §4(7A) requires the owner to pay for reasonable modifications in publicly assisted housing and buildings of 10 or more units. Federal law usually puts the cost on the tenant, which is the tempting answer here.", "trap": "opposite", "difficulty": 3, "outline": "VII.C"}, {"id": "ma-fh-010", "part": "ma", "topic": "MA Fair Housing", "q": "A landlord with a \"no pets\" policy receives a request from an applicant with a disability to keep an emotional support animal, backed by a letter from her clinician. The landlord should generally:", "a": ["Deny it, because only trained service dogs are allowed", "Allow it only if the applicant pays a pet fee", "Grant it as a reasonable accommodation", "Deny it, because the policy applies to all tenants equally"], "c": 2, "why": "Fair housing law treats an assistance animal as a reasonable accommodation for a person with a disability, even under a no-pets rule. It does not have to be a trained service dog, and charging a pet fee for it is not allowed.", "trap": "too-simple", "difficulty": 3, "outline": "VII.C"}, {"id": "ma-fh-011", "part": "ma", "topic": "MA Fair Housing", "q": "The owner of an 1890s rental refuses to rent to a couple with a 2-year-old because he does not want to delead. This is:", "a": ["Legal, because the cost of deleading would be too expensive for the owner", "Legal, as long as he tells the couple in writing about the lead paint", "Illegal; he must delead rather than refuse the family", "Legal, as long as the owner lives in one of the units in the building"], "c": 2, "why": "Under c.151B and the MA lead law, refusing to rent because a child under 6 would trigger deleading is discrimination. Disclosing the lead does not fix it; the owner's duty is to delead.", "trap": "wrong-context", "difficulty": 2, "outline": "VII.A"}, {"id": "ma-fh-012", "part": "ma", "topic": "MA Fair Housing", "q": "A buyer asks the listing agent whether the previous owner died of AIDS. What is the BEST response?", "a": ["Decline to discuss it; HIV status is not a material fact", "Answer truthfully, because every known fact about the home must be disclosed", "Find out from the late owner's family, then report back to the buyer", "Say no, regardless of the truth, to protect the seller's privacy"], "c": 0, "why": "c.93 §114 says an occupant's HIV/AIDS status is not a material fact, and HIV is a disability under c.151B. The agent should not discuss it, and must not lie either.", "trap": "familiar-term", "difficulty": 2, "outline": "VII.A"}, {"id": "ma-fh-013", "part": "ma", "topic": "MA Fair Housing", "q": "A landlord turns down a 72-year-old applicant with good credit because \"older tenants have too many emergencies.\" Under Massachusetts law this is:", "a": ["Discrimination based on age, which c.151B prohibits", "Legal, because age is not a federally protected class", "Legal, because the landlord is protecting other tenants", "Legal unless the building is senior housing"], "c": 0, "why": "Massachusetts c.151B protects age even though federal fair housing law does not. That federal law is silent does not excuse a MA landlord.", "trap": "opposite", "difficulty": 2, "outline": "VII.A"}, {"id": "ma-fh-014", "part": "ma", "topic": "MA Fair Housing", "q": "While signing a listing, the seller tells the broker, \"Don't bring me any buyers who are Muslim.\" What should the broker do?", "a": ["Refuse to take the listing under that condition", "Take the listing but show it only to buyers the seller would like", "Take the listing and ignore the remark", "Take the listing, but have the seller put the instruction in writing"], "c": 0, "why": "A broker may not accept a listing that requires discrimination based on religion. Taking it while quietly screening buyers is steering, and putting the instruction in writing only documents the violation.", "trap": "wrong-context", "difficulty": 3, "outline": "VII.A"}, {"id": "ma-fh-015", "part": "ma", "topic": "MA Fair Housing", "q": "A landlord refuses to rent to an unmarried couple, saying he rents only to married couples. Under Massachusetts law this is:", "a": ["Legal, because marital status is not a federal class", "Legal if the landlord's religion forbids it", "Illegal discrimination based on marital status", "Legal in a building with more than two units"], "c": 2, "why": "c.151B protects marital status in Massachusetts housing. Federal law does not, which is why \"not a federal class\" is the tempting wrong answer.", "trap": "familiar-term", "difficulty": 1, "outline": "VII.A"}, {"id": "ma-cp-001", "part": "ma", "topic": "Consumer Protection", "q": "A homicide occurred in a house three years ago. The seller's agent does not mention it, and no buyer asks. Under c.93 §114:", "a": ["The fact is not material, so the agent need not volunteer it", "The agent must disclose it in writing before any offer is signed", "The agent must disclose it, but only to buyers who have young children", "The seller must disclose it for 5 years after the event occurred"], "c": 0, "why": "c.93 §114 says that a property being the site of a felony, suicide or homicide is not a material fact that must be disclosed. There is no special disclosure period or buyer-type rule.", "trap": "opposite", "difficulty": 2, "outline": "V.A"}, {"id": "ma-cp-002", "part": "ma", "topic": "Consumer Protection", "q": "A buyer looking at a listing asks the agent directly, \"Did anyone die violently in this house?\" A suicide did occur there. The agent may NOT:", "a": ["Decline to answer and suggest the buyer research it", "Say she is not required to discuss that topic", "Tell the buyer that nothing like that happened", "Answer truthfully with the seller's permission"], "c": 2, "why": "c.93 §114 removes the duty to volunteer stigma facts, but it says it does not authorize a misrepresentation. Declining to answer is allowed; stating a falsehood is not.", "trap": "too-simple", "difficulty": 3, "outline": "V.B"}, {"id": "ma-cp-003", "part": "ma", "topic": "Consumer Protection", "q": "Under c.93 §114, which of these is NOT a material fact the seller's agent must disclose?", "a": ["The basement takes on water in heavy rain", "The septic system failed its Title 5 inspection", "The house has a reputation for being haunted", "There is an active termite infestation"], "c": 2, "why": "c.93 §114 lists an alleged paranormal or supernatural event as a psychological impact that is not material. Water problems, a failed septic system and termites are physical defects that a licensee who knows of them must disclose.", "trap": "wrong-context", "difficulty": 2, "outline": "V.A"}, {"id": "ma-cp-004", "part": "ma", "topic": "Consumer Protection", "q": "A seller tells his listing agent that mold was found behind a bathroom wall last year and only painted over. He says, \"Don't mention it.\" What should the agent do?", "a": ["Stay silent, since the seller is the client and confidentiality comes first", "Stay silent unless a buyer's inspector finds it", "Disclose the known mold problem to buyers; she cannot hide a known material defect", "Stay silent, because Massachusetts has no mold disclosure form"], "c": 2, "why": "A licensee must disclose known material defects to buyers; failing to do so is deceptive under c.93A and the Board's rules. Confidentiality to a client does not cover hiding a defect, and the lack of a specific mold form changes nothing.", "trap": "opposite", "difficulty": 3, "outline": "V.A"}, {"id": "ma-cp-005", "part": "ma", "topic": "Consumer Protection", "q": "An agent says a home has \"the best sunset view in town.\" This statement is MOST likely:", "a": ["Fraud, because the statement cannot be proven true", "A violation of the Board's advertising rules", "Puffing, an opinion that is generally not actionable", "A material misrepresentation of fact about the property"], "c": 2, "why": "Puffing is a vague opinion or exaggeration that a reasonable buyer would not treat as a fact. A misrepresentation is a false statement of fact, like a false roof age or square footage.", "trap": "familiar-term", "difficulty": 1, "outline": "V.B"}, {"id": "ma-cp-006", "part": "ma", "topic": "Consumer Protection", "q": "A seller's radon test showed 9 pCi/L and no mitigation was done. The listing agent knows the result. What applies?", "a": ["Nothing, because radon is invisible and any buyer can run a test of their own", "Disclose it, because it is a known level above the EPA action level of 4 pCi/L", "Disclosure is required only if the buyer has children who will live there", "Disclosure is required only for homes that were built before 1978"], "c": 1, "why": "A known radon level above the EPA's 4 pCi/L action level is a material fact the agent must disclose. That a buyer could test does not excuse hiding a known result, and 1978 is the lead paint cutoff, not a radon rule.", "trap": "too-simple", "difficulty": 2, "outline": "V.A"}, {"id": "ma-cp-007", "part": "ma", "topic": "Consumer Protection", "q": "Under 201 CMR 17.00, a real estate firm that keeps personal information about Massachusetts residents must have a:", "a": ["Surety bond of $50,000", "Do-not-call registration with the Board", "Board-approved privacy officer license", "Written Information Security Program (WISP)"], "c": 3, "why": "201 CMR 17.00 requires a comprehensive Written Information Security Program to protect personal information of MA residents. A surety bond protects against mishandled money, not data.", "trap": "familiar-term", "difficulty": 1, "outline": "V.C"}, {"id": "ma-cp-008", "part": "ma", "topic": "Consumer Protection", "q": "Which of the following counts as \"personal information\" under Massachusetts data security rules (c.93H / 201 CMR 17.00)?", "a": ["A client's name and the address of the home she is selling", "A buyer's name and the price he offered", "A seller's name and his email address", "A client's name together with her Social Security number"], "c": 3, "why": "Personal information is a resident's name combined with a Social Security number, driver's license or state ID number, or a financial account or card number. A name with a property address, price or email does not meet the definition.", "trap": "wrong-context", "difficulty": 2, "outline": "V.C"}, {"id": "ma-cp-009", "part": "ma", "topic": "Consumer Protection", "q": "A laptop holding unencrypted mortgage pre-approval letters with clients' names and Social Security numbers is stolen from an agent's car. Under c.93H, the firm must:", "a": ["Notify only the agent's managing broker, who decides what to do next", "Do nothing unless one of the clients later reports identity theft", "Notify the Attorney General, OCABR and the affected residents", "Notify only the local police department where the car was parked"], "c": 2, "why": "c.93H requires notice of a breach of personal information to the Attorney General, the Director of OCABR and the affected residents. Waiting for actual identity theft is too late, and a police report alone is not enough.", "trap": "too-simple", "difficulty": 3, "outline": "V.C"}, {"id": "ma-cp-010", "part": "ma", "topic": "Consumer Protection", "q": "Before suing a broker under c.93A, §9, a consumer must generally send a written demand letter how many days before filing suit?", "a": ["At least 10 days", "At least 60 days", "No demand letter is required", "At least 30 days"], "c": 3, "why": "c.93A §9 requires a written demand for relief at least 30 days before suit. The respondent then has 30 days to make a reasonable written settlement offer.", "trap": "opposite", "difficulty": 2, "outline": "V.D"}, {"id": "ma-cp-011", "part": "ma", "topic": "Consumer Protection", "q": "A court finds a broker's c.93A violation was willful or knowing. Actual damages are $8,000. What is the range the court may award, before attorney's fees?", "a": ["$8,000 only", "$8,000 to $16,000", "$16,000 to $24,000", "$24,000 to $40,000"], "c": 2, "why": "Under c.93A §9, for a willful or knowing violation the court may award not less than two and up to three times actual damages: 2 x $8,000 = $16,000 up to 3 x $8,000 = $24,000. Reasonable attorney's fees and costs are added on top.", "trap": "math-step", "difficulty": 2, "outline": "V.D"}, {"id": "ma-cp-012", "part": "ma", "topic": "Consumer Protection", "q": "A homeowner sells her own house without an agent and does not mention a leaky foundation she knew about. In an unrelated sale, a broker hides the same kind of defect from his buyer. Which statement is generally correct under c.93A?", "a": ["Only the broker, who acts in trade or commerce, is generally subject to c.93A", "Both are fully subject to c.93A, including multiple damages and attorney's fees", "Neither is subject to c.93A, because real estate sales are exempt from that law", "Only the homeowner is subject to c.93A, because she owned the property"], "c": 0, "why": "c.93A reaches people acting in trade or commerce, which includes real estate brokers. A private homeowner making a one-time sale of her home is generally not in trade or commerce, though she can still face common-law fraud claims.", "trap": "wrong-context", "difficulty": 3, "outline": "V.D"}, {"id": "ma-lt-001", "part": "ma", "topic": "Landlord-Tenant", "q": "At the start of a tenancy, which of these may a Massachusetts landlord lawfully collect in addition to first month's rent?", "a": ["A non-refundable pet fee", "A $75 application fee", "The cost of buying and installing a new lock", "A cleaning fee for the end of the tenancy"], "c": 2, "why": "Under c.186 §15B a landlord may collect only first month's rent, last month's rent, a security deposit of no more than one month's rent, and the cost of a new lock. Pet, application and cleaning fees are not on the list.", "trap": "wrong-context", "difficulty": 1, "outline": "VIII.A"}, {"id": "ma-lt-002", "part": "ma", "topic": "Landlord-Tenant", "q": "Rent is $2,400 per month. The landlord asks for first month's rent, last month's rent and a $3,000 security deposit. What is wrong?", "a": ["The security deposit may not exceed one month's rent, so $2,400 is the most allowed", "Nothing; the total is under four months' rent", "The landlord may not collect last month's rent and a deposit together", "The deposit may not exceed half a month's rent"], "c": 0, "why": "c.186 §15B caps the security deposit at one month's rent, here $2,400. First, last and a one-month deposit may all be collected together; the problem is only the deposit's size.", "trap": "math-step", "difficulty": 2, "outline": "VIII.A"}, {"id": "ma-lt-003", "part": "ma", "topic": "Landlord-Tenant", "q": "When must a landlord who takes a security deposit give the tenant a statement of the unit's condition?", "a": ["When the deposit is received, or within 10 days after the tenancy begins, whichever is later", "Within 30 days after the tenancy ends, with the deposit refund", "Only if the tenant asks for one in writing during the first month", "Within 45 days after the lease is signed by both parties"], "c": 0, "why": "c.186 §15B(2)(c) requires the statement of condition upon receipt of the deposit or within 10 days after the tenancy begins, whichever is later; the tenant then has 15 days to add to it. Thirty days after the tenancy ends is the deadline for returning the deposit.", "trap": "opposite", "difficulty": 2, "outline": "VIII.A"}, {"id": "ma-lt-004", "part": "ma", "topic": "Landlord-Tenant", "q": "Within 30 days of receiving a security deposit, the landlord must give the tenant a receipt showing:", "a": ["The bank's name and address, the account number and the amount", "The landlord's home address and Social Security number for tax purposes", "The interest rate the tenant must pay the landlord on the deposit", "The estimated cost of every repair the landlord plans for the unit"], "c": 0, "why": "c.186 §15B requires a receipt naming the bank and its address, the account number and the amount, so the tenant can track the money. The deposit must sit in a separate interest-bearing account in a Massachusetts bank.", "trap": "familiar-term", "difficulty": 2, "outline": "VIII.A"}, {"id": "ma-lt-005", "part": "ma", "topic": "Landlord-Tenant", "q": "A tenant pays a $2,000 security deposit. The landlord's bank pays 3% on the account. At the end of the first year, how much interest does the landlord owe the tenant?", "a": ["$100, because the statutory rate is always 5%", "$60, the actual rate paid by the bank", "$0, because interest is due only at move-out", "$40, at a 2% statutory rate"], "c": 1, "why": "c.186 §15B requires yearly interest at 5% or the lower rate the bank actually pays, so here 3% x $2,000 = $60. Five percent is the ceiling, not a fixed rate, so $100 overpays.", "trap": "math-step", "difficulty": 2, "outline": "VIII.A"}, {"id": "ma-lt-006", "part": "ma", "topic": "Landlord-Tenant", "q": "A tenancy ends on June 30. The landlord wants to deduct $400 for broken cabinets. To keep the deduction lawful, the landlord must, within 30 days:", "a": ["Give an itemized list signed under the pains and penalties of perjury, with bills or estimates", "Send the tenant a text message explaining the reason for the $400 deduction", "Deduct the amount and return the balance to the tenant with no other paperwork", "Get the tenant's verbal agreement to the deduction during the final walk-through"], "c": 0, "why": "c.186 §15B(4) allows deductions only for unpaid rent or water charges, certain real estate tax increases, and damage beyond normal wear and tear. For damage, the landlord must give a sworn itemized list with written estimates or bills within 30 days. A text message or verbal agreement does not meet the statute.", "trap": "too-simple", "difficulty": 2, "outline": "VIII.A"}, {"id": "ma-lt-007", "part": "ma", "topic": "Landlord-Tenant", "q": "A landlord kept a $1,800 security deposit in his personal checking account and never returned it after the tenant moved out. The tenant sues. Which outcome is possible under c.186 §15B?", "a": ["Return of the $1,800 deposit only, with no other damages available", "A fine paid to the Board of Registration, but nothing paid to the tenant", "Three times the deposit, plus interest, costs and attorney's fees", "Nothing at all, as long as the landlord returns it once he is sued"], "c": 2, "why": "Under c.186 §15B(6)-(7), for violations like failing to return the deposit or keep it in a separate account, the court shall award three times the deposit (or the balance owed), plus interest, costs and reasonable attorney's fees. Repaying after the suit is filed does not erase the violation.", "trap": "wrong-context", "difficulty": 3, "outline": "VIII.A"}, {"id": "ma-lt-008", "part": "ma", "topic": "Landlord-Tenant", "q": "An apartment building is sold while tenants' security deposits are on hold. Under c.186 §15B, which is correct?", "a": ["The deposits become the seller's property when the sale closes", "The new owner takes over the deposits and must notify tenants within 45 days", "Every tenant must pay a new security deposit to the new owner", "The security deposit rules stop applying once the building changes hands"], "c": 1, "why": "Under c.186 §15B(5) the new owner takes over responsibility for the deposits and must, within 45 days, notify tenants in writing that the deposit was transferred and is being held, with the new owner's (or agent's) name, business address and phone number. Tenants do not pay again, and the seller does not keep the money.", "trap": "opposite", "difficulty": 3, "outline": "VIII.A"}, {"id": "ma-lt-009", "part": "ma", "topic": "Landlord-Tenant", "q": "Which local body enforces the State Sanitary Code (105 CMR 410) for rental housing?", "a": ["The Massachusetts Commission Against Discrimination", "The Conservation Commission", "The local Board of Health", "The Board of Registration of Real Estate Brokers and Salespersons"], "c": 2, "why": "The local Board of Health inspects and enforces the State Sanitary Code's minimum housing standards. MCAD handles discrimination, and the Conservation Commission handles wetlands.", "trap": "familiar-term", "difficulty": 1, "outline": "VIII.B"}, {"id": "ma-lt-010", "part": "ma", "topic": "Landlord-Tenant", "q": "Under the State Sanitary Code, when may a landlord make a tenant pay for gas or electric heat?", "a": ["Whenever the landlord tells the tenant so verbally at move-in", "Whenever heating oil prices rise above the prior year's average", "Never; the landlord must always pay for heat in every rental unit", "When a written agreement says so and the unit's heat is separately metered"], "c": 3, "why": "105 CMR 410 makes the owner supply heat unless a written agreement puts it on the occupant and the unit's gas or electric heat is exclusively metered (for oil heat, a separate tank serving only that unit). A verbal statement is not enough, but \"never\" is too strong.", "trap": "too-simple", "difficulty": 2, "outline": "VIII.B"}, {"id": "ma-lic-001", "part": "ma", "topic": "Licensing Requirements", "q": "How many hours of pre-licensing education must a Massachusetts salesperson applicant complete?", "a": ["40 hours", "24 hours", "12 hours", "60 hours"], "c": 0, "why": "The current Board/PSI requirement is 40 hours of salesperson pre-license education. Twenty-four hours is an outdated figure, and 12 hours is the continuing education needed for each renewal.", "trap": "familiar-term", "difficulty": 1, "outline": "II"}, {"id": "ma-lic-002", "part": "ma", "topic": "Licensing Requirements", "q": "Which of these people needs a Massachusetts real estate license?", "a": ["An owner who is selling her own house without the help of a broker", "An attorney handling a sale for a client while practicing law", "An executor selling a home in the course of settling an estate", "A person who, for a fee, negotiates rentals of other people's apartments"], "c": 3, "why": "c.112 §87PP defines a broker as one who, for another and for a fee, negotiates sales or rentals. Owners acting for themselves, attorneys serving clients and executors are exempt under §87QQ.", "trap": "wrong-context", "difficulty": 2, "outline": "II.A"}, {"id": "ma-lic-003", "part": "ma", "topic": "Licensing Requirements", "q": "The salaried building superintendent of an apartment complex shows vacant units and takes applications for the owner. He receives no commission. Does he need a license?", "a": ["Yes; anyone who shows apartments to the public must be licensed", "Yes, unless he works fewer than 20 hours a week at the complex", "No, but only because he also lives in the complex as a tenant", "No; an owner's regular employee on the owner's property is exempt"], "c": 3, "why": "c.112 §87QQ exempts an owner's regular employees acting for the owner on the owner's property. Showing units is a brokerage act only when done for another for a fee as a business, which is why \"anyone who shows\" is too broad.", "trap": "opposite", "difficulty": 2, "outline": "II.A"}, {"id": "ma-lic-004", "part": "ma", "topic": "Licensing Requirements", "q": "A salesperson reaches her renewal date without completing her continuing education. What happens?", "a": ["Her license is revoked and she must pass the licensing exam again", "She may renew as active and then has 6 months to finish the CE", "She may renew only as inactive and cannot practice until the CE is done", "Nothing happens, because continuing education applies only to brokers"], "c": 2, "why": "Massachusetts requires 12 hours of CE before renewing as active; without it the license is renewed as inactive and she cannot perform brokerage acts. Missing CE alone does not trigger revocation or a new exam.", "trap": "too-simple", "difficulty": 2, "outline": "II.C"}, {"id": "ma-lic-005", "part": "ma", "topic": "Licensing Requirements", "q": "Jordan passes both parts of the salesperson exam on June 3, 2026. Jordan's birthday is August 20. Under the PSI/Board rules, the first license runs for no less than 2 and no more than 3 years. On which date does it expire?", "a": ["June 3, 2028", "August 20, 2028", "August 20, 2029", "June 3, 2029"], "c": 1, "why": "The issue date is the exam pass date and the license expires on the licensee's birthday, between 2 and 3 years later. August 20, 2028 is about 2 years 2.5 months out, which fits; June 3 dates use the wrong anchor, and August 20, 2029 is beyond 3 years.", "trap": "math-step", "difficulty": 2, "outline": "II.C"}, {"id": "ma-lic-006", "part": "ma", "topic": "Licensing Requirements", "q": "A licensed salesperson is convicted of a misdemeanor. Within how many days must she report the conviction to the Board?", "a": ["7 days", "90 days", "30 days", "Only at her next renewal"], "c": 2, "why": "254 CMR 3.00 requires a licensee to report a criminal conviction to the Board within 30 days. Seven days is the deadline for surrendering a suspended or revoked license, which is a different rule.", "trap": "opposite", "difficulty": 1, "outline": "II.D"}, {"id": "ma-lic-007", "part": "ma", "topic": "Licensing Requirements", "q": "Which person may sign one of the three candidate endorsements for a Massachusetts salesperson applicant?", "a": ["The applicant's aunt", "A classmate the applicant knows only from the real estate course", "The applicant's spouse", "An unrelated former coworker who lives in New Hampshire and works in Massachusetts"], "c": 3, "why": "Endorsers must be unrelated to the applicant. 254 CMR 2.00 requires them to live in or have a place of business in Massachusetts, so a New Hampshire resident who works here qualifies. Relatives and people known only from the licensing class may not sign.", "trap": "familiar-term", "difficulty": 2, "outline": "II"}, {"id": "ma-lic-008", "part": "ma", "topic": "Licensing Requirements", "q": "Maria completes her 40-hour course in March 2026. In May 2026 she passes the state portion but fails the general portion. What must she do?", "a": ["Retake both portions, because she did not pass them on the same day", "Retake only the general portion, within 2 years of her education certificate", "Retake the general portion within 30 days or lose her passing state score", "Repeat the entire 40-hour course before she is allowed to test again"], "c": 1, "why": "Under the PSI bulletin a candidate who fails one portion retakes only that portion, within the 2-year life of the education certificate. Both parts must be retaken only if the certificate expires and a new one is obtained.", "trap": "wrong-context", "difficulty": 3, "outline": "II"}, {"id": "ma-con-001", "part": "ma", "topic": "MA Contracts", "q": "In Massachusetts, a signed and accepted Offer to Purchase that contains all the essential terms and shows the parties intended to be bound:", "a": ["Is never binding, because only a P&S can bind a buyer in Massachusetts", "Can be binding even though a P&S is planned later", "Is binding only on the seller, since the buyer can still walk away", "Becomes binding only after it is recorded at the registry of deeds"], "c": 1, "why": "The MA Supreme Judicial Court (McCarthy v. Tobin, 1999) held that an accepted offer with all essential terms can be binding even if a later P&S is contemplated. Contracts like this are not recorded to become binding.", "trap": "opposite", "difficulty": 2, "outline": "IV.A"}, {"id": "ma-con-002", "part": "ma", "topic": "MA Contracts", "q": "After a P&S is signed, the buyer and seller agree to move the closing date. What is the best way to make the change?", "a": ["By a phone call between the two agents", "By the listing agent editing the document alone", "By email from the buyer only", "In writing, initialed or signed by all parties"], "c": 3, "why": "Best practice is a written extension signed or initialed by all parties, so the new deadline is clearly documented and disputes are avoided. Agents cannot change a contract on their own, and a phone call between agents leaves no record of what the parties agreed.", "trap": "too-simple", "difficulty": 1, "outline": "IV.B"}, {"id": "ma-con-003", "part": "ma", "topic": "MA Contracts", "q": "A tenant at will pays rent monthly on the 1st. The landlord delivers a written no-fault notice to quit on March 10. What is the earliest date the tenancy can end?", "a": ["March 31", "April 30", "April 9", "May 31"], "c": 1, "why": "c.186 §12 requires notice of at least the rental period or 30 days, whichever is longer, ending at the end of a rental period. Thirty days from March 10 is April 9, which is mid-period, so the tenancy ends at the end of April.", "trap": "math-step", "difficulty": 3, "outline": "IV.C"}, {"id": "ma-con-004", "part": "ma", "topic": "MA Contracts", "q": "A landlord and tenant agree orally that the tenant will rent an apartment for one year. Under Massachusetts law, the tenant MOST likely holds a:", "a": ["Tenancy for years", "Tenancy at sufferance", "Tenancy at will", "Periodic tenancy of one year"], "c": 2, "why": "Under c.183 §3, an estate or tenancy not created in writing is only a tenancy at will. A tenancy for years in MA is a written lease; tenancy at sufferance describes holding over without permission.", "trap": "familiar-term", "difficulty": 2, "outline": "IV.C"}, {"id": "ma-con-005", "part": "ma", "topic": "MA Contracts", "q": "A tenant at will receives a 14-day notice to quit for nonpayment. This is her first such notice in 12 months. How long does she have to pay all the rent owed and keep the tenancy?", "a": ["5 days after receiving the notice", "14 days after receiving the notice", "30 days after receiving the notice", "10 days after receiving the notice"], "c": 3, "why": "c.186 §12 lets a tenant at will cure by paying the full amount due within 10 days of receiving the notice, once in any 12-month period. Five days is an outdated figure still printed in some old books.", "trap": "opposite", "difficulty": 2, "outline": "IV.C"}, {"id": "ma-con-006", "part": "ma", "topic": "MA Contracts", "q": "A seller and buyer both want help completing a sale but neither wants to be represented. They sign a facilitation agreement. The licensee:", "a": ["Represents both parties as a dual agent with full fiduciary duties", "Represents the seller as a subagent through the listing broker", "Represents the buyer exclusively, as a buyer's agent would", "Assists both parties without acting as either one's agent"], "c": 3, "why": "A facilitation agreement creates a non-agency relationship: the licensee helps with the transaction but advocates for neither side. Dual agency, by contrast, means representing both sides with written consent.", "trap": "wrong-context", "difficulty": 1, "outline": "IV.F"}, {"id": "ma-con-007", "part": "ma", "topic": "MA Contracts", "q": "A renter signs a written agreement hiring a broker to find her an apartment. Whom does the broker represent?", "a": ["The landlord of any unit shown", "Both landlord and tenant automatically", "The tenant", "No one, because rentals do not create agency"], "c": 2, "why": "A tenant representation agreement makes the broker the tenant's agent. Under the rental broker-fee rule effective August 1, 2025, this licensee cannot also represent the landlord in the same rental, and rental work does create agency relationships.", "trap": "familiar-term", "difficulty": 1, "outline": "IV.D"}, {"id": "ma-con-008", "part": "ma", "topic": "MA Contracts", "q": "A seller signs a 6-month exclusive right to sell listing. In month 3, the seller finds a buyer through a neighbor and sells without the broker's help. Under the agreement:", "a": ["No commission is owed because the seller found the buyer", "Half the commission is owed", "The broker is still entitled to the commission", "The broker is owed only marketing costs"], "c": 2, "why": "Under an exclusive right to sell, the broker earns the commission no matter who finds the buyer during the term. That is the difference from an exclusive agency listing, where an owner-found buyer means no commission.", "trap": "too-simple", "difficulty": 3, "outline": "IV.E"}, {"id": "ma-env-001", "part": "ma", "topic": "Environmental", "q": "Under the Massachusetts Lead Law, an owner must delead (or bring under interim control) a home built before 1978 when:", "a": ["The home is sold", "A child under 6 lives there", "The home is refinanced", "Any tenant moves in"], "c": 1, "why": "The duty to delead is triggered by a child under 6 living in a pre-1978 home, not by a sale. A sale triggers notification forms, but not deleading by itself.", "trap": "familiar-term", "difficulty": 1, "outline": "VI.A"}, {"id": "ma-env-002", "part": "ma", "topic": "Environmental", "q": "A buyer is about to sign an offer on a 1955 house. Under Massachusetts lead law, the buyer must be given the Property Transfer Lead Paint Notification and told of the right to a lead inspection within:", "a": ["10 days", "30 days", "3 days", "90 days"], "c": 0, "why": "Before signing a binding offer on pre-1978 housing, the buyer gets the notification forms and a 10-day lead inspection right, which can be waived. Ninety days is a different deadline in the lead law, not the inspection window.", "trap": "opposite", "difficulty": 2, "outline": "VI.A.1"}, {"id": "ma-env-003", "part": "ma", "topic": "Environmental", "q": "A couple with no children applies to rent an apartment in a 1920 building. Which is correct about lead requirements?", "a": ["The landlord must still give the Tenant Lead Law Notification forms", "No lead forms are needed, because no child under 6 will live in the unit", "Only buyers, not tenants, receive lead paint notices in Massachusetts", "The landlord must fully delead the unit before any lease can be signed"], "c": 0, "why": "For rentals of pre-1978 housing, every new tenant gets the Tenant Lead Law Notification whether or not children live there. Deleading is required when a child under 6 lives there, so it is not triggered here.", "trap": "too-simple", "difficulty": 3, "outline": "VI.A.1"}, {"id": "ma-env-004", "part": "ma", "topic": "Environmental", "q": "Under Title 5, a septic system must generally be inspected:", "a": ["Within 2 years before the sale or transfer", "Within 30 days after the closing on the sale", "Every 5 years, whether or not there is a sale", "Only when the buyer's mortgage lender requires it"], "c": 0, "why": "Title 5 (310 CMR 15.301) generally requires the inspection within 2 years before a transfer of title (3 years if the system is pumped every year with records). Weather delays and certain specified transfers, such as foreclosures and bankruptcies, have special deadlines, some after the transfer, but the normal rule is before.", "trap": "familiar-term", "difficulty": 1, "outline": "VI.B"}, {"id": "ma-env-005", "part": "ma", "topic": "Environmental", "q": "Which of these events triggers a Title 5 septic inspection?", "a": ["Refinancing the existing mortgage", "Sale of the property to an unrelated buyer", "A transfer of the property between spouses", "Adding a new lender to the mortgage"], "c": 1, "why": "Title 5 inspections are triggered by a transfer of title (and by certain expansions or changes in use). Refinancing and transfers between spouses are specifically not triggers.", "trap": "wrong-context", "difficulty": 2, "outline": "VI.B"}, {"id": "ma-env-006", "part": "ma", "topic": "Environmental", "q": "A January sale is scheduled, but frozen ground makes a Title 5 inspection impossible before closing. What does Title 5 allow?", "a": ["The inspection requirement is waived entirely for winter sales", "The sale must be postponed until spring, when the inspection can be done", "It may be done up to 6 months after transfer, with written notice to the buyer", "The buyer's home inspector may do a visual inspection of the system instead"], "c": 2, "why": "310 CMR 15.301 allows the inspection up to 6 months after transfer when weather prevents it, with written notice to the buyer. It is postponed, not waived, and only a state-approved system inspector may perform it.", "trap": "opposite", "difficulty": 3, "outline": "VI.B"}, {"id": "ma-env-007", "part": "ma", "topic": "Environmental", "q": "Before a Massachusetts single-family home is sold, what is required for smoke and carbon monoxide alarms?", "a": ["A self-certification signed by the seller under oath", "A certificate of compliance from the local fire department", "An inspection report from the buyer's home inspector", "A letter of approval from the State Board of Health"], "c": 1, "why": "Under c.148 §26F and §26F½, the local fire department inspects and issues a certificate showing compliant smoke and CO alarms before transfer. A seller's own statement or a private home inspection does not replace it.", "trap": "too-simple", "difficulty": 2, "outline": "VI.C"}, {"id": "ma-env-008", "part": "ma", "topic": "Environmental", "q": "A buyer wants to build an addition 150 feet from a perennial river in a suburban town. Which body reviews the work, and why?", "a": ["The local Board of Health, because the addition is close to surface water", "MCAD, because public access to rivers must be preserved for everyone", "The Conservation Commission, since it is within the 200-foot riverfront area", "No review is needed, because the work is more than 100 feet from the river"], "c": 2, "why": "Under the Wetlands Protection Act as amended by the 1996 Rivers Protection Act, most perennial rivers have a 200-foot riverfront area, and work there is reviewed by the Conservation Commission. The 100-foot figure is the wetlands buffer zone, not the riverfront area.", "trap": "familiar-term", "difficulty": 2, "outline": "VI.D"}, {"id": "ma-bd-001", "part": "ma", "topic": "Board Duties and Powers", "q": "Which of these may the Board of Registration of Real Estate Brokers and Salespersons do?", "a": ["Set the commission rate brokers charge", "Inspect a broker's escrow account and records", "Decide commission disputes between two brokers", "Prosecute unlicensed people for criminal penalties"], "c": 1, "why": "The Board may examine brokerage records, including escrow funds. It does not set commissions (which are negotiable), and unlicensed activity is pursued by the Attorney General.", "trap": "familiar-term", "difficulty": 1, "outline": "I.A.1"}, {"id": "ma-bd-002", "part": "ma", "topic": "Board Duties and Powers", "q": "Which of the following is NOT a sanction the Board may impose on a licensee?", "a": ["Imprisonment", "A fine", "Probation", "Suspension or revocation of the license"], "c": 0, "why": "The Board's sanctions include fines, probation, suspension and revocation. Imprisonment can only come from a criminal court, not a licensing board.", "trap": "opposite", "difficulty": 2, "outline": "I.B"}, {"id": "ma-bd-003", "part": "ma", "topic": "Board Duties and Powers", "q": "A person with no license advertises himself as a real estate broker and collects fees for arranging sales. Which statement is correct?", "a": ["The Board may revoke his license after a formal hearing on the charges", "He faces a fine of up to $500 and cannot sue for a commission", "The Board may only issue a written warning to unlicensed people", "He may keep the fees if he gets a license within 90 days of the deal"], "c": 1, "why": "c.112 §87CCC punishes unlicensed brokerage with a fine of up to $500, and a person unlicensed when the work was done cannot sue for a commission. The Board cannot revoke a license that does not exist.", "trap": "wrong-context", "difficulty": 2, "outline": "I.B"}, {"id": "ma-bd-004", "part": "ma", "topic": "Board Duties and Powers", "q": "When may the Board of Registration investigate a licensee's conduct?", "a": ["On its own initiative, and it must on a verified written complaint", "Only after a court has found the licensee liable to a consumer", "Only when the Attorney General refers a case to the Board", "Only during the licensee's renewal period, every two years"], "c": 0, "why": "The Board may investigate on its own authority, and must look into a verified written complaint from an aggrieved person. It does not need a court ruling or an AG referral first.", "trap": "too-simple", "difficulty": 2, "outline": "I"}, {"id": "ma-bd-005", "part": "ma", "topic": "Board Duties and Powers", "q": "At renewal, a salesperson certifies that she completed 12 hours of continuing education. A Board audit shows she completed none. Which is MOST likely?", "a": ["Nothing happens, because CE completion is checked only for brokers", "Only her supervising broker is disciplined, since he oversees her renewal", "She simply renews as inactive, with no other consequence for her", "The Board may discipline her for the false certification"], "c": 3, "why": "Falsely certifying CE is a violation the Board can sanction, separate from the CE shortfall itself. Renewing as inactive is the result of honestly not completing CE, not of lying about it.", "trap": "wrong-context", "difficulty": 3, "outline": "I.B.2"}, {"id": "ma-add-001", "part": "ma", "topic": "Additional MA Topics", "q": "A buyer of a unit in a cooperative usually receives:", "a": ["A unit deed and an undivided interest in the land", "Shares of stock in the corporation and a proprietary lease", "A deed to a specific week of use", "A fee simple title to the apartment only"], "c": 1, "why": "Co-op owners own stock in the corporation that owns the building and hold a proprietary lease to their unit. A unit deed with an undivided interest in the common areas describes a condominium.", "trap": "familiar-term", "difficulty": 1, "outline": "IX.A"}, {"id": "ma-add-002", "part": "ma", "topic": "Additional MA Topics", "q": "At the closing of a condominium resale, what does a 6(d) certificate under c.183A show?", "a": ["Whether the unit's condo fees are paid, or how much is owed", "That the unit passed its smoke and carbon monoxide inspection", "The unit's percentage interest in the common areas of the condominium", "That the seller has paid all of the municipal property taxes due"], "c": 0, "why": "The c.183A §6(d) certificate from the association states whether condo fees are paid. Recording it protects the buyer from the association's lien for unpaid fees. The percentage interest is set in the master deed.", "trap": "wrong-context", "difficulty": 2, "outline": "IX.A"}, {"id": "ma-add-003", "part": "ma", "topic": "Additional MA Topics", "q": "Under Massachusetts c.183A, a condominium is created when:", "a": ["The bylaws are approved by the town", "The first unit buyer obtains a mortgage", "The developer files a plan with the Board of Registration", "The master deed is recorded at the registry of deeds"], "c": 3, "why": "A condominium comes into existence when the master deed, with plans, is recorded under c.183A. The Board of Registration licenses agents and has no role in creating a condominium.", "trap": "opposite", "difficulty": 2, "outline": "IX.A"}, {"id": "ma-add-004", "part": "ma", "topic": "Additional MA Topics", "q": "A legal description reads: \"Beginning at a stone bound on the easterly side of Elm Street, thence northerly 120 feet... to the point of beginning.\" This is a:", "a": ["Lot and block description", "Street address description", "Metes and bounds description", "Rectangular survey description"], "c": 2, "why": "Metes and bounds descriptions start at a point of beginning and follow distances and directions back to it. This is the traditional Massachusetts method. Lot and block refers to a recorded subdivision plan, and the rectangular survey system is not used in MA.", "trap": "familiar-term", "difficulty": 1, "outline": "IX.B"}];
const SCHOOL = {"name": "Metropolitan School of Real Estate", "shortName": "Metropolitan", "state": "Massachusetts", "stateCode": "MA", "colors": {"accent": "#42D0F8", "accentLight": "#42D0F8", "primary": "#16203A", "slate": "#4A5370", "ink": "#16203A", "paper": "#F7F6F2", "muted": "#4A5370", "line": "#DEDCD7", "tint": "#E8F8FE"}, "logo": "img/metro-icon.svg", "heroImage": "img/hero.png", "instructor": {"name": "Michael Albano", "quotes": ["You don't run a marathon to get ready for a marathon."]}, "guessLetter": "C", "passPercent": 70, "tips": ["Pass 1: answer only the questions you are sure of. Flag the rest and keep moving.", "Pass 2: go back to the flagged ones. Many look easier the second time.", "Pass 3: take the 50/50s. Cross out what you know is wrong and pick the better of the two left.", "Last: if you still don't know, pick the same letter every time. Never leave a blank.", "Watch the clock, not the question. If one question takes more than two minutes, flag it and move on.", "The second half is where people fade. Slow, even breathing and a quick stretch help you stay sharp.", "Read the last line of the question first, so you know what you are looking for.", "Words like 'except', 'not' and 'always' change the answer. Slow down when you see them."], "classSchedule": [], "readingList": [{"title": "Your class textbook (the blue book)", "note": "Missed a question? Read only that topic in the book, then try the drill again."}], "examSite": "The exam is given on a computer at a PSI test center. Bring your ID, arrive early, and expect an on-screen calculator.", "contact": {"name": "Metropolitan School of Real Estate", "phone": "617-201-0402", "email": "school@metropolitanbre.com"}, "icon": {"svg": "img/metro-icon.svg", "png": "img/metro-icon-180.png"}};
const BUILD_INFO = {"files": ["gen-contracts-agency.json", "gen-own-land-val-fin.json", "gen-practice-title-math.json", "ma-all.json"], "count": 337, "sample": false};
